import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`ディスパッチの有効化、バックエンドの選択、許可する対象エージェントの制限、ストリーミングされるターンの投影動作の選択を行うためのACPランタイム制御。`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`ACPで許可するエージェント`},help:{"v1-f2mw0d-3a":`ACPランタイムセッションで許可する対象エージェントIDの許可リスト。空の場合、許可リストによる追加の制限はありません。`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACPバックエンド`},help:{"v1-1s1l6bz-2v":`デフォルトのACPランタイムバックエンドID（例：acpx）。登録済みのACPランタイムプラグインのバックエンドと一致する必要があります。`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`ACPのデフォルトエージェント`},help:{"v1-7donnu-2c":`ACPの生成時に対象が明示的に指定されていない場合に使用する、フォールバック先の対象エージェントID。`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACPディスパッチを有効化`},help:{"v1-1ug9t9m-3w":`ACPセッションのターンに対する独立したディスパッチ制御（デフォルト：true）。falseに設定すると、ACPコマンドを利用可能なまま、ACPターンの実行をブロックします。`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACPを有効化`},help:{"v1-1uonl1v-2a":`ACP機能全体の有効・無効を制御します。ACPランタイムとポリシーが設定されていない場合は、無効のままにしてください。`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`ACP フォールバックバックエンド`},help:{"v1-1wvdifq-5m":`プライマリバックエンドが UNAVAILABLE（例：レート制限／クォータ超過）で失敗したときに試行する、フォールバック先の ACP バックエンド ID の順序付きリスト。各エントリは、登録済みの ACP ランタイムプラグインのバックエンドと一致する必要があります。`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`ACP ランタイムのインストールコマンド`},help:{"v1-1jjuv9m-39":"ACP バックエンドの接続設定がない場合に、`/acp install` と `/acp doctor` が表示する、運用担当者向けの任意のインストール／セットアップコマンド。"}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP ストリーム`},help:{"v1-1bka5p-2v":`ACP ストリーミングの表示出力に関する制御設定。チャンクサイズ、メタデータの表示、重複を除去した配信の動作を制御します。`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`ACP ストリーム配信モード`},help:{"v1-19gdmx1-3s":`ACP の配信方式：live は表示用の出力を逐次ストリーミングし、final_only はターン終了イベントまで ACP の表示用出力をすべてバッファリングします。`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`ACP ストリームの繰り返し抑制`},help:{"v1-manh32-3d":`true（デフォルト）の場合、生の ACP イベントは変更せずに、ターン内で繰り返される ACP ステータス／ツールの表示行を抑制します。`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`ACP ストリームのタグ表示`},help:{"v1-1ybhx22-34":`ACP の表示出力に対する sessionUpdate ごとの表示設定の上書き（例：usage_update、available_commands_update）。`}},agents:{label:{"v1-1sa8ub3-6":`エージェント`},help:{"v1-2rc4v8-55":`エージェントランタイム設定のルート。ルートと同階層の項目はインフラストラクチャとエージェント共通のデフォルト設定を管理し、agents.defaults はエージェントループの動作を管理します。対応している場合、各エージェントのエントリでどちらの設定も上書きできます。`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`エージェントのデフォルト設定`},help:{"v1-1af7k5b-5a":`agents.entries の各エントリで上書きされない限り、エージェントが継承する共通のデフォルト設定です。デフォルト設定を使用すると、一貫した基本動作を適用し、エージェントごとの設定の重複を減らせます。`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`認証継承先`},help:{"v1-2d16wl-2x":`認証情報がエージェントごとに移動されるまで、アップグレード時の互換性を維持するための、継承される認証情報ストアの所有者です。`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`認証継承元の所有者`},help:{"v1-1a1s7nm-4s":`デフォルトマーカーの廃止後も、従来の認証情報ストアが継承元として使用されるエージェントです。以前の所有者が main ではなかった場合、アップグレード時に自動的に書き込まれます。`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`ブートストラップの最大文字数`},help:{"v1-drlo3i-37":`システムプロンプトに挿入される各ワークスペースのブートストラップファイルの最大文字数です。超過分は切り詰められます（デフォルト：20000）。`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`ブートストラップの合計最大文字数`},help:{"v1-1evwsjb-2c":`挿入されるすべてのワークスペースのブートストラップファイルの合計最大文字数です（デフォルト：60000）。`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`圧縮`},help:{"v1-1qxdwz8-5p":`コンテキストがトークン上限に近づいたときの圧縮動作を設定します。圧縮方式や圧縮前のメモリ書き出し動作が含まれます。限られたコンテキストウィンドウで、長時間のセッションの継続性を安定して維持する必要がある場合に使用してください。`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`組み込みの自動圧縮`},help:{"v1-1et7vwu-5l":`組み込みの予防的な自動圧縮を有効にします（デフォルト: true）。false に設定すると、OpenClaw のオーバーフロー回復、事前圧縮、手動の /compact を維持したまま、しきい値に基づく組み込み圧縮を停止します。`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`圧縮時の識別子ポリシー`},help:{"v1-hby01l-4l":`圧縮要約での識別子保持ポリシーです。"strict" は、不透明な識別子を保持するための組み込みガイダンスを先頭に追加します（デフォルト）。"off" は、この追加を無効にします。`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`圧縮時に保持する直近のトークン数`},help:{"v1-tgysub-5h":`圧縮時に直近の会話ウィンドウから保持する最小トークン数です。値を大きくすると直近の文脈の連続性を保ちやすくなり、小さくすると古い履歴をより多く保持できます。`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`圧縮を開始するアクティブな会話記録のサイズしきい値`},help:{"v1-u715n1-90":`モデルに提示される会話記録のウィンドウ（最後の圧縮またはリセット以降）がこのサイズに達すると、通常の事前ローカル圧縮を実行するバイト数のしきい値です。バイト数または "20mb" などの文字列で指定します。0 に設定するか未設定のままにすると無効になります。Codex app-server のネイティブロールアウト記録のサイズも制限します。サイズ超過のネイティブスレッドは、新規の状態で再開されます。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`圧縮前のメモリフラッシュ`},help:{"v1-18q0ve9-55":`大幅な圧縮の前に、エージェントによるメモリへの書き込みを実行する、圧縮前のメモリフラッシュ設定です。長いセッションでは有効のままにしておくと、大幅な切り詰めの前に重要な文脈が永続化されます。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`コンパクション時のメモリフラッシュを有効化`},help:{"v1-9xllgp-5o":`トークン上限に近づき、ランタイムが履歴を大幅に削減する前に、コンパクション前のメモリフラッシュを実行します。制約のある環境でメモリへの副作用を意図的に無効にする場合を除き、有効のままにしてください。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`コンパクション時のメモリフラッシュの会話記録サイズしきい値`},help:{"v1-1rzov1e-93":`モデルから参照できる会話記録の範囲がこのしきい値（バイト数または "2mb" などの文字列）に達すると、コンパクション前のメモリフラッシュを強制的に実行します。コンパクション後は、破棄された履歴ではなく、保持された末尾部分とそれ以降のターンが対象になります。トークンカウンターが更新されていない場合でも、長時間のセッションでハングが発生するのを防ぐために使用します。無効にするには 0 に設定してください。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`コンパクション時のメモリフラッシュのモデル上書き`},help:{"v1-1r3ctyu-7w":`コンパクション前のメモリフラッシュのターンでのみ使用する、任意のプロバイダー／モデルの上書き設定です。永続メモリの抽出にアクティブなセッションの有料モデルを使いたくない場合は、ollama/qwen3:8b などのローカルモデルを設定してください。指定したモデルがそのまま使用され、アクティブなモデルのフォールバックチェーンは継承されません。`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`コンパクション時のメモリフラッシュのソフトしきい値`},help:{"v1-1dqo2l1-5c":`コンパクションまでの残りトークン数がこのしきい値に達すると、コンパクション前のメモリフラッシュが実行されます。より確実に永続化するには早めに実行されるしきい値を、フラッシュの頻度を抑えるにはコンパクションに近いしきい値を使用してください。`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`圧縮のターン途中事前チェック`},help:{"v1-am6gbh-6x":`組み込みの OpenClaw ツールループで、ツール結果の追加後、次のモデル呼び出しの前にコンテキスト容量の逼迫を検出する、任意の事前チェックです。有効にすると、OpenClaw は既存の事前チェックの復旧処理を再利用し、再試行前にツール結果を切り詰めるか、圧縮を行います。`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`圧縮のターン途中事前チェックを有効化`},help:{"v1-engbwe-5u":`組み込みの OpenClaw ツールループで、ターン途中のコンテキスト容量の逼迫を構造的にチェックします。既定値：false。ツールを多用する長時間のセッションで、通常のターン終了時の圧縮が実行される前にコンテキスト容量を超過する場合を除き、無効のままにしてください。`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`圧縮モード`},help:{"v1-1unahwc-76":`圧縮方式のモード："safeguard"（未設定時に適用される既定値）は直近のコンテキストを保持するための保護措置を適用します。一方、"default" は保護措置なしの基本的な要約を使用します。safeguard による要約がお使いのプロバイダーで問題を引き起こす場合にのみ、"default" を設定してください。`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`圧縮モデルの上書き`},help:{"v1-cfeys9-6q":`圧縮用の要約にのみ使用する、任意の provider/model または設定済みの単独エイリアスです。単独エイリアスは送信前に解決されます。設定済みのリテラルなモデル ID がエイリアスと競合する場合は、モデル ID が優先されます。プライマリエージェントのモデルを引き続き使用するには、未設定のままにしてください。`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`圧縮時にユーザーへ通知`},help:{"v1-lvymm8-bv":`有効にすると、コンテキストのメンテナンスに関する簡潔な通知をユーザーに送信します。圧縮の開始時と完了時（例：「🧹 コンテキストを圧縮中...」「🧹 圧縮が完了しました」）、および圧縮前のメモリフラッシュが試行上限に達し、機能が低下した状態で返信を続ける場合（例：「⚠️ メモリのメンテナンスが一時的に失敗しました。返信を続けます。」）に通知します。コンテキストのメンテナンスを通知せず、ユーザーの操作を妨げないよう、デフォルトでは無効になっています。`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`圧縮後のコンテキストセクション`},help:{"v1-1n0ln2u-5f":`圧縮後に再挿入する AGENTS.md の H2/H3 セクション名を明示的に指定します。再挿入を無効にするには、未設定のままにするか [] を設定してください。従来のデフォルトの組み合わせを有効にするには、["Session Startup", "Red Lines"] を明示的に設定してください。`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`圧縮後のインデックス同期`},help:{"v1-ekpjeq-6l":`圧縮後のセッションメモリのインデックス再作成モードを制御します。指定できる値は "off"、"async"、"await" です（デフォルト："async"）。最新の状態を最優先する場合は "await"、圧縮の待ち時間を短縮する場合は "async" を使用してください。"off" は、セッションメモリの同期を別の仕組みで処理している場合にのみ使用してください。`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`圧縮プロバイダー`},help:{"v1-kiwk91-86":`要約に使用する、登録済みの圧縮プロバイダープラグインの ID です。設定されており、プロバイダーが登録済みの場合は、組み込みの summarizeInStages パイプラインの代わりに、そのプロバイダーの summarize() メソッドが呼び出されます。プロバイダーで障害が発生した場合は、組み込みの処理に切り替わります。デフォルトの組み込み要約を使用するには、未設定のままにしてください。`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`圧縮品質ガード`},help:{"v1-u9ognp-4k":`セーフガード圧縮の要約に対する品質監査の再試行設定です。セーフガードモードではデフォルトで有効です。要約の監査と再生成をスキップするには、enabled: false を設定してください。`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`圧縮の品質ガードを有効化`},help:{"v1-1xk2vt3-36":`セーフガード圧縮で要約の品質監査と再生成の再試行を有効にします。デフォルト：セーフガードモードでは true。`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`圧縮の品質ガードの最大再試行回数`},help:{"v1-n7l46y-3y":`セーフガード要約の品質監査に不合格となった場合の、再生成の最大再試行回数です。追加の遅延とトークンコストを抑えるには、小さい値を使用してください。`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`圧縮時に保持する直近のターン数`},help:{"v1-y34ihi-5k":`セーフガードの要約対象から除外し、原文のまま保持する直近のユーザー／アシスタントのターン数です（デフォルト：3）。直近の対話の文脈を正確に保持するには値を増やし、圧縮による節約効果を最大化するには値を減らしてください。`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`圧縮時の思考レベル`},help:{"v1-1vafgaw-g1":`OpenClaw の組み込みコンパクション要約でのみ使用する思考レベル："off"、"minimal"、"low"、"medium"、"high"、"xhigh"、"adaptive"、"max"、"ultra"、または "inherit"。デフォルトではプロバイダーのコンパクション推奨設定を使用し、推奨設定がない場合は "low" を使用します。ネイティブのローカル Ollama では "off" が優先されます。セッションのレベルを再利用するには "inherit" を設定してください。明示的な設定はプロバイダーのデフォルトより優先され、選択したレベルは実際のコンパクションモデル／ランタイムが対応する範囲に制限されます。ネイティブの Codex app-server コンパクションでは、compact リクエストに操作ごとの思考レベルの上書き指定がないため、この設定は無視され、OpenClaw が警告をログに記録します。`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`コンパクションのタイムアウト（秒）`},help:{"v1-2bhn29-7m":`組み込みコンパクションモデルへの各リクエストに対する、安全のための制限時間（秒、デフォルト：180）。複数段階のコンパクションでは、順次実行される各リクエストの開始時に制限時間がリセットされるため、コンパクション全体にはそれ以上の時間がかかる場合があります。プラグインが処理するコンパクションでは、操作全体に対して1回分の制限時間が適用されます。`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`コンテキストの挿入`},help:{"v1-u18x0-7u":`組み込みランタイムでのワークスペースのブートストラップファイルの注入を制御します。"always" は通常の注入を行います（デフォルト）。"continuation-skip" は、完全なブートストラップを行ったターンが記録された後、対象となる継続ターンでの注入をスキップします。"never" は注入を無効にします。CLIを使用したプロンプトの準備には影響しません。`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`デフォルトのコンテキスト制限`},help:{"v1-1coeez8-5d":`特定の大容量の抜粋と挿入されるプロンプトブロックを対象とする、エージェントごとのコンテキスト容量のデフォルト設定です。制限のない呼び出し経路を再び有効にすることなく、読み取り／挿入サイズの上限を調整できます。`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`memory_get のデフォルト最大文字数`},help:{"v1-1qb40qv-4v":`切り詰めのメタデータと続きの通知が追加される前に、memory_get が返すデフォルトの最大文字数です。以前のように大きな抜粋を取得するには値を増やしますが、適切な上限を設けてください。`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`圧縮後のデフォルト最大文字数`},help:{"v1-64qo8g-5r":`圧縮後にコンテキストを更新するための挿入時に、AGENTS.md から保持するデフォルトの最大文字数です。圧縮からの復元コストを抑えるには値を下げ、長い起動時ガイダンスに依存するエージェントでは値を上げてください。`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`作業ディレクトリ`},help:{"v1-1y8wlxn-6a":`エージェントの応答実行用の作業ディレクトリです。ワークスペースの初期設定ファイルやメモリファイルとは別に指定します。エージェント固有の cwd とセッション生成時の cwd が優先されます。~ と相対パスをサポートします。別の cwd を使用するには、サンドボックス外での実行が必要です。`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`判断モデル`},help:{"v1-7nd7ze-64":`型付きの選択肢、スコア、真偽値の確率に使用する任意のプロバイダー/モデルです。未設定または空の場合、判断呼び出しは無効になります。対応プラグインは、範囲を限定したタスクの判断材料をこのプロバイダーに送信します。チャットモデルとユーティリティモデルは変更されません。`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`組み込み OpenClaw`},help:{"v1-1keek32-3k":`OpenClaw セッションでワークスペース内のエージェント設定をどのように信頼し適用するかを制御する、組み込み OpenClaw ランナーのセキュリティ強化設定です。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`サイバーポリシーのフェイルオーバー`},help:{"v1-xvv6wl-2r":`組み込みランタイムでOpenAIのサイバーポリシーによる拒否が発生した際、安全に再実行できる場合にDaybreakへ自動エスカレーションします。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`サイバーポリシーのフェイルオーバー待機時間`},help:{"v1-16smtrl-25":`現在のセッションで、利用できないエスカレーション先をスキップする期間。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`サイバーポリシーのフェイルオーバーモード`},help:{"v1-rzsd2b-2h":`自動エスカレーションを有効にする（"auto"、デフォルト）か、プロバイダーによる拒否で処理を終了する（"off"）かを設定します。`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`サイバーポリシーのフェイルオーバーモデル`},help:{"v1-1aaj8nn-1t":`サイバーポリシーによる自動エスカレーション先として使用するプロバイダー／モデル。`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`組み込み OpenClaw の実行契約`},help:{"v1-1fch2ig-66":`組み込み OpenClaw の実行契約です。"default" は標準のランナー動作を維持し、"strict-agentic" は対応する OpenAI/OpenAI Codex GPT-5 ファミリーの実行で、構造化された計画追跡と非表示のターン復旧を有効にします。`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`組み込み OpenClaw のプロジェクト設定ポリシー`},help:{"v1-fdyy04-65":'埋め込み OpenClaw がワークスペース内の `.openclaw/settings.json` を処理する方法です。"sanitize"（デフォルト）は shellPath/shellCommandPrefix を削除し、"ignore" はプロジェクト設定を完全に無効化し、"trusted" はプロジェクト設定をそのまま適用します。'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`実験的なエージェントフラグ`},help:{"v1-cvv5cl-2w":`エージェントのデフォルト設定に適用する実験的なフラグです。プレビュー機能を意図的にテストする場合を除き、オフにしてください。`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`軽量ローカルモデルモードを有効化（実験的）`},help:{"v1-gj06u6-7b":`browser、automations、messageなどのオプションツールを制限する、トラブルシューティング用の詳細なオーバーライド設定です。デフォルトでは無効です。対応するローカルランタイムでは、この制限なしで自動Tool Searchを使用します。明示的に許可されたツールと、配信に必要なツールは維持されます。`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`エージェントのデフォルト高速モード`},help:{"v1-zv4y98-2z":`エージェントループのデフォルトの高速モードポリシーです（"auto"、true、false）。個々のエージェント設定で上書きされます。`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`ハートビートエージェント`},help:{"v1-1jynxej-3w":`エージェントごとのハートビート設定がない場合に、バックグラウンドのハートビート実行を担当するエージェントです。設定済みのデフォルトルーティングを維持するには、未設定のままにしてください。`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`ハートビートのダイレクト送信ポリシー`},help:{"v1-nhyxa9-41":`ハートビートの配信先にダイレクトチャットや DM を指定できるかどうかを制御します。"allow"（デフォルト）は DM への配信を許可し、"block" はダイレクト宛ての送信を抑止します。`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`ハートビートのタイムアウト（秒）`},help:{"v1-1se21py-5f":`ハートビートのエージェントターンが中止されるまでの最大許容時間（秒）。未設定の場合、agents.defaults.timeoutSeconds が設定されていればその値を使用し、それ以外の場合はハートビートの実行間隔を使用します（上限600秒）。`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`人間らしい応答遅延の最大値（ms）`},help:{"v1-vnmvli-1m":`カスタム humanDelay の最大遅延時間（ms、デフォルト：2500）。`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`人間らしい応答遅延の最小値（ms）`},help:{"v1-5nrtr5-1l":`カスタム humanDelay の最小遅延時間（ms、デフォルト：800）。`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`人間らしい応答遅延のモード`},help:{"v1-k7hyg3-1n":`ブロック単位の返信に適用する遅延方式（"off", "natural", "custom"）。`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`画像の最大寸法（px）`},help:{"v1-vju8x-2u":`会話記録やツール結果の画像ペイロードをサニタイズする際の、画像の辺の最大長（ピクセル、デフォルト：1200）。`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`画像モデルのフォールバック`},help:{"v1-1kgx5i9-1b":`優先順に並べたフォールバック画像モデル（provider/model）。`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`画像モデル`},help:{"v1-dstqyh-2c":`プライマリモデルが画像入力に対応していない場合に使用する任意の画像モデル（provider/model）。`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`画質`},help:{"v1-1uyxc5s-6u":`画像ツールのメディア圧縮設定："auto" はプロバイダーやモデルの制限と画像数に応じて調整し、"efficient" はトークン数とバイト数を削減し、"balanced" は現在のバランスを維持し、"high" はスクリーンショットや文書画像の細部をより多く保持します。`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`画像生成モデルのフォールバック`},help:{"v1-oljfk4-1m":`優先順に並べたフォールバック用の画像生成モデル（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`画像生成モデル`},help:{"v1-g4yw0h-2o":`共通の画像生成機能で使用する任意指定の画像生成モデル（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`画像生成のタイムアウト（ms）`},help:{"v1-9yesfj-31":`image_generate 呼び出し時のプロバイダーへのリクエストに適用するデフォルトのタイムアウト（ミリ秒）。呼び出しごとの timeoutMs でこの値を上書きできます。`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`音楽生成モデルのフォールバック`},help:{"v1-wyg9xe-1m":`優先順に並べたフォールバック用の音楽生成モデル（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`音楽生成モデル`},help:{"v1-xs1e2h-2o":`共通の音楽生成機能で使用する任意指定の音楽生成モデル（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`動画生成モデルのフォールバック`},help:{"v1-wpbf1e-1m":`優先順に並べたフォールバック用の動画生成モデル（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`動画生成モデル`},help:{"v1-hfmlbl-2o":`共通の動画生成機能で使用する任意の動画生成モデル（provider/model）。`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`動画生成のタイムアウト（ms）`},help:{"v1-1bqj80s-4i":`video_generate 呼び出しでのプロバイダーへのリクエストのデフォルトタイムアウト（ミリ秒）。呼び出しごとの timeoutMs がこの値より優先され、この値はプロバイダーが定めたデフォルト値より優先されます。`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`フォールバックモデル`},help:{"v1-t4djq2-24":`優先順に並べたフォールバックモデル（provider/model）。プライマリモデルが失敗した場合に使用されます。`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`プライマリモデル`},help:{"v1-1i8a1v4-v":`プライマリモデル（provider/model）。`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`モデルポリシー`},help:{"v1-z0txb7-2e":`モデルの上書きに関する明示的なポリシー。すべてのモデルを許可するには、この設定を省略するか、allow を空にしてください。`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`許可するモデル`},help:{"v1-1fqace-3x":`上書き先として許可するモデルの参照。エイリアス、完全な "provider/model" 形式の参照、および "openai/*" などのプロバイダーワイルドカードを指定できます。空の場合はすべてのモデルを許可します。`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`モデル`},help:{"v1-13cvq23-4i":`設定済みのモデルカタログとモデルごとの設定。各エントリには、エイリアス、パラメーター、ランタイムメタデータ、Code Mode の上書き設定を指定できます。モデルの上書きを制限するものではありません。`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`デフォルトエージェントのモデルランタイム`},help:{"v1-6km9kx-41":`デフォルトエージェントのモデルごとのランタイムポリシー（任意）。エージェント全体のランタイムを設定する代わりに、モデル固有のランタイム例外を指定する場合に使用します。`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`デフォルトエージェントのモデルランタイムID`},help:{"v1-1co96w7-4a":`デフォルトエージェントのモデルランタイムID："openclaw"、"auto"、"codex"などの登録済みプラグインハーネスID、または"claude-cli"などのサポートされているCLIバックエンドエイリアス。`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`コードモード`},help:{"v1-rsdl5o-6x":`このプロバイダーとモデルの組み合わせに対するOpenClaw Code Modeの設定です。オンにすると強制的に有効になり、オフにすると無効になります。デフォルトではtools.codeMode.enabledを継承します。エージェント固有の有効化設定が優先されます。選択したランタイムやCodexネイティブのCode Modeは変更されません。`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`モデル選択の適用範囲`},help:{"v1-sj8owq-bl":`適用範囲が明示されていないチャットコマンドとGatewayセッションのモデル更新に使用する範囲です。"session"（デフォルト）は現在のセッションのみを変更し、"agent"はそのエージェントのプライマリモデルも更新し、"global"は共有のagents.defaults.modelフォールバックも更新します。明示的な範囲フラグが優先されます。設定済みのデフォルト値への書き込みには、所有者または管理者の権限が必要です。Telegramのコールバック選択UIと組み込みのローカルTUIでは、引き続きセッションのみに適用されます。`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`PDFの最大サイズ（MB）`},help:{"v1-1uig1dr-1u":`PDFツールで扱えるPDFファイルの最大サイズ（メガバイト単位、デフォルト：10）。`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`PDFの最大ページ数`},help:{"v1-11na7hp-1y":`PDFツールで処理するPDFの最大ページ数（デフォルト：20）。`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`PDFモデルのフォールバック`},help:{"v1-89ebd8-19":`優先順に並べたフォールバック用PDFモデル（provider/model）。`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDFモデル`},help:{"v1-2ktkxt-2y":`PDF解析ツール用の任意のPDFモデル（provider/model）。未指定の場合はimageModelを使用し、それも未指定の場合はセッションモデルを使用します。`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`リポジトリルート`},help:{"v1-j3sh74-2h":`システムプロンプトのランタイム行に表示する任意のリポジトリルート（自動検出を上書きします）。`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`サンドボックスブラウザーのCDP送信元ポート範囲`},help:{"v1-1jkowdc-2b":`コンテナ境界でのCDP受信に適用する任意のCIDR許可リスト（例：172.21.0.1/32）。`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`サンドボックスブラウザーのネットワーク`},help:{"v1-8m74ud-5w":`サンドボックスブラウザーコンテナ用のDockerネットワーク（デフォルト：openclaw-sandbox-browser）。専用のデフォルトネットワークまたはカスタムブリッジネットワークを使用してください。ブラウザーの制御には公開されたCDPポートが必要なため、"none"はサポートされていません。`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`サンドボックスDockerでコンテナ名前空間への参加を許可`},help:{"v1-qm39de-4c":`サンドボックスのDockerネットワークモードcontainer:<id>を許可する、緊急時用の危険なオーバーライドです。別のコンテナの名前空間に参加するため、サンドボックスの分離が弱まります。`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`サンドボックスのDocker GPU`},help:{"v1-jj0yhw-4k":`--gpusに渡す任意のDocker GPUパススルー値です。例："all"、"device=GPU-uuid"。NVIDIA Container Toolkitなどの互換性のあるホストランタイムが必要です。`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`レガシーセッションストアの対象`},help:{"v1-1xkej6i-2g":`廃止されたmain-agent行および固定のレガシーセッションストアについて、アップグレード時の互換性を維持するための所有者です。`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`レガシーセッションストアの所有者`},help:{"v1-ommm7e-5w":`デフォルトマーカーの廃止後に、固定のレガシーセッションストア内の廃止されたmain-agent行またはスコープ未指定の行を所有するエージェントです。以前の所有者がmainでも唯一のエージェントでもなかった場合、アップグレード時に自動的に書き込まれます。`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`agents.entries.*.skillsを省略したエージェントが継承する、任意のデフォルトスキル許可リストです。スキルを制限しない場合は省略し、継承するエージェントにスキルを一切付与しない場合は[]を設定します。明示的に指定したagents.entries.*.skillsは、このデフォルトと統合されず、置き換える点に注意してください。`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`ワークスペースのブートストラップ作成をスキップ`},help:{"v1-kbstgw-5v":`ワークスペースのブートストラップファイルの自動作成をスキップします。既存ファイルの注入はスキップしません。組み込みランタイムで注入を無効にするには、agents.defaults.contextInjection を "never" に設定してください。ただし、エージェントごとの設定で上書きされる場合があります。`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`スキップする任意のブートストラップファイル`},help:{"v1-1j2z4yj-4c":`エージェントのワークスペースに作成しない任意のブートストラップファイルです。有効な値：SOUL.md、USER.md、IDENTITY.md（HEARTBEAT.mdも指定できますが、効果はありません）。`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`起動時のコンテキスト`},help:{"v1-1ugsihy-5o":`引数なしの「/new」と「/reset」に対して、ランタイムが最初のターンに付加する導入コンテキストです。何を読むかをモデルに判断させる代わりに、最近の日次メモリファイルを最初のプロンプトに事前読み込みするかどうかを制御します。`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`起動時コンテキストの適用対象`},help:{"v1-wav4a5-36":`起動時コンテキストを適用する引数なしのリセットコマンドを選択します。"new"、"reset"、または両方を指定します（デフォルト: ["new","reset"]）。`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`起動時コンテキストの日次メモリ日数`},help:{"v1-4i5xcm-3p":`設定されたユーザーのタイムゾーンで、今日からさかのぼって読み込む日付付きメモリファイルの数です（デフォルト: 今日と昨日の2日分）。`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`起動時コンテキストを有効にする`},help:{"v1-1d5vz2u-4i":`引数なしのセッションリセット時に、起動時の導入コンテキストを有効にします（デフォルト: true）。無効にすると、ランタイムによる日次メモリの読み込みを行わず、プロンプトのみに基づく動作に戻ります。`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`起動時コンテキストのファイルあたりの最大バイト数`},help:{"v1-11cbian-41":`起動時コンテキストの構築時に、日次メモリファイルごとに許容される最大バイト数です（デフォルト: 16384）。境界の安全性を確保するためのこの読み取り上限を超えるファイルはスキップされます。`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`起動時コンテキストのファイルあたりの最大文字数`},help:{"v1-10z53s-2u":`読み込んだ各日次メモリファイルから、起動時の導入コンテキストに保持する最大文字数です（デフォルト: 1200）。`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`起動時コンテキストの最大合計文字数`},help:{"v1-sf676u-54":`起動時の前置きに読み込まれるすべての日次メモリファイルについて、保持する合計文字数の上限です（デフォルト：2800）。この上限に達すると、それ以降のファイルは前置きに収まるように切り詰められます。`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`サブエージェントへの委任モード`},help:{"v1-pqewbk-5o":`プロンプトのみで制御するサブエージェントへの委任の強さです。各エージェントのメインセッションでは "prefer"、それ以外では "suggest" がデフォルトです。"prefer" は、単純ではない作業を sessions_spawn 経由で委任するようエージェントに強く指示します。`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`システムエージェントの対象`},help:{"v1-1wwimo9-34":`バックグラウンドで動作する OpenClaw システムエージェントと Custodian の推論、およびスコープが指定されていない一部のオペレーター読み取り操作の対象設定です。`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`システムエージェントの所有者`},help:{"v1-15rvt92-8c":`バックグラウンドのシステムエージェントおよび Custodian への問い合わせで使用するモデルと認証情報を所有するエージェントです。models.list、models.authStatus、skills.status、doctor.memory.status、またはエージェント所有のモデルや認証状態を解決する infer CLI コマンドで agentId または --agent が省略された場合にも使用されます。リクエストで明示された agentId が常に優先されます。`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`入力中表示の更新間隔（秒）`},help:{"v1-1y701ox-42":`すべてのエージェントの入力中インジケーターを維持するための更新間隔を秒単位で制御します。値を大きくすると、入力中表示に対応するすべてのチャネルで更新頻度が下がります。`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`入力中表示モード`},help:{"v1-m2hvpw-3m":`エージェントが入力中表示を開始するタイミングを制御します。指定できる値は "never"、"instant"、"thinking"、"message" です。エージェントごとの typingMode は、このデフォルト設定を上書きします。`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`ユーティリティモデル`},help:{"v1-1wg7h1a-7s":`タイトル生成や進捗説明などの短い内部タスクに使用する、低コストのモデル（provider/model またはエイリアス）を任意で指定します。未設定の場合、プライマリプロバイダーで宣言された小型モデルがあればそれを使用し、なければプライマリモデルを使用します。ユーティリティルーティングを無効にするには、空の文字列を設定します。`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`音声モデルのフォールバック`},help:{"v1-faazv4-1b":`優先順に並べたフォールバック用の音声モデル（provider/model）。`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`音声モデル`},help:{"v1-1yeh3h4-2t":`音声合成、文字起こし、リアルタイム音声機能で使用する音声モデル（provider/model）を任意で指定します。`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`音声タイムアウト（ミリ秒）`},help:{"v1-1sbergs-32":`呼び出し元がタイムアウトに対応している場合に、音声モデルの処理で使用するプロバイダーリクエストのデフォルトタイムアウト（ミリ秒）。`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`ワークスペース`},help:{"v1-1lssx8l-5w":`初期化ファイルとメモリファイル用のデフォルトのエージェントワークスペース。agents.defaults.cwd が未設定の場合は、作業ディレクトリとしても使用されます。ラッパーから実行する場合は、パス解決の一貫性を保つため、明示的に設定してください。`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`エージェント一覧`},help:{"v1-yurood-5l":`設定済みエージェントを明示的に指定する一覧。ID と、モデル、ツール、アイデンティティ、ワークスペースの任意の上書き設定を含みます。バインディング、承認、セッションルーティングの一貫性を保つため、ID は継続して同じものを使用してください。`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`レガシーエージェントランタイム`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`レガシーエージェントランタイム ID`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`エージェントのブートストラップ最大文字数`},help:{"v1-rsf1es-4j":`このエージェントのシステムプロンプトに挿入される各ワークスペースのブートストラップファイルの最大文字数を、エージェントごとに上書きします。省略すると agents.defaults.bootstrapMaxChars を継承します。`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`エージェントのブートストラップ合計最大文字数`},help:{"v1-1bal68p-4y":`このエージェントのシステムプロンプトに挿入されるすべてのワークスペースのブートストラップファイルの合計最大文字数を、エージェントごとに上書きします。省略すると agents.defaults.bootstrapTotalMaxChars を継承します。`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`エージェントのコンテキスト挿入`},help:{"v1-1j68ys8-50":`組み込みランタイムでのワークスペースのブートストラップファイル注入を、エージェントごとに上書きする設定です。省略すると agents.defaults.contextInjection を継承します。CLI を使用するプロンプトの準備には適用されません。`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`エージェントのコンテキスト制限`},help:{"v1-f1qxq8-3c":`特定のコンテキスト容量設定をエージェントごとに上書きするための任意設定です。省略したフィールドは agents.defaults.contextLimits を継承します。`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`エージェントの memory_get 最大文字数`},help:{"v1-12hlmsv-1v":`memory_get のデフォルトの最大文字数上限を、エージェントごとに上書きします。`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`エージェントの圧縮後の最大文字数`},help:{"v1-15s0npd-1w":`圧縮後の AGENTS.md 抜粋の文字数上限をエージェントごとに上書きします。`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`エージェントの作業ディレクトリ`},help:{"v1-mv43ak-6a":`このエージェントが応答を実行する際の作業ディレクトリです。agents.defaults.cwd を上書きしますが、セッション生成時に指定された cwd は上書きしません。ブートストラップファイルとメモリファイルはワークスペースに残ります。~ と相対パスに対応しています。別の cwd を使用するには、サンドボックス外での実行が必要です。`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`エージェントの判断モデル`},help:{"v1-1mih8bf-3j":`エージェントごとの判断モデルです。未設定の場合は agents.defaults.decisionModel を継承します。空文字列の場合、このエージェントの判断呼び出しは無効になります。`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`エージェントの組み込み OpenClaw`},help:{"v1-uoomza-4b":`エージェントごとの組み込み OpenClaw の上書き設定（任意）です。全体のデフォルトを変更せずに、特定のエージェントでより厳格な GPT-5 の実行動作を有効にできます。`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`エージェントの組み込み OpenClaw 実行契約`},help:{"v1-1d1jaoi-7k":`エージェントごとの組み込み OpenClaw 実行契約の上書き設定（任意）です。"strict-agentic" に設定すると、対応する OpenAI/OpenAI Codex GPT-5 ファミリーでの実行時に、そのエージェントの構造化された計画追跡と非表示ターンの復旧が有効になります。"default" に設定すると、標準のランナー動作を継承します。`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`エージェントの実験的フラグ`},help:{"v1-1r06jov-2a":`エージェントごとの実験的フラグです。省略されたフィールドは agents.defaults.experimental を継承します。`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`エージェントの軽量ローカルモデルモード`},help:{"v1-5o3tgx-58":`軽量ローカルモデルモード向けの、エージェント別のトラブルシューティング用オーバーライド設定です。すべてのエージェントのツールを減らすことなく、オプションツールの制限によって確認済みのモデルの不具合を解消できる場合にのみ有効にしてください。`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`エージェントの高速モードのデフォルト`},help:{"v1-1ujydjc-3o":`エージェントごとの高速モードのデフォルト値（"auto"、true、false）を任意で指定します。メッセージ単位またはセッション単位の高速モードの上書き設定がない場合に適用されます。`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`ハートビートのダイレクト配信ポリシー`},help:{"v1-11gl9l0-41":`ハートビートのダイレクト/DM配信ポリシーをエージェントごとに上書きします。ハートビートのアラートをDM以外の宛先にのみ送信するエージェントには、"block"を使用してください。`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`ハートビートのタイムアウト（秒）`},help:{"v1-kdetv4-6s":`ハートビートのエージェントターンが中止されるまでに許容される最大時間を、エージェントごとに秒単位で指定します。未設定の場合は、マージ済みのハートビートのタイムアウトを継承します。それも未設定の場合は、agents.defaults.timeoutSecondsが設定されていればその値を使用し、それ以外の場合はハートビートの実行間隔を使用します（上限600秒）。`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`アイデンティティのアバター`},help:{"v1-pzp9gr-1t":`エージェントのアバター（ワークスペースからの相対パス、http(s) URL、またはdata URI）。`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`エージェントのモデルポリシー`},help:{"v1-17d5je8-2r":`エージェントごとのモデル上書きポリシーです。明示的な許可リストを指定すると、このエージェントのデフォルトポリシーが置き換えられます。`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`許可されたエージェントモデル`},help:{"v1-v1ueke-5b":`このエージェントで上書き先として許可するモデル参照です。エイリアス、完全な"provider/model"参照、および"provider/*"や"provider/namespace/*"のように末尾にワイルドカードを付けたプレフィックスを指定できます。空の場合はすべてのモデルが許可されます。`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`エージェントのモデル上書き設定`},help:{"v1-nld1vq-1v":`完全な provider/model ID をキーとする、エージェントごとのモデルカタログの上書き設定。`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`エージェントのモデルランタイム`},help:{"v1-7b59y-3s":`このエージェントのモデルごとのランタイムポリシー（任意）。エージェント全体のランタイムを設定する代わりに、エージェント固有のモデル例外を設定する場合に使用します。`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`エージェントのモデルランタイム ID`},help:{"v1-1ckfc39-46":`エージェントごとのモデルランタイム ID："openclaw"、"auto"、"codex" などの登録済みプラグインハーネス ID、または "claude-cli" などのサポートされている CLI バックエンドのエイリアス。`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`コードモード`},help:{"v1-91zu7f-7m":`このエージェントと、完全に一致する provider/model に適用する OpenClaw コードモード。「オン」は強制的に有効化し、「オフ」は無効化します。「デフォルト」は、エージェントの有効化設定、共有モデルの上書き設定、tools.codeMode.enabled の順に設定を継承します。選択されているランタイムや Codex ネイティブのコードモードは変更されません。`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`エージェントの推論表示のデフォルト`},help:{"v1-13ly0xf-3m":`エージェントごとの推論表示のデフォルト設定（任意、on|off|stream）。メッセージ単位またはセッション単位の推論の上書き設定がない場合に適用されます。`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`エージェントのランタイム`},help:{"v1-avjgkf-3l":`このエージェントのランタイム記述子（任意）。デフォルトの OpenClaw 実行には embedded、外部 ACP ハーネスのデフォルト設定には acp を使用します。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`エージェントの ACP ランタイム`},help:{"v1-91zvdk-3i":`runtime.type=acp の場合に使用する、このエージェントの ACP ランタイムのデフォルト設定です。会話ごとに、バインディングレベルの ACP オーバーライドが引き続き優先されます。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`エージェントの ACP ハーネスエージェント`},help:{"v1-1pm98vp-37":`この OpenClaw エージェントで使用する ACP ハーネスエージェントの ID（任意）。例：codex、claude、cursor、gemini、openclaw。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`エージェントの ACP バックエンド`},help:{"v1-1u3cdsg-2n":`このエージェントの ACP セッションで使用する ACP バックエンドのオーバーライド（任意）。未指定の場合はグローバルの acp.backend を使用します。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`エージェントの ACP 作業ディレクトリ`},help:{"v1-d9p9rf-1t":`このエージェントの ACP セッションで使用するデフォルトの作業ディレクトリ（任意）。`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`エージェントの ACP モード`},help:{"v1-yatuk4-21":`このエージェントのデフォルトの ACP セッションモード（任意）。persistent または oneshot を指定します。`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`エージェントのランタイムタイプ`},help:{"v1-139fbk6-2r":`このエージェントのランタイムタイプ："embedded"（デフォルトの OpenClaw ランタイム）または "acp"（ACP ハーネスのデフォルト設定）。`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`エージェントのサンドボックスブラウザーの CDP 接続元範囲`},help:{"v1-1q1qyso-1d":`CDP 接続元 CIDR 許可リストのエージェントごとのオーバーライド。`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`エージェントのサンドボックスブラウザーのネットワーク`},help:{"v1-13bdfww-4c":`サンドボックスブラウザーのDockerネットワークに対するエージェントごとの上書き設定です。ブリッジネットワークを使用してください。ブラウザーの制御にはCDPポートの公開が必要なため、"none"はサポートされていません。`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`エージェントのサンドボックスDockerでコンテナー名前空間への参加を許可`},help:{"v1-1xtnseb-2i":`サンドボックスのDockerネットワークモードでコンテナー名前空間への参加を許可する、エージェントごとの危険な上書き設定です。`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`エージェントのサンドボックスDocker GPU`},help:{"v1-1kek1n2-1t":`サンドボックスコンテナーのDocker GPUパススルーに対するエージェントごとの上書き設定です。`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`エージェントのスキルフィルター`},help:{"v1-igchue-6v":`このエージェントで使用できるスキルの許可リストです（任意）。省略すると、agents.defaults.skillsが設定されている場合はその設定を継承し、設定されていない場合はスキルを制限しません。スキルを使用しない場合は[]を設定してください。明示的に指定したリストは、継承されたデフォルト設定と統合されず、完全に置き換えます。`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`エージェントのSkills制限`},help:{"v1-1sv10v9-4y":`スキルサブシステムの使用枠に対するエージェントごとの上書き設定です（任意）。汎用的なコンテキスト制限の設定経路を別途追加せずに、エージェントのスキルプロンプトの使用枠を変更する場合に使用してください。`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`エージェントのSkillsプロンプトの最大文字数`},help:{"v1-dys63y-52":`スキルプロンプトの文字数上限をエージェントごとに上書きします。同じ上限を contextLimits 経由で設定するのではなく、既存の skills.limits.maxSkillsPromptChars パスを拡張します。`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`サブエージェント委任モード`},help:{"v1-1rkgh6p-4s":`サブエージェントへの委任の強さをエージェントごとに上書きします。省略すると、このエージェントのメインセッションでは "prefer"、それ以外では "suggest" が使用されます。明示的に設定された "prefer" または "suggest" が常に優先されます。`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`エージェントのデフォルト思考レベル`},help:{"v1-173q7vy-43":`エージェントごとに設定できる任意のデフォルト思考レベルです。メッセージ単位またはセッション単位の上書き設定がない場合、このエージェントの agents.defaults.thinkingDefault を上書きします。`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`エージェントのツール許可リストへの追加`},help:{"v1-1550ui9-46":`グローバルポリシーとプロファイルポリシーに追加する、エージェントごとのツール許可リストです。特化型エージェントの権限が意図せず拡大しないよう、範囲を絞ってください。`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`プロバイダー別のエージェントツールポリシー`},help:{"v1-mthxv9-4t":`チャネル単位で機能を制御するために、エージェントごとにプロバイダー別のツールポリシーを上書きします。特定のエージェントで、あるプロバイダーに対して他のプロバイダーより厳しい制限が必要な場合に使用してください。`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`エージェントのコードモード`},help:{"v1-118t8u5-65":`エージェントごとのコードモードのオプション。enabled を明示的に設定すると、共有モデルおよびグローバルの有効化のデフォルト設定を上書きします。ただし、エージェント固有のモデルの codeMode 設定が優先されます。その他のオプションは、有効化の状態を変更せずに tools.codeMode に上書きマージされます。`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`エージェント実行タイムアウト（秒）`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`エージェントの GitHub CLI ID の上書き`},help:{"v1-mjwdh4-38":`このエージェントの管理対象 GitHub CLI ID と Git 作成者情報を完全に上書きします。省略すると、システムの ID を継承します。`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`エージェントの Git 作成者メールアドレス`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`エージェントの Git 作成者名`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`エージェントの GitHub 認証情報の種類`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`エージェントの GitHub プロファイルのバージョン`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`エージェントのメッセージアクション許可リスト`},help:{"v1-1g5gov3-67":`メッセージツールで使用する、エージェントごとのメッセージアクション許可リスト。公開サンドボックスエージェントでは、["send"] のような最小限のリストに設定してください。これにより、読み取り、編集、削除、リアクション、およびその他のプロバイダー固有のメッセージアクションが非表示になり、ブロックされます。`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`エージェントのコンテキスト間メッセージ送信（プロバイダー間）`},help:{"v1-pehesn-49":`異なるプロバイダー間での送信に関するエージェントごとの上書き設定です。グローバル設定を継承します（デフォルト: true）。このエージェントのプロバイダー間メッセージ送信をブロックするには、false に設定してください。`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`エージェントのコンテキスト間メッセージ送信（同一プロバイダー）`},help:{"v1-s9u09h-4t":`同じプロバイダー上の他の会話への送信を制御する、エージェントごとのメッセージ保護設定です。公開エージェントの送信先を現在の会話のみに制限するには、この設定と allowAcrossProviders の両方を false に設定してください。`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`エージェントのツールプロファイル`},help:{"v1-1du76ix-57":`特定のエージェントに異なる基本機能セットが必要な場合に、ツールプロファイルの選択をエージェントごとに上書きします。エージェント間のポリシーの違いを意図的かつ確認可能な状態に保つため、使用は必要最小限にしてください。`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`エージェントのスウォーム`},help:{"v1-420ljs-2c":`エージェントごとのスウォーム設定の上書きです。値はトップレベルの tools.swarm 設定に優先してマージされます。`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`エージェントの入力中表示モード`},help:{"v1-oxir52-2e":`他のエージェントを変更せずに、特定のエージェントの入力中表示を開始するデフォルトのポリシーを上書きします。`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`エージェントのユーティリティモデル`},help:{"v1-1v9oskz-2z":`短い内部タスクに使用するユーティリティモデルを、エージェントごとに上書きする任意の設定です。agents.defaults.utilityModel を上書きします。`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`エージェント所有権の世代`},help:{"v1-m2hp61-8g":`マルチエージェントの所有権の世代を示す永続的なマーカーです。"explicit" は、アンビエントチャネル、ハートビート、システムエージェントへの問い合わせ、Talk、cron、およびエージェント指定なしの CLI 操作で、操作面ごとの所有者を特定する必要があり、特定できない場合は安全のため処理を拒否することを意味します。OpenClaw は、エージェント群の作成時または移行時にこの値を自動設定します。単一のエージェントでは省略してください。`}},approvals:{label:{"v1-1m405m7-9":`承認`},help:{"v1-4y3in-5w":`execとプラグインの承認リクエストを、発生元のセッション外のチャット送信先に転送するための承認ルーティング設定です。運用担当者が別経路で承認状況を明示的に確認する必要がない限り、無効のままにしてください。`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`exec承認の転送`},help:{"v1-1r2mozk-5v":`有効化、ルーティングモード、フィルター、明示的な転送先など、exec承認の転送動作をまとめて設定します。承認プロンプトを発生元のスレッドだけでなく運用チャネルにも届ける必要がある場合は、ここで設定してください。`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`承認エージェントフィルター`},help:{"v1-xbuhd3-5i":'承認の転送対象となるエージェントIDの任意の許可リストです。例：`["primary", "ops-agent"]`。転送の影響範囲を制限し、無関係なエージェントについてチャネルに通知しないようにするために使用します。'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`exec承認を転送`},help:{"v1-1t0whe8-5s":`設定済みの配信先へのexec承認リクエストの転送を有効にします（デフォルト：false）。リスクの低い構成では無効のままにし、承認を行う担当者がチャネル上でプロンプトを確認する必要がある場合にのみ有効にしてください。`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`承認転送モード`},help:{"v1-1dedfo4-69":`承認プロンプトの送信先を制御します。"session"は発生元のチャットを使用し、"targets"は設定済みの転送先を使用し、"both"は両方の経路に送信します。基本は"session"を使用し、運用ワークフローで冗長性が必要な場合にのみ送信先を拡張してください。`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`承認セッションフィルター`},help:{"v1-smeg8e-5u":'部分文字列または正規表現形式のパターンで照合する、任意のセッションキーフィルターです。例：`["discord:", "^agent:ops:"]`。意図した承認コンテキストのみが共有の送信先に転送されるよう、対象を絞ったパターンを使用してください。'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`承認の転送先`},help:{"v1-17ah848-5u":`転送モードに転送先が含まれる場合に使用する、明示的な配信先です。各項目にチャネルと送信先の詳細を指定します。転送先リストは最小権限の原則に従って必要最小限に抑え、広範囲への転送を有効にする前に各送信先を確認してください。`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`承認転送先のアカウントID`},help:{"v1-16zopng-5e":`複数アカウントを使用するチャネル構成で、特定のアカウントコンテキストを通じて承認を送信する必要がある場合に指定する、任意のアカウントセレクターです。対象チャネルに複数のIDが設定されている場合にのみ使用してください。`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`承認転送先のチャネル`},help:{"v1-ji1igl-59":`転送された承認の配信に使用するチャネルまたはプロバイダーのIDです。例：discord、slack、プラグインのチャネルID。不明なルートが原因で承認の配信が通知なく失敗することを防ぐため、有効なチャネルIDのみを使用してください。`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`承認転送先のスレッドID`},help:{"v1-1axynw7-59":`転送された承認のスレッド配信に対応するチャネルで指定する、任意のスレッドまたはトピックの転送先です。承認に関するやり取りをメインチャネルではなく運用スレッド内にまとめるために使用してください。`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`承認転送先の送信先`},help:{"v1-1ijng7e-5n":`対象チャネル内の送信先識別子（プロバイダーに応じて、チャネル ID、ユーザー ID、またはスレッドのルート）。送信先の形式はチャネル連携によって異なるため、プロバイダーごとに仕様を確認してください。`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`プラグイン承認の転送`},help:{"v1-1m6pzxv-6b":`有効化、ルーティングモード、フィルター、明示的な転送先など、プラグイン承認の転送動作をまとめて設定します。実行承認の転送とは独立しています。プラグイン承認のプロンプトを運用チャネルに送信する必要がある場合は、ここで設定してください。`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`プラグイン承認のエージェントフィルター`},help:{"v1-jb1bra-4b":'プラグイン承認の転送対象となるエージェント ID の任意の許可リスト。例：`["primary", "ops-agent"]`。転送の影響範囲を制限するために使用します。'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`プラグイン承認を転送`},help:{"v1-1ntctaf-3v":`設定された配信先へのプラグイン承認リクエストの転送を有効にします（デフォルト：false）。approvals.exec.enabled とは独立しています。`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`プラグイン承認の転送モード`},help:{"v1-1h62vy4-3z":`プラグイン承認プロンプトの送信先を制御します。"session" は元のチャットを使用し、"targets" は設定された転送先を使用し、"both" は両方の経路に送信します。`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`プラグイン承認のセッションフィルター`},help:{"v1-1eppxmt-57":'部分文字列または正規表現形式のパターンとして照合される任意のセッションキーフィルター。例：`["discord:", "^agent:ops:"]`。意図した承認コンテキストのみが転送されるよう、対象を絞ったパターンを使用してください。'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`プラグイン承認の転送先`},help:{"v1-o92qze-3k":`プラグイン承認の転送モードに転送先が含まれる場合に使用する明示的な配信先です。各配信先にはチャネルと宛先の詳細を指定します。`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`プラグイン承認の転送先アカウントID`},help:{"v1-1wf3lqn-3j":`複数アカウントのチャネル設定で、プラグイン承認を特定のアカウント経由で転送する必要がある場合に使用する、任意のアカウント選択設定です。`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`プラグイン承認の転送先チャネル`},help:{"v1-1mzhzi9-34":`プラグイン承認の転送に使用するチャネルまたはプロバイダーのIDです。discord、slack、プラグインのチャネルIDなどを指定します。`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`プラグイン承認の転送先スレッドID`},help:{"v1-1scaw9c-2v":`転送されたプラグイン承認のスレッド配信に対応するチャネルで使用する、任意の転送先スレッドまたはトピックです。`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`プラグイン承認の転送先宛先`},help:{"v1-sh5te1-31":`転送先チャネル内の宛先識別子です。プロバイダーに応じて、チャネルID、ユーザーID、またはスレッドの起点を指定します。`}},attachments:{label:{"v1-8925gh-b":`添付ファイル`},help:{"v1-1xvgkss-40":`メディアを永続保存するプロバイダーやツール全体で共有される、最上位の保持動作です。一般的な一時保存メディアを期限付きで削除する必要がある場合は、ttlHoursを使用します。`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`添付ファイルの保持TTL（時間）`},help:{"v1-1g90day-9e":`一般的な mtime ベースのクリーンアップで処理される保存済みメディアの保持期間（時間、省略可）。未設定のままにするとこのクリーンアップが無効になります。24（1日）や168（7日）などの値を設定すると、古い一時保存メディアが定期的に削除されます。管理対象の送信メディア（チャットで生成された添付ファイル）は対象外で、SQLite と会話記録を考慮した独自の保持ルールに従います。`}},audio:{label:{"v1-11wczsp-5":`音声`}},auth:{label:{"v1-5xz433-4":`認証`},help:{"v1-1eu3aud-5c":`複数プロファイルのプロバイダー認証情報と、クールダウンに基づくフェイルオーバー順序に使用する認証プロファイルのルート設定です。自動フェイルオーバーの動作を監査できるよう、プロファイルは必要最小限にし、明示的に設定してください。`}},"auth%2Eorder":{label:{"v1-gadtii-i":`認証プロファイルの順序`},help:{"v1-1x6kknp-1w":`プロバイダーごとに順序付けされた認証プロファイル ID（自動フェイルオーバーに使用）。`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`認証プロファイル`},help:{"v1-kzoqcn-1j":`名前付き認証プロファイル（プロバイダー + モード + 任意のメールアドレス）。`}},bindings:{label:{"v1-1hcih9f-8":`キー割り当て`},help:{"v1-y7hrzb-4i":`ルーティングと永続的な ACP 会話の所有権を定義するトップレベルのバインディングルールです。通常のルーティングには type=route を、永続的な ACP ハーネスのバインディングには type=acp を使用してください。`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`ACP バインディングの上書き設定`},help:{"v1-1t4lisi-44":`bindings[].type=acp に対する、バインディングごとの任意の ACP 上書き設定です。この設定層は、一致する会話に対して agents.entries.*.runtime.acp のデフォルト値を上書きします。`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`ACP バインディングのバックエンド`},help:{"v1-rsrbkp-2x":`このバインディングの ACP バックエンドの上書き設定（未設定の場合はエージェントランタイムの ACP バックエンド、次にグローバルの acp.backend にフォールバック）。`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`ACP バインディングの作業ディレクトリ`},help:{"v1-ngpkj0-1y":`このバインディングから作成されるACPセッションの作業ディレクトリを上書きします。`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`ACPバインディングのラベル`},help:{"v1-azce82-23":`このバインディングに紐づく会話で、ACPのステータスや診断に使用するわかりやすいラベルです。`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`ACPバインディングのモード`},help:{"v1-cgq8xv-1v":`このバインディングのACPセッションモードを上書きします（persistentまたはoneshot）。`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`バインディングのエージェントID`},help:{"v1-17ra0cl-4m":`対応するバインディングの一致ルールが満たされたときにトラフィックを受信する対象エージェントのIDです。実行時のルーティング失敗を防ぐため、設定済みの有効なエージェントIDのみを使用してください。`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`バインディングの一致ルール`},help:{"v1-sc1w2e-51":`バインディングを適用する条件を決める一致ルールオブジェクトです。チャネルと、任意のアカウントやピアの制約を含みます。コンテキストをまたいで意図せずエージェントが処理を引き継ぐことを避けるため、ルールの適用範囲を絞ってください。`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`バインディングのアカウントID`},help:{"v1-1d209g7-56":`複数アカウントを使用するチャネル構成で、バインディングを1つのIDにのみ適用するための任意のアカウントセレクターです。ルートを特定のアカウントに限定する必要がある場合に使用し、それ以外は未設定のままにしてください。`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`バインディングのチャネル`},help:{"v1-d22m5-54":"このバインディングが適用されるチャネルまたはプロバイダーの識別子です。例として、`telegram`、`discord`、プラグインのチャネルIDなどがあります。バインディングの評価が確実に機能するよう、設定済みのチャネルキーを正確に使用してください。"}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`バインディングのギルドID`},help:{"v1-jzzfj1-4x":`複数サーバー環境でのバインディング評価に使用する、Discord形式のギルド／サーバーIDによる任意の制約です。同じピア識別子が異なるギルドに存在する場合に使用します。`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`バインディングのピア照合`},help:{"v1-gcjxff-4i":`ピアの種類とIDを含む、特定の会話に対する任意の照合条件です。ダイレクト会話、グループ、チャンネルのうち、1つの対象だけをエージェントに固定する場合に使用します。`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`バインディングのピアID`},help:{"v1-86fbh7-4b":`ピアの照合に使用する会話識別子です。プロバイダーのチャットID、チャンネルID、グループIDなどを指定します。通知なしに不一致となることを避けるため、正確に指定してください。`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`バインディングのピアの種類`},help:{"v1-uufscp-4x":`ピアの会話タイプ："direct"、"group"、"channel"、または旧形式の"dm"（directの非推奨エイリアス）。新しい設定では"direct"を推奨します。種類はチャンネルの意味に合うように指定してください。`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`バインディングのロール`},help:{"v1-6s891m-4k":`チャットのコンテキストにロールを付与するプロバイダーが使用する、ロールに基づく任意のフィルターリストです。特権ロールや運用ロールのトラフィックを専用エージェントにルーティングする場合に使用します。`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`バインディングのチームID`},help:{"v1-hh9ps2-48":`チャットをチーム単位で管理するプロバイダーが使用する、チーム／ワークスペースIDによる任意の制約です。バインディングを1つのワークスペースのコンテキストに限定する必要がある場合に追加します。`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`バインディングのセッション`},help:{"v1-x325l2-4v":`このバインディングに一致する会話のルートセッション設定を任意で上書きします。特定のルートで同じエージェントを使いながら、セッションの継続性を別の方法で分離したい場合に使用します。`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`バインディングのセッションDMスコープ`},help:{"v1-10sg3xw-4s":`このルートバインディングのDMセッションスコープを任意で上書きします。たとえば、グローバル設定を session.dmScope="main" に保ちながら、特定のダイレクトメッセージ相手には "per-account-channel-peer" を使用できます。`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`バインディングのセッショングループスコープ`},help:{"v1-1ys2u7k-6n":`このルートバインディングのグループ／チャンネルのセッションスコープを任意で上書きします。"per-group" は一致するルームを分離して保持し、dmScope に関係なくエージェントのメインセッションがバックグラウンドで監視します。"main" はそれらのコンテキストをメインセッションに統合するため、監視は不要です。`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`バインディングの種類`},help:{"v1-172mhtk-3o":`バインディングの種類です。通常のルーティングには "route"（従来のルートエントリでは省略可能）を、永続的なACP会話バインディングには "acp" を使用します。`}},broadcast:{label:{"v1-awqjh0-j":`エージェントグループスレッド`},help:{"v1-1tz72sr-6b":`エージェントグループスレッドを使用すると、1つの受信会話に対して、設定済みの複数のエージェントをそれぞれ専用のセッションで実行できます。チャネルで修飾されたエントリは回数制限付きの追加ラウンドに対応しています。従来のWhatsAppピア配列は、1回のみ実行する動作を維持します。`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`エージェントグループの参加者とオプション`},help:{"v1-1b63zmt-7d":`チャネルで修飾されたピアID（例："telegram:-100123"）を使用して、エージェントIDの配列、またはagents、mentionGating、maxRounds、maxTurnsを含む厳密な形式のオブジェクトを設定します。修飾されたエントリは従来のWhatsAppピアキーより優先され、最大16個のエージェントを指定できます。`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`エージェントグループの参加者`},help:{"v1-g5o0ky-43":`agents.entriesに含まれる参加エージェントのID（最大16個）。各参加者は、このチャネル、アカウント、会話、スレッドに対して専用のセッションを使用します。`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`エージェントグループの最大ラウンド数`},help:{"v1-i6v4jc-5a":`初回ラウンドを含む、受信メッセージあたりの最大ラウンド数（整数：1～4、デフォルト：1）。後続のラウンドでは、他の参加者の返信を、返信元を明示して制限された範囲で共有し、すべての参加者がパスすると終了します。`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`エージェントグループの最大ターン数`},help:{"v1-1kiv8dy-72":`全ラウンドを通じた、受信メッセージあたりの参加者の最大ターン数（整数：1～32、デフォルト：agents.length）。スロットは並列ディスパッチの前に予約されます。この設定はエージェントのターン数を制限するもので、実際のメッセージチャンク数やツールによる送信回数を制限するものではありません。再起動後に残りの実行枠は引き継がれません。`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`エージェントグループのメンションによる選択`},help:{"v1-uay9zu-5u":`明示的な@メンションに一致する参加者がいる場合は、その参加者のみを選択します。一致する参加者がいない場合は、全参加者を実行します（デフォルト：true）。名前だけの記述や絵文字では参加者は選択されません。チャンネルの許可リストと参加許可ルールは引き続き適用されます。`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`エージェントグループの実行方式`},help:{"v1-p4k9hu-4q":`参加者の実行順序："parallel"（デフォルト）ではエージェントを同時に実行し、"sequential"では設定された順序で実行します。各ラウンドが完了してから次のラウンドが始まります。`}},browser:{label:{"v1-13dzmen-7":`ブラウザー`},help:{"v1-5b74wi-5l":`ローカルまたはリモートの CDP 接続、プロファイルのルーティング、スクリーンショットやスナップショットの動作に関するブラウザー実行時の設定です。自動化ワークフローでブラウザーの通信設定をカスタマイズする必要がない限り、デフォルト設定を維持してください。`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`システムプロファイルのインポートを許可`},help:{"v1-1lsvlxw-5w":`macOS ホストで、ローカルの Chrome 系ブラウザーのシステムプロファイルから、管理対象の OpenClaw ブラウザープロファイルに Cookie をインポートできるようにします。ブラウザープロファイルの Cookie のインポートと、それに伴う macOS キーチェーンの同意プロンプトを防ぐには、無効にしてください。`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`ブラウザー接続専用モード`},help:{"v1-xaw7xm-4s":`ローカルのブラウザープロセスを起動せず、既存のブラウザーへの接続のみを行うように制限します。すべてのブラウザーセッションがリモート CDP プロバイダーによって外部管理されている場合に使用してください。`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`ブラウザー CDP URL`},help:{"v1-2n72jb-65":`外部で管理されているブラウザーインスタンスへの接続に使用する CDP/DevTools エンドポイント URL です。ブラウザーホストの集中管理、トンネル、既存セッションへの接続に使用し、URL へのアクセスは信頼できるネットワーク経路に制限してください。`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`ブラウザーのデフォルトプロファイル`},help:{"v1-a6xo96-52":`呼び出し元がプロファイルを明示的に選択しない場合に使用する、デフォルトのブラウザープロファイル名です。異なるコンテキストの状態を誤って使用するリスクを減らすため、権限を抑えた固定のプロファイルをデフォルトとして使用してください。`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`ブラウザーを有効化`},help:{"v1-19qr4oj-56":`Gateway でブラウザー機能を有効にし、ブラウザーツールや CDP を利用するワークフローを実行できるようにします。ブラウザーの自動操作が不要な場合は無効にすると、攻撃対象領域と起動時の処理を減らせます。`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`ブラウザーの evaluate を有効化`},help:{"v1-1oa79mq-59":`対応している環境で、実行時にスクリプトを評価するためのブラウザー側の evaluate ヘルパーを有効にします。ワークフローでスナップショットやナビゲーション以外の評価処理が必要な場合を除き、無効のままにしてください。`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`ブラウザーの実行ファイルのパス`},help:{"v1-1plb4ki-6i":`ホスト環境で自動検出が十分に機能しない場合に、ブラウザーの実行ファイルのパスを明示的に指定します。再起動後も起動動作が一定になるよう、変更されない絶対パス、または OS のホームディレクトリを表す ~ で始まるパスを使用してください。`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`ブラウザー拡張機能リレー`},help:{"v1-6ywlwr-4e":`Chrome 拡張機能リレーの認証互換性設定です。ペアリング済みの古い拡張機能や外部 CDP クライアントで必要な間のみ、従来方式を許可する移行期間を維持してください。`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`ブラウザーリレーの従来の認証方式を許可`},help:{"v1-pj2e90-63":`従来の Bearer、Basic、および token-subprotocol によるリレー認証を一時的に受け入れます。デフォルト：1 回の移行期間中は true。すべての拡張機能と外部 CDP クライアントがブラウザーリレー認証 v2 を使用するようになったら、false に設定してください。`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`ブラウザーのヘッドレスモード`},help:{"v1-1rswq8j-5a":`ローカルランチャーがブラウザーインスタンスを起動する際に、ヘッドレスモードでの起動を強制します。サーバー環境ではヘッドレスモードを有効のままにし、画面を表示して UI をデバッグする必要がある場合にのみ無効にしてください。`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`ブラウザーのサンドボックス無効モード`},help:{"v1-slntux-4w":`実行時にサンドボックスが機能しない環境向けに、Chromiumのサンドボックス分離フラグを無効にします。プロセス分離による保護が弱まるため、可能な限りこの設定はオフにしてください。`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`ブラウザープロファイル`},help:{"v1-1x8lf05-51":`CDPポートまたはURLへの明示的なルーティングに使用する、名前付きブラウザープロファイルの接続マップです。任意でメタデータを追加できます。プロファイル名は一貫させ、エンドポイントの定義が重複しないようにしてください。`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`ブラウザープロファイルの接続専用モード`},help:{"v1-2b5zs0-5a":`ローカルブラウザーの起動をスキップし、既存のCDPエンドポイントへの接続のみを行う、プロファイルごとの上書き設定です。あるプロファイルは外部で管理し、ほかのプロファイルはローカルで起動する場合に便利です。`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`ブラウザープロファイルのCDPポート`},help:{"v1-gx1yiq-49":`URLではなくポートを指定してブラウザーインスタンスに接続する際に使用する、プロファイルごとのローカルCDPポートです。接続の競合を避けるため、プロファイルごとに異なるポートを使用してください。`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`ブラウザープロファイルのCDP URL`},help:{"v1-x491r0-64":`プロファイル名による明示的なブラウザールーティングに使用する、プロファイルごとのCDP/DevToolsエンドポイントURLです。リモートCDPホスト、トンネル、または稼働中のChrome DevToolsエンドポイント経由で接続する既存セッションのプロファイルに使用してください。`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`ブラウザープロファイルのドライバー`},help:{"v1-17byyx6-5r":`プロファイルごとのブラウザードライバーモード。CDP ベースのプロファイルには "openclaw"（または従来の "clawd"）、Chrome DevTools MCP 接続には "existing-session"、認証済み Chrome 拡張機能リレーには "extension" を使用します。`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`ブラウザープロファイルの実行ファイルパス`},help:{"v1-29azyv-4w":`ローカルで起動する管理対象ブラウザープロファイルの、プロファイルごとのブラウザー実行ファイルパス。browser.executablePath を上書きします。OS のホームディレクトリを示す ~ で始まるパスも指定できます。`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`ブラウザープロファイルのヘッドレスモード`},help:{"v1-p4jtgv-4u":`ローカルで起動するブラウザーインスタンスの、プロファイルごとのヘッドレス設定の上書き。他のすべてのプロファイルに browser.headless を強制せずに、特定のプロファイルだけをヘッドレスで動作させたい場合に使用します。`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`ブラウザープロファイルの Chrome MCP 引数`},help:{"v1-rc45ke-5g":`existing-session 接続用の、プロファイルごとの追加の Chrome DevTools MCP 引数（例：--no-usage-statistics）。ここで指定したエンドポイント引数は、組み込みの自動接続またはブラウザー URL の選択を上書きします。`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`ブラウザープロファイルの Chrome MCP コマンド`},help:{"v1-1xpty8o-2h":`existing-session 接続用の、プロファイルごとの Chrome DevTools MCP コマンド。デフォルトは npx です。`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`ブラウザープロファイルのユーザーデータディレクトリ`},help:{"v1-5xvgex-9h":`Chrome DevTools MCP 経由で既存のセッションに接続するための、プロファイルごとの Chromium ユーザーデータディレクトリです。選択したホストまたはブラウザノードで、組み込みの自動接続処理が誤ったブラウザデータディレクトリを選択する場合に、Brave、Edge、Chromium、またはデフォルト以外の Chrome プロファイルに対して使用してください。~ で始まるパスは、OS のホームディレクトリに展開されます。`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`ブラウザスナップショットのデフォルト設定`},help:{"v1-v19wdy-4y":`呼び出し元がスナップショットのオプションを明示的に指定しない場合に使用される、デフォルトのスナップショット取得設定です。チャネルや自動化経路を問わず一貫した取得動作になるように調整してください。`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`ブラウザスナップショットモード`},help:{"v1-joeyxp-5c":`エージェントが利用できるようにページコンテンツを変換する方法を制御する、デフォルトのスナップショット抽出モードです。ワークフローに合わせて、読みやすさ、再現性、トークン使用量のバランスが取れたモードを選択してください。`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`ブラウザ SSRF ポリシー`},help:{"v1-1qbp9im-5e":`内部ホストに到達する可能性があるブラウザやネットワークの取得経路に対する、サーバーサイドリクエストフォージェリ防止設定です。本番環境では制限の厳しいデフォルト設定を維持し、明示的に承認された接続先のみを許可してください。`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`ブラウザで許可するホスト名`},help:{"v1-1rng39-2k":`ブラウザの SSRF ポリシーチェックで許可する、完全一致のホスト名または IP アドレスリテラルです。リストは必要最小限にしてください。`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`ブラウザで IPv6 ユニークローカル範囲を許可`},help:{"v1-1glx5cy-2c":`信頼できる fake-IP プロキシ環境で、IPv6 ユニークローカルアドレス（fc00::/7）を許可します。`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`ブラウザーでRFC 2544ベンチマーク範囲を許可`},help:{"v1-10ateu3-2i":`信頼できるFake-IPプロキシ環境で、RFC 2544ベンチマーク範囲のIPアドレス（198.18.0.0/15）を許可します。`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`ブラウザーでブロックするホスト名`},help:{"v1-nug0we-6k":`プライベートネットワークへのアクセスが有効な場合でも、DNS解決や許可ルールの適用前に拒否するホスト名パターンです。完全一致のホスト名と、サブドメインのみに一致する「*.example.com」をサポートします。ルートドメインもブロックするには、「example.com」を別途追加してください。空または未設定の場合、拒否対象は追加されません。`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`ブラウザーでプライベートネットワークを許可（危険）`},help:{"v1-17103pi-4m":`ブラウザーツールからプライベートネットワークのアドレス範囲へのアクセスを許可します。未設定の場合はデフォルトで無効です。明示的に信頼されたプライベートネットワーク上の接続先に対してのみ有効にしてください。`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`ブラウザータブのクリーンアップ`},help:{"v1-1ctwaad-4y":`プライマリエージェントのセッションで開かれたブラウザータブを、可能な範囲でクリーンアップするポリシーです。長時間稼働するGatewayで、不要になったサンドボックスや管理対象ブラウザーのタブが蓄積しないよう、有効のままにしてください。`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`ブラウザータブのクリーンアップを有効化`},help:{"v1-4sv97p-3u":`プライマリエージェントのセッションで追跡している、アイドル状態のブラウザータブのクリーンアップを有効にします。外部ツールがタブのライフサイクルを完全に管理する場合にのみ無効にしてください。`}},channels:{label:{"v1-1ju93md-8":`チャンネル`},help:{"v1-12yv6ma-5n":`チャネルプロバイダーの設定と、アクセスポリシー、ハートビートの表示、各インターフェースの動作を制御する共通のデフォルト設定です。デフォルト設定は一元管理し、必要な場合にのみプロバイダーごとに上書きしてください。`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`チャンネルのデフォルト設定`},help:{"v1-uz6veb-4p":`プロバイダー固有の設定がない場合に、すべてのプロバイダーに適用されるデフォルトのチャンネル動作です。プロバイダーごとに調整する前に、一貫した基本ポリシーを適用するために使用します。`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`デフォルトのボットループ保護`},help:{"v1-1lpznyk-4w":`ボット間のループ防止に対応するチャンネルプロバイダー向けの、ペア単位のデフォルトのループ保護設定です。特定のチャンネルに異なる上限が必要な場合にのみ、プロバイダー固有の設定で上書きしてください。`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`デフォルトのボットループクールダウン時間（秒）`},help:{"v1-1yl5ird-2z":`ペアがループの上限を超えた後に適用されるクールダウン時間（秒）です。対応チャンネルのデフォルト値は60です。`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`ボットループ保護をデフォルトで有効化`},help:{"v1-3ruik-4r":`ボットが作成したメッセージがディスパッチに到達できる場合、対応チャンネルでペア単位のループ保護をデフォルトで有効にします。ボットを無視する場合は、プロバイダー側で保護を無効にすることもできます。`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`デフォルトのボットループ時間枠あたりのイベント数`},help:{"v1-1u0mdjc-41":`抑制が開始されるまでに、送信者と受信者のペアが設定された時間枠内でやり取りできるイベントの最大数です。対応チャンネルのデフォルト値は20です。`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`デフォルトのボットループ時間枠（秒）`},help:{"v1-12xpmen-2m":`ペア間のループ上限を適用するスライディングウィンドウの長さ（秒）。対応チャネルでのデフォルトは60です。`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`デフォルトのコンテキスト表示範囲`},help:{"v1-1hze3g1-5o":`取得した引用・スレッド・履歴の内容に関する補足コンテキストのデフォルト表示範囲："all"（すべてのコンテキストを保持）、"allowlist"（許可リストに登録された送信者のみ）、または "allowlist_quote"（許可リストに加え、明示的な引用を保持）。`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`デフォルトのグループポリシー`},help:{"v1-ntl9m4-4n":`チャネル全体のデフォルトのグループポリシー："open"、"disabled"、または "allowlist"。幅広いグループ参加を意図している場合を除き、本番環境での安全性を高めるために "allowlist" を維持してください。`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`デフォルトのハートビート表示設定`},help:{"v1-49bw75-4v":`プロバイダーやチャネルが送信するステータスメッセージのデフォルトのハートビート表示設定。アラートは表示したまま、正常状態の更新通知が多すぎる場合は、この設定を全体で調整してください。`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`ハートビートのアラートを表示`},help:{"v1-8dk8zx-4g":`true の場合、劣化状態やエラーを示すハートビートアラートを表示し、運用担当者向けチャネルで問題を速やかに把握できるようにします。本番環境では、チャネルの異常な状態を確認できるよう、有効のままにしてください。`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`ハートビートの正常状態を表示`},help:{"v1-17tg3mk-4z":`true の場合、チャネルのステータス出力に正常なハートビートのステータス項目を表示します。通知が多い環境では false のままにし、運用担当者が正常であることを明示的に確認する必要がある場合にのみ有効にしてください。`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`ハートビートのインジケーター表示`},help:{"v1-1w12cs2-4m":`対応している場合、詳細なステータステキストの代わりに簡潔なインジケーター形式でハートビートを表示します。アクティブなチャネルが多く、情報密度の高いダッシュボードでは、インジケーターモードを使用してください。`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`暗黙的なメンションのデフォルト設定`},help:{"v1-4gtdyv-48":`ボットへの返信、ボットの引用、ボットが参加したスレッド内での発言を、明示的なメンションなしでも対応するメッセージチャネルの起動条件として扱うかどうかを定めるデフォルトのポリシーです。`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`ボットの引用による暗黙的なメンションのデフォルト設定`},help:{"v1-va1u5v-2v":`デフォルトで、ボットのメッセージの引用を暗黙的なメンションとして扱います。後方互換性のため、デフォルトは true です。`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`ボットへの返信による暗黙的なメンションのデフォルト設定`},help:{"v1-lm44c3-39":`デフォルトで、ボット自身のメッセージへの返信を暗黙的なメンションとして扱います。後方互換性のため、デフォルトは true です。`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`スレッド参加による暗黙的なメンションのデフォルト設定`},help:{"v1-160205h-3o":`デフォルトで、ボットが参加したスレッドでの後続の発言を暗黙的なメンションとして扱います。後方互換性のため、デフォルトは true です。`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`チャンネル別モデルの上書き`},help:{"v1-1b01spx-2p":`プロバイダー -> チャンネル ID / DM 相手 ID -> モデルの上書き設定のマッピング（値は provider/model またはエイリアス）。`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`クラウドワーカー`},help:{"v1-10carc4-5v":`使い捨てのリモート環境向けの、オプトイン方式のクラウドワーカープロファイルです。このセクションを省略するか、プロファイルを設定しない場合、クラウドワーカーは作成できず、既存の Gateway/ノードのステータス動作も変わりません。`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`クラウドワーカーデスクトップ（実験機能）`},help:{"v1-vllayc-3n":`デスクトップ対応のクラウドワーカー環境で、実験的な worker.desktop.observe インターフェースと Control UI のデスクトップパネルを有効にします。`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`クラウドワーカーの事前準備プール`},help:{"v1-rw51o5-6b":`後続のセッションですぐに使えるよう、準備して待機させておくクラウドワーカーの上限です。確保したワーカーには、プロバイダーによるクリーンアップが完了するまでマシンの稼働料金が発生します。有効期限は、プロジェクトの実際の需要とプロバイダーの既存のアイドルポリシーに基づいて決まります。`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`クラウドワーカーの待機予備数の上限`},help:{"v1-1mpd1dt-7u":`プロジェクトとプロファイルを横断した、未割り当ての準備済みクラウドワーカー数のGateway全体での上限です（デフォルト: 4）。準備中のワーカーと、クリーンアップの完了が未確認の予備ワーカーも上限の計算に含まれます。0に設定すると、スナップショットの再利用とアクティブなセッションを維持しながら、未割り当ての予備ワーカーを削除して補充を無効にします。`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`クラウドワーカープロファイル`},help:{"v1-eii67l-3j":`名前付きのクラウドワーカープロファイルです。各プロファイルは、プラグインによって登録されたワーカープロバイダーを選択し、そのプロバイダー固有の設定を保持します。`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`クラウドワーカープロファイル`},help:{"v1-1v2w7jl-4u":`環境の作成時に名前で選択する単一のクラウドワーカープロファイルです。プロバイダーの認証情報は、このブロックに機密情報を埋め込むのではなく、サポートされている参照形式で保持してください。`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`クラウドワーカーのインストール方法`},help:{"v1-blrtbf-74":`ワーカーのインストール方法："bundle"（デフォルト）は、Gateway にインストールされているコンテンツハッシュ付きのビルドを転送し、リリース済み、開発中、未リリースのバージョンをサポートします。"npm" は Gateway と完全に同じバージョンをインストールし、そのバージョンがリリース済みの場合にのみ利用できます。`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`クラウドワーカープロバイダー`},help:{"v1-1p4s4c1-44":`プラグインによって登録されたワーカープロバイダーの ID。Gateway がこのプロファイルから環境をプロビジョニングするには、設定されたプラグインがこの ID を公開している必要があります。`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`クラウドワーカーの待機予備数の目標`},help:{"v1-1nwve9s-7w":`このプロファイルを使用する対象プロジェクトごとの、未割り当ての準備済みワーカー数の目標です（デフォルト: 1）。Gateway全体の準備済みプールの上限が適用されます。0に設定すると、スナップショットの再利用を維持しながら、このプロファイルの予備ワーカーを無効にします。準備中のワーカーと、クリーンアップの完了が未確認の予備ワーカーも目標数の計算に含まれます。`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`クラウドワーカープロバイダーの設定`},help:{"v1-mq7u32-4j":`選択したプラグインによって検証される、プロバイダー固有の設定。シークレットを含む値には SecretRef オブジェクトを使用してください。内容が不透明な設定では、シークレットは自動的に解決されません。`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`クラウドワーカーのアイドル時停止までの時間`},help:{"v1-1keuwgh-4w":`45m や 2h など、指定した時間が経過するとアイドル状態のクラウドワーカーを自動的に解放します。次のメッセージで代替ワーカーがプロビジョニングされます。最小値：1m。ワーカーの実行を継続するには、未設定のままにしてください。`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`クラウドワーカーのプロジェクトプロファイル`},help:{"v1-1kkfrif-46":`小文字に正規化されたリポジトリ識別子（host/owner/repo）をキーとする、デフォルトのクラウドワーカープロファイル名。明示的に指定されたディスパッチプロファイル ID が優先されます。`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`クラウドワーカーのプロジェクトプロファイル`},help:{"v1-1mux5u0-30":`セッションのワークツリーの origin がこのリポジトリ識別子と一致する場合に、デフォルトで使用されるクラウドワーカープロファイル名。`}},commands:{label:{"v1-15x4mpf-8":`コマンド`},help:{"v1-1gi0dr2-5a":`各プロバイダーにおけるチャットコマンドの提供範囲、オーナーによるアクセス制限、昇格権限を要するコマンドへのアクセス動作を制御します。より厳格な運用者向け制御や、より広い範囲でのコマンド利用が必要でなければ、デフォルト設定を維持してください。`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`コマンドの昇格権限アクセスルール`},help:{"v1-7azkw-5g":`所有者レベルのコマンドインターフェースに対して、チャネルと送信者ごとに昇格コマンドの許可ルールを定義します。特権コマンドがチャットの幅広い参加者に公開されないよう、プロバイダー固有のIDで対象を限定してください。`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Bashチャットコマンドを許可`},help:{"v1-83ah7w-36":"bashチャットコマンド（`!`、別名 `/bash`）によるホストのシェルコマンドの実行を許可します（デフォルト: false、tools.elevatedが必要）。"}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Bashフォアグラウンド実行時間（ms）`},help:{"v1-1o0o4dw-2c":`bashがバックグラウンドに移行するまでの待機時間です（デフォルト: 2000、0の場合は即座にバックグラウンドに移行）。`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`/configを許可`},help:{"v1-151bb7c-21":`/configチャットコマンドによるディスク上の設定の読み書きを許可します（デフォルト: false）。`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`/debugを許可`},help:{"v1-y1lc3j-1y":`/debugチャットコマンドによるランタイム限定の設定の上書きを許可します（デフォルト: false）。`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`/mcpを許可`},help:{"v1-1rtwcgd-2o":`/mcpチャットコマンドによるmcp.servers配下のOpenClaw MCPサーバー設定の管理を許可します（デフォルト: false）。`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`ネイティブコマンド`},help:{"v1-dighr2-5n":`コマンド登録に対応するチャネル（Discord、Slack、Telegram）にネイティブのスラッシュコマンドやメニューコマンドを登録します。意図的にテキストのみのコマンドワークフローを使用する場合を除き、コマンドを見つけやすくするために有効にしておいてください。`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`ネイティブスキルコマンド`},help:{"v1-19gtqci-5h":`ネイティブのスキルコマンドを登録し、対応するプロバイダーのコマンドメニューからユーザーがスキルを直接呼び出せるようにします。公開されるコマンドが運用担当者の想定と一致するよう、スキルポリシーとの整合性を保ってください。`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`コマンド所有者`},help:{"v1-1di38gv-3y":`所有者限定コマンドの所有者を明示的に指定する許可リスト。チャネル固有のIDを使用してください（必要に応じて "whatsapp:+15551234567" のようにプレフィックスを付けられます）。'*' は無視されます。`}},"commands%2Eplugins":{label:{"v1-culv09-e":`/plugins を許可`},help:{"v1-akwy9y-33":`検出されたプラグインの一覧表示と、設定でのプラグインの有効・無効の切り替えを行う /plugins チャットコマンドを許可します（デフォルト: false）。`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`再起動を許可`},help:{"v1-m32fv2-27":`/restart、/update、および外部からの SIGUSR2 による再起動リクエストを許可します（デフォルト: true）。`}},"commands%2Etext":{label:{"v1-5g1c88-d":`テキストコマンド`},help:{"v1-1utu76s-5j":`利用可能なネイティブコマンド機能に加えて、チャット入力でのテキストコマンド解析を有効にします。ネイティブコマンドの登録に対応していないチャネルとの互換性を保つため、有効のままにしてください。`}},cron:{label:{"v1-1qlte4b-b":`自動化`},help:{"v1-4md8ic-5u":`保存済みの自動化、同時実行数、配信フォールバック、実行セッションの保持に関するグローバルスケジューラー設定。自動化の規模を拡大する場合や外部の Webhook 受信先を連携する場合を除き、デフォルト設定を維持してください。`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`自動化を有効化`},help:{"v1-y8otx6-5i":`Gateway が管理する保存済みスケジュールの自動実行を有効にします。通常のリマインダーや自動化のフローでは有効のままにし、ジョブを削除せずにすべての自動実行を一時停止する場合にのみ無効にしてください。`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`自動化セッションの保持期間`},help:{"v1-4wagu6-7e":"完了した自動化の実行セッションを削除するまでの保持期間を設定します（`24h`、`7d`、`1h30m`、または削除を無効にする `false`。`0h` などのゼロの期間でも無効になります。デフォルト：`24h`）。高頻度のスケジュールでは、保持期間を短くするとストレージ使用量の増加を抑えられます。"}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`実行し損ねた定期自動化をスキップ`},help:{"v1-w9wfmo-66":`Gateway の起動時に、実行し損ねた定期的な cron/every の実行分をスキップし、後追いで実行する代わりに次の実行予定を設定します。デフォルト：false。有効にすると、停止期間後に古いリマインダーが届くのを防げます。単発の at ジョブは引き続き後追いで実行されます。`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`自動化 Webhook の SSRF ポリシー`},help:{"v1-1xlfqnu-5h":`自動化によるすべての送信 Webhook に適用される SSRF ポリシーです。プライベート、ループバック、リンクローカル、内部の宛先は、このポリシーで明示的に許可しない限りブロックされます。厳格な配信制限を維持するには、未設定のままにしてください。`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`自動化 Webhook の許可ホスト名`},help:{"v1-1i94hyz-3n":`自動化 Webhook の配信を許可する完全一致のホスト名または IP リテラルです。通常はブロックされる宛先も含められます。リストは必要最小限にしてください。`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`自動化 Webhook で IPv6 ユニークローカル範囲を許可`},help:{"v1-rke0oj-3b":`IPv6 ユニークローカルアドレス（fc00::/7）への自動化 Webhook を許可します。信頼できる fake-IP プロキシ環境でのみ使用してください。`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`自動化 Webhook で RFC 2544 ベンチマーク範囲を許可`},help:{"v1-x1usg4-3h":`RFC 2544のベンチマーク用IPアドレス範囲（198.18.0.0/15）への自動化Webhookを許可します。信頼できるfake-IPプロキシ環境でのみ使用してください。`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`自動化Webhookのブロック対象ホスト名`},help:{"v1-16cv1ic-6a":`自動化Webhookの配信時に、DNS解決および許可ルールの適用前に拒否するホスト名パターンです。完全一致のホスト名と、サブドメインのみに一致する「*.example.com」を指定できます。ルートドメインもブロックするには「example.com」を別途追加してください。空または未設定の場合、拒否ルールは追加されません。`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`自動化Webhookのプライベートネットワークへのアクセスを許可（危険）`},help:{"v1-1n9710c-3t":`プライベートネットワークおよび内部ネットワークの宛先への自動化Webhookを許可します。設定されているすべてのWebhook送信先が信頼できる場合を除き、無効のままにしてください。`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`自動化WebhookのBearerトークン`},help:{"v1-1l90hxg-5l":`Webhookモードの使用時に、自動化WebhookのPOST配信に付加するBearerトークンです。シークレットまたは環境変数による置換を推奨します。共有Webhookエンドポイントにインターネットからアクセスできる場合は、このトークンを定期的にローテーションしてください。`}},desktop:{label:{"v1-rs698z-7":`デスクトップ`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`ローカルデスクトップ`},help:{"v1-99weio-30":`ローカルVNCサーバーを使用して、ペアリング済みノードまたは試験的なGatewayホストソースのデスクトップを監視します。`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`デスクトップ共有`},help:{"v1-m9lbcj-83":`このマシンのデスクトップソースを有効にします。ペアリング済みのmacOS、Windows、Linuxノードではデフォルトで有効です。デスクトップアプリで共有設定が明示されている場合は、その設定が優先されます。GatewayホストのLabsソースはデフォルトで無効で、変更は即座に適用されます。ペアリング済みノードのデスクトップ設定を変更した後は、そのノードを再起動してください。`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`管理対象のLinuxホストデスクトップ`},help:{"v1-1r7n22m-49":`Linux 上でループバック接続のみを受け付けるヘッドレスの TigerVNC/XFCE デスクトップを実行・監視します。明示的に指定されたポート、またはデフォルトポートで稼働中の既存の VNC サーバーがある場合は、そちらが優先されます。`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`ローカルVNCパスワードファイル`},help:{"v1-1m5lsox-37":`VNCパスワードファイルの絶対パス。macOSでは省略すると、デスクトップビューアーを開く際にアカウントの認証情報を入力できます。`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`ローカルVNCポート`},help:{"v1-1ku4w9b-2b":`このマシンで実行中のVNCサーバーのループバックRFBポート（デフォルト：5900）。`}},diagnostics:{label:{"v1-1stxhg7-b":`診断`},help:{"v1-1d5rnym-5p":`デバッグ時に対象を絞ったトレース、テレメトリーのエクスポート、キャッシュの検査を行うための診断設定です。本番環境では基本的な診断を最小限に抑え、問題を調査する場合にのみ詳細な診断情報の収集を有効にしてください。`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`キャッシュトレース`},help:{"v1-10523zm-5b":`組み込み実行時のキャッシュ判定とペイロードのコンテキストを確認するためのキャッシュトレースのログ設定です。デバッグ時に一時的に有効にし、終了後は無効にして、ログに残る機密情報を減らしてください。`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`キャッシュトレースの有効化`},help:{"v1-2c1umi-1v":`組み込みエージェントの実行時にキャッシュトレースのスナップショットをログに記録します（デフォルト：false）。`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`診断の有効化`},help:{"v1-a46pxt-4h":`ログおよびテレメトリー連携経路への診断計測情報の出力を一括で切り替えます。デフォルトでは有効です。厳しい制約のある環境でのみ false に設定してください。`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`診断フラグ`},help:{"v1-x4w5ok-33":`フラグで指定した対象の診断ログを有効にします（例：["telegram.http"]）。"telegram.*" や "*" などのワイルドカードに対応しています。`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Gateway コンポーネントが出力するトレース、メトリクス、ログの OpenTelemetry エクスポート設定です。集中型のオブザーバビリティバックエンドや分散トレーシングパイプラインと連携する場合に使用します。`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`OpenTelemetry コンテンツ収集`},help:{"v1-19tid4t-2t":`明示的に有効化する OTEL スパンのコンテンツ収集です。デフォルトはオフです。true にすると、システムメッセージ以外のメッセージとツールのコンテンツを収集します。`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry の有効化`},help:{"v1-193bm0-5b":`設定されたエンドポイントとプロトコルに基づいて、トレース、メトリクス、ログの OpenTelemetry エクスポートパイプラインを有効にします。コレクターのエンドポイントと認証の設定が完了するまでは、無効のままにしてください。`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`OpenTelemetry エンドポイント`},help:{"v1-4rrd1x-4y":`OpenTelemetry のエクスポート送信に使用する、スキームとポートを含むコレクターのエンドポイント URL です。到達可能で信頼できるコレクターのエンドポイントを使用し、導入後は取り込みエラーを監視してください。`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`OpenTelemetry フラッシュ間隔（ms）`},help:{"v1-1moqogc-53":`バッファーからコレクターへテレメトリを定期的にフラッシュする間隔（ミリ秒）です。値を大きくするとエクスポートの通信頻度が下がり、小さくするとインシデント対応中に状況をより迅速に把握できます。`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`OpenTelemetry ヘッダー`},help:{"v1-s26t2a-52":`OpenTelemetry のエクスポートリクエストとともに送信する追加の HTTP リクエストヘッダーです。主にテナント認証やルーティングに使用します。シークレットは環境変数を参照する値として保持し、不要なヘッダーの増加を避けてください。`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry ログの有効化`},help:{"v1-12wo6rv-4k":`ローカルのログ出力先に加えて、OpenTelemetry によるログシグナルのエクスポートを有効にします。サービスやエージェント間でログを一元的に関連付ける必要がある場合に使用してください。`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`OpenTelemetry ログエンドポイント`},help:{"v1-1vgzldu-40":`ログシグナル専用の OTLP/HTTP エンドポイントです。設定すると、ログのエクスポートに限り、diagnostics.otel.endpoint と OTEL_EXPORTER_OTLP_ENDPOINT よりも優先されます。`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`OpenTelemetry ログエクスポーター`},help:{"v1-9bzywd-5q":`diagnostics.otel.logs のログエクスポート先です。設定済みの OTLP ログエンドポイントには "otlp"、コンテナのログパイプラインで標準出力の各行に JSON レコードを1件ずつ出力するには "stdout"、両方の出力先が必要な場合は "both" を使用してください。`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`OpenTelemetry メトリクス名のプレフィックス`},help:{"v1-1epdpi9-b2":`OpenClaw 独自のメトリクス名に付くデフォルトのプレフィックス "openclaw." を置き換えます。プレフィックスを削除するには空文字列を使用してください。指定する場合は、先頭を英字とし、ASCII の英字、数字、アンダースコア、ドット、ハイフン、スラッシュを最大128文字まで使用できます。"acme." のように、必要な区切り文字も含めてください。標準の gen_ai.* メトリクス名は変更されません。この値を変更する場合は、古い名前をクエリするダッシュボードやアラートも更新する必要があります。`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`OpenTelemetry メトリクスの有効化`},help:{"v1-13r4cf4-4x":`設定済みのOpenTelemetryコレクターエンドポイントへのメトリクスシグナルのエクスポートを有効にします。実行時の稼働状況ダッシュボードを使用する場合は有効のままにし、メトリクス量を最小限に抑える必要がある場合にのみ無効にしてください。`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`OpenTelemetryメトリクスエンドポイント`},help:{"v1-qlfh7x-47":`メトリクスシグナル専用のOTLP/HTTPエンドポイントです。設定すると、メトリクスのエクスポートに限り、diagnostics.otel.endpointとOTEL_EXPORTER_OTLP_ENDPOINTより優先されます。`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetryプロトコル`},help:{"v1-17ine8s-5e":`テレメトリのエクスポートに使用するOTelトランスポートプロトコルです。"http/protobuf"のみ使用できます。保存されている従来の"grpc"値を修正するか、設定元に応じた手動編集の手順を確認するには、"openclaw doctor --fix"を実行してください。`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`OpenTelemetryトレースサンプリング率`},help:{"v1-brcwep-50":`可観測性バックエンドにエクスポートするトレース量を制御するサンプリング率（0～1）です。低い値ではオーバーヘッドとコストが減り、高い値ではデバッグ情報の精度が向上します。`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetryサービス名`},help:{"v1-1hpiqon-5d":`可観測性バックエンドでこのGatewayインスタンスを識別するために、テレメトリのリソース属性で報告されるサービス名です。デプロイを重ねてもダッシュボードとアラートの一貫性を維持できるよう、固定の名前を使用してください。`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetryトレースを有効化`},help:{"v1-j7zrrp-4s":`設定済みのOpenTelemetryコレクターエンドポイントへのトレースシグナルのエクスポートを有効にします。レイテンシ分析やデバッグ用のトレースが必要な場合は有効のままにし、メトリクスとログのみが必要な場合は無効にしてください。`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`OpenTelemetry トレースエンドポイント`},help:{"v1-8yw5p1-43":`シグナル固有の OTLP/HTTP トレースエンドポイント。設定すると、トレースのエクスポートについてのみ diagnostics.otel.endpoint と OTEL_EXPORTER_OTLP_ENDPOINT よりも優先されます。`}},discovery:{label:{"v1-l2sr05-9":`検出`},help:{"v1-1sqleij-4w":`ローカル mDNS 広告と、任意の広域プレゼンス通知に使用するサービス検出設定。サービスのメタデータが漏洩しないよう、検出範囲を想定するネットワークに限定してください。`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS 検出`},help:{"v1-vtbyyq-4w":`ローカルネットワークでの広告と検出動作を調整するための mDNS 検出設定グループ。追加のメタデータが必要な場合を除き、通常の LAN 検出では minimal モードを使用してください。`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`mDNS 検出モード`},help:{"v1-1p28pd5-2m":`mDNS ブロードキャストモード（デフォルトは "minimal"、"full" は cliPath/sshPort を含み、"off" は mDNS を無効にします）。`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`広域検出`},help:{"v1-1akkqjm-53":`ローカルリンクの範囲を超えて検出シグナルを公開するための広域検出設定グループ。拠点間で Gateway のプレゼンス情報を意図的に集約する環境でのみ有効にしてください。`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`広域検出ドメイン`},help:{"v1-rxrygo-4m":`広域検出に使用する任意のユニキャスト DNS-SD ドメイン（例：openclaw.internal）。ローカル mDNS の範囲を超えて Gateway の検出情報を意図的に公開する場合に使用してください。`}},env:{label:{"v1-1zc80q-b":`環境`},help:{"v1-1ao5po6-55":`Gateway プロセスに実行時変数を渡すための、環境変数のインポートと上書きの設定。このセクションで、シェル環境変数の読み込みと明示的な変数注入の動作を制御します。`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`シェル環境のインポート`},help:{"v1-1gw487t-4y":`起動時にログインシェルから変数を読み込むための、シェル環境のインポート設定です。プロファイルで定義されたシークレットや PATH のカスタマイズに依存している場合は、有効のままにしてください。`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`シェル環境のインポートを有効化`},help:{"v1-5tiuup-5u":`起動時の初期化中に、ユーザーのシェルプロファイルから環境変数を読み込めるようにします。開発用マシンでは有効のままにしてください。環境変数を明示的に管理する、制限の厳しいサービス環境では無効にしてください。`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`シェル環境のインポートのタイムアウト（ミリ秒）`},help:{"v1-nsk2yf-5c":`フォールバック動作が適用されるまでに、シェル環境の解決に許可される最大時間（ミリ秒）です。起動を速くするにはタイムアウトを短くし、シェルの初期化に時間がかかる場合は長くしてください。`}},"env%2Evars":{label:{"v1-grhbhj-u":`環境変数の上書き`},help:{"v1-yxc3z7-5n":`OpenClaw の実行時プロセス環境に統合される、明示的なキーと値による環境変数の上書き設定です。シェルプロファイルの副作用だけに依存せず、環境を確実に構成するには、この設定を使用してください。`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`バインドモード、認証、Control UI、リモート通信、運用上の安全性を制御する Gateway の実行時設定です。信頼できるローカルインターフェースの外部に Gateway を意図的に公開する場合を除き、安全性を重視したデフォルト設定を維持してください。`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Gateway の x-real-ip フォールバックを許可`},help:{"v1-1wr3qmw-4c":`プロキシを使用する環境で x-forwarded-for がない場合に、x-real-ip へのフォールバックを有効にします。イングレス構成でこの互換動作が必要な場合を除き、無効のままにしてください。`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway 認証`},help:{"v1-70b6ni-50":`Gateway の HTTP/WebSocket アクセスに関する認証ポリシーです。モード、認証情報、信頼済みプロキシの動作、レート制限を含みます。ループバック以外のすべてのデプロイでは、認証を有効にしてください。`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Gateway 認証で Tailscale ID を許可`},help:{"v1-vqtmgw-53":`設定されている場合、信頼できる Tailscale ID 経由で Gateway の認証チェックを通過できるようにします。tailnet の ID セキュリティが十分に確保され、運用担当者のワークフローで必要な場合にのみ使用してください。`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Gateway ID へのスコープ付与`},help:{"v1-1h0zxy7-5n":`信頼済みプロキシまたは Tailscale で検証された ID を、その接続にのみ有効な運用担当者スコープの付与に対応付けます。メールアドレスのキーは大文字と小文字を区別せずに照合されます。付与されたスコープは、接続スコープの上限が適用される前にデバイスのスコープに追加されます。`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Gateway 認証モード`},help:{"v1-j8rodq-9t":`Gateway の認証モードです。エッジアーキテクチャに応じて "none"、"token"、"password"、"trusted-proxy" のいずれかを指定します。token/password モードでは、設定されたシークレット（gateway.auth.token または gateway.auth.password）が選択されます。クライアントは接続時のどちらの認証フィールドでも送信できます。直接公開する場合は token/password を使用し、trusted-proxy はセキュリティを強化した ID 対応プロキシの背後でのみ使用してください。`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Gateway パスワード`},help:{"v1-1ndt0u2-4g":`gateway.auth.mode=password で選択される共有シークレットです。クライアントは auth.token または auth.password のどちらでも送信できます。Tailscale Funnel には password モードが必要です。`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Gateway 認証のレート制限`},help:{"v1-1kstr42-54":`Gatewayの境界で認証情報への総当たり攻撃のリスクを軽減するため、ログイン・認証の試行を制限する設定です。外部に公開する環境では有効に保ち、通常のトラフィック量に合わせてしきい値を調整してください。`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Gatewayトークン`},help:{"v1-16i7cxs-5q":`gateway.auth.mode=tokenで選択される共有シークレットです。新規のローカル初期設定ではこれがデフォルトです。クライアントはauth.tokenまたはauth.passwordのどちらでも送信できます。ループバック以外のアドレスにバインドする場合は、認証モードを有効にする必要があります。`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gatewayの信頼済みプロキシ認証`},help:{"v1-12fsi5d-58":`ユーザークレームを挿入する上流のIDプロバイダー向けの、信頼済みプロキシ認証ヘッダーのマッピングです。IDヘッダーの偽装を防ぐため、既知のプロキシCIDRと厳格なヘッダー許可リストを使用する場合にのみ利用してください。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Cloudflare Access OIDC の GitHub ID 情報`},help:{"v1-1puth4k-6t":`選択した Cloudflare Access OIDC プロバイダーから取得する、検証済みの GitHub ID 情報（任意）。標準の Access メールヘッダーとアサーションヘッダーが必要です。クレームがない場合はメールのみのプロフィールが維持されます。既存のプロフィールのロールと共同作成者の設定は保持されます。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`GitHub アカウント ID クレーム`},help:{"v1-pcaaw7-57":`検証済みの GitHub アカウント ID を正の整数の10進文字列として値に持つ、転送された OIDC クレームの正確な名前。oidc_fields でこのクレームを転送するように Access を設定してください。ユーザーが編集できる未検証のクレームは絶対に使用しないでください。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access 発行者`},help:{"v1-gykv03-56":`信頼するCloudflare Accessチームの正確なHTTPSオリジンを、末尾のスラッシュなしで指定します（例：https://example.cloudflareaccess.com）。他の発行者からのクレームは、GitHubのID情報として使用されません。`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Cloudflare Access OIDCプロバイダーID`},help:{"v1-kbyo5w-44":`信頼するOIDC連携の正確なAccess IDプロバイダーIDを指定します。プロバイダーの表示名やクレーム名の一致だけでは、信頼は確立されません。`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`信頼済みプロキシによるデバイスの自動承認`},help:{"v1-uh32ha-6z":`信頼済みプロキシ認証後に、ブラウザーおよびネイティブUIの新規オペレーターデバイスと、同一キーのスコープ拡張を自動承認するための任意のポリシーです。権限の付与はdeviceAutoApprove.scopesによって制限され、プロキシのx-openclaw-scopesヘッダーが存在する場合は、その値によっても制限されます。`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`信頼済みプロキシによるデバイスの自動承認を有効化`},help:{"v1-1nntwls-78":`リバースプロキシが許可されたユーザーを認証した後、ブラウザーおよびネイティブUIの新規オペレーターデバイスと、同一キーのスコープ拡張を自動承認します。デフォルト：false。プロキシのID認証境界が、手動のデバイスペアリングに代わる十分な強度を備えている場合にのみ有効にしてください。`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`信頼済みプロキシのデバイス自動承認スコープ`},help:{"v1-raeila-g3":`自動承認されたオペレーターデバイスに付与するスコープの上限。デフォルトは operator.read、operator.write、operator.approvals、operator.questions です。要求されたスコープはこのリストの範囲内に制限され、スコープの指定がないリクエストにはこのリストが適用されます。未設定の場合、自動承認時に旧バージョンの UI クライアント向けに operator.questions も追加されます。明示的に指定したリストが拡張されることはありません。operator.admin を明示的にリストに含めると、プロキシ認証されたすべてのユーザーに完全な管理者権限の自動承認が許可され、スコープの指定がないリクエストにも完全な管理者権限が自動的に付与されます。また、セキュリティ監査で重大な問題として検出され、Gateway 起動時に警告が表示されます。`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Gateway バインドモード`},help:{"v1-1unqude-4y":`インターフェースの公開範囲を制御するネットワークバインドプロファイル："auto"、"lan"、"loopback"、"custom"、"tailnet"。ローカルのみで使用する場合は "loopback" を維持してください。"auto" はすべてのインターフェースを公開する可能性があります。`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI エージェント`},help:{"v1-1qqo8m2-5a":`Gatewayのセッションカタログで公開される外部CLIセッションエンジンをControl UIで検出する設定です。デフォルトでは有効です。新規セッションのモデル選択画面からこれらのエンジンを起動できないようにするには、無効にしてください。`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI エージェントの有効化`},help:{"v1-ufu7fx-8p":`true の場合、カタログに基づく CLI エージェントを Control UI の新規セッションのモデル選択画面に表示します（デフォルト：true）。CLI エージェントとネイティブ CLI セッションの作成を無効にするには、false に設定してください。セッション作成への対応を通知するカタログのみが一覧に表示されます。Gateway がセッションカタログへの対応を通知しない場合、選択画面は表示されません。`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`有効化、パス設定、ブラウザーのオリジンおよび認証のセキュリティ強化を含む、Control UI のホスティング設定です。UI の公開範囲を最小限に抑え、インターネットに公開する前に強力な認証制御を組み合わせてください。`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Control UI の許可オリジン`},help:{"v1-1stgitk-9i":`Control UI/WebChat の WebSocket 接続で許可するブラウザーのオリジンです（https://control.example.com などの完全なオリジンのみ）。危険な Host ヘッダーへのフォールバックを明示的に有効にしていない限り、ループバック以外での Control UI のデプロイには必須です。["*"] を設定すると、すべてのブラウザーオリジンが許可されるため、厳密に管理されたローカルテスト以外では使用しないでください。`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Control UI の外部埋め込み URL を許可`},help:{"v1-obwpfg-6s":`ホストされている埋め込みコンテンツによる外部の絶対 http(s) URL の読み込みを許可する、危険な設定です。Control UI で信頼できるサードパーティーのページを意図的に埋め込む場合を除き、オフのままにしてください。ホストされている /__openclaw__/canvas および /__openclaw__/a2ui ドキュメントには不要です。`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`リンクのファビコンを自動取得`},help:{"v1-bn9u34-ag":`Gateway 経由でリンクのファビコンとブラウザータブのソーシャルプレビューを取得します（デフォルトで有効）。ブラウザータブのカードは、ブラウザーの Cookie やサイトの認証情報を使用せずに、公開ページのメタデータと指定された画像を読み込みます。すべてのリクエストに厳格な SSRF チェックを適用し、HTML と画像の処理には制限を設けています。false に設定すると、ファビコンとページプレビューの自動取得が両方とも無効になります。ブラウザーのライブスクリーンショットには影響しません。`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Control UI のベースパス`},help:{"v1-1dx68ar-1w":`Control UI を配信する URL のプレフィックス（任意、例：/openclaw）。`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Control UI のコミュニティ招待`},help:{"v1-1rz3zsx-73":`この Gateway が提供する Control UI に Discord コミュニティへの招待を表示します（デフォルトでオン）。false に設定すると、この UI デプロイを使用するすべてのブラウザーで非表示になります。変更はブラウザーの再読み込みまたは再接続後に適用されます。再度有効にしても、各ブラウザーで閉じた状態は保持されます。`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Host ヘッダーベースのオリジンフォールバックを許可（危険）`},help:{"v1-1t1qi4c-7v":`Control UI/WebChat の WebSocket チェックで、Host ヘッダーベースのオリジンフォールバックを有効にする危険な設定です。このモードは、デプロイが意図的に Host ヘッダーのオリジンポリシーに依存している場合にサポートされます。セキュリティを強化するための推奨される標準設定は、引き続き gateway.controlUi.allowedOrigins の明示的な指定です。`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Control UI の埋め込みサンドボックスモード`},help:{"v1-d54l3a-7c":'ホストされる Control UI の埋め込み用 iframe サンドボックスポリシーです。"strict" はスクリプトを無効にし、"scripts" はオリジンの分離を維持しながら対話型の埋め込みを許可します（デフォルト）。"trusted" は、より強い権限を意図的に必要とする同一サイトのドキュメントに対して `allow-same-origin` を追加します。'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI の有効化`},help:{"v1-1hhyymc-4w":`true の場合、Gateway の HTTP プロセスから Gateway の Control UI を提供します。ローカル管理には有効のままにし、外部の管理インターフェースで置き換える場合は無効にしてください。`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Control UI の環境`},help:{"v1-paarso-4n":`Control UI のストライプ、エージェントのアバター、ラベルバッジ、ブラウザーのタイトル、ファビコンに表示される、任意の公開環境識別情報です。デフォルトの外観を維持するには省略してください。`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Control UI の環境カラー`},help:{"v1-mp6cta-2i":`名前で指定する環境のカラースケール：teal、amber、purple、coral、pink、blue、green、red、gray。`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Control UI の環境ラベル`},help:{"v1-1njve3z-3z":`Control UI とブラウザーのタブに表示される環境ラベルです。前後の空白は削除されます。ラベルは 1〜24 文字で指定してください。`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Control UI の実験的機能`},help:{"v1-1qobi2m-3g":`任意で有効にできる Control UI の実験的機能です。これらの機能はリリース間で変更される可能性があり、明示的に有効にしない限り無効のままです。`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`カスタムプラグイン UI`},help:{"v1-108u6ts-9e":`ユーザーがインストールしたプラグインによるControl UIでのネイティブJavaScriptの実行を許可します（デフォルト: false）。同梱のプラグインビューは引き続き利用できます。カスタムUIはログイン中のオペレーターのGateway権限を共有するため、信頼できるプラグインに対してのみ有効にしてください。変更はGatewayを再起動せずに適用されます。以前に読み込まれたプラグインコードをクリアするには、開いているControl UIのページを再読み込みしてください。`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Control UI の GitHub サービス認証情報`},help:{"v1-1p31phh-d6":`マネージド ID を使用せずに Control UI のプロジェクト検出と GitHub のホバープレビューを行うための、SecretRef に基づくサービス認証情報です。ホバープレビューでは、選択されたエージェントに設定された GitHub ID が優先され、上書き設定がない場合はシステム ID を継承します。サービスの所有者を明確にするため、明示的な設定を推奨します。省略すると、共有 Gateway プロセス環境の GH_TOKEN/GITHUB_TOKEN へのフォールバックが維持されます。明示的に設定された認証情報が利用できない場合は、安全のためアクセスを拒否します。`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Control UI アセットのルート`},help:{"v1-elck04-25":`Control UI アセット用のファイルシステム上のルート（省略可能、デフォルトは dist/control-ui）。`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Control UI セッションオブザーバー`},help:{"v1-1ahs80-8a":`各エージェントのユーティリティモデルを使用して、購読中の Control UI クライアント向けにセッション状態の要約をリアルタイムで生成します（デフォルトで有効）。false に設定すると、Gateway 全体でオブザーバーによるモデル呼び出しが無効になります。agents.defaults.utilityModel を空文字列に設定すると、この設定を上書きしていないエージェントではユーティリティモデルによる監視が無効になります。`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Gateway カスタムバインドホスト`},help:{"v1-lwjcyo-4d":`カスタムバインドに使用する IPv4 アドレスです。特定の IPv4 アドレスを指定する場合は、127.0.0.1 上でも同じ Gateway ポートが必要です。すべてのインターフェースでの公開が必要な場合を除き、0.0.0.0 は避けてください。`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`Gateway HTTP API`},help:{"v1-ebtex7-4j":`エンドポイントの有効・無効の切り替えと、トランスポート側の API 公開制御をまとめた Gateway HTTP API 設定です。攻撃対象領域を減らすため、必要なエンドポイントのみを有効にしてください。`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Gateway HTTP エンドポイント`},help:{"v1-1a0r104-55":`Gateway API の互換ルートとオプションの連携用 HTTP エンドポイントの機能切り替え設定です。エンドポイントは必要性を確認して有効にし、導入後はアクセスパターンを監視してください。`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`OpenAI Chat Completions エンドポイント`},help:{"v1-1271mpb-2b":"OpenAI 互換の `POST /v1/chat/completions` エンドポイントを有効にします（デフォルト：false）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`OpenAI Chat Completions の画像制限`},help:{"v1-xgscw1-20":"OpenAI 互換の `image_url` パートの画像取得・検証設定です。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`OpenAI Chat Completions の画像 MIME 許可リスト`},help:{"v1-1guijf3-1t":"`image_url` パートで許可する MIME タイプです（大文字と小文字を区別しないリスト）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`OpenAI Chat Completions の画像 URL を許可`},help:{"v1-55cb3n-47":"`image_url` パートの URL からサーバー側で取得することを許可します（デフォルト：false。データ URI は引き続きサポートされます）。URL からの取得を完全に無効にするには、`false` に設定してください。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`OpenAI Chat Completions の画像の最大バイト数`},help:{"v1-d920yx-1s":"取得・デコードされた `image_url` 画像 1 枚あたりの最大バイト数です（デフォルト：10MB）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`OpenAI Chat Completions 画像の最大リダイレクト数`},help:{"v1-1enujsk-1z":"`image_url` の URL 取得時に許可する HTTP リダイレクトの最大回数（デフォルト: 3）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`OpenAI Chat Completions 画像のタイムアウト（ミリ秒）`},help:{"v1-89w2b9-1x":"`image_url` の URL 取得時のタイムアウト（ミリ秒単位、デフォルト: 10000）。"}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`OpenAI Chat Completions 画像 URL の許可リスト`},help:{"v1-n4hlt1-4r":"`image_url` の URL 取得に使用する任意のホスト名許可リスト。ホスト名の完全一致と `*.example.com` 形式のワイルドカードに対応しています。リストが空または省略されている場合、ホスト名の許可リストによる制限はありません。"}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Gateway HTTP セキュリティヘッダー`},help:{"v1-n8z1hb-44":`Gateway プロセス自体が適用する任意の HTTP レスポンスセキュリティヘッダー。リバースプロキシで TLS を終端する場合は、そちらで設定することを推奨します。`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Strict Transport Security ヘッダー`},help:{"v1-1buwhc3-3v":`Strict-Transport-Security レスポンスヘッダーの値。完全に管理下にある HTTPS オリジンでのみ設定してください。明示的に無効にするには false を使用します。`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway モード`},help:{"v1-nfjirv-5m":`Gateway の動作モード："local" はこのホストでチャネルとエージェントランタイムを実行し、"remote" はリモートトランスポート経由で接続します。リモート Gateway を分離した構成で意図的に運用する場合を除き、"local" のままにしてください。`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Gateway ノードの Skills を有効化`},help:{"v1-1xwu6at-3g":`ペアリング済みノードが接続中に公開するスキルを受け入れます（デフォルト：true）。ノードが公開するスキルを無視するには false に設定してください。`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Gateway ノードのブラウザモード`},help:{"v1-oeu1nc-69":`ノードのブラウザールーティング（"auto" = ホストのブラウザーを優先し、ローカルの機能が利用できない場合は接続済みのブラウザーノード1台を使用します。"manual" = ノードの明示的な選択または固定先の設定が必要です。"off" = ノードルーティングを無効にします）。`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Gateway ノードのブラウザ接続先固定`},help:{"v1-1cykty2-1p":`ブラウザのルーティング先を特定のノード ID または名前に固定します（任意）。`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Gateway ノードの許可リスト（追加コマンド）`},help:{"v1-6l4otb-5m":"Gateway のデフォルトに加えて許可する node.invoke コマンド（コマンド文字列の配列）。ここで危険なコマンドを有効にすると、セキュリティに関わる設定の上書きとなり、`openclaw security audit` で警告されます。"}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Gateway ノードの拒否リスト`},help:{"v1-u7c8wx-53":"ノードの申告内容やデフォルトの許可リストに含まれていてもブロックするノードコマンド名（`system.run` など、コマンド名の完全一致のみ。そのコマンド内のシェルテキストは検査しません）。"}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Gateway ノードのペアリング`},help:{"v1-gldsi2-4s":`ノードのペアリングポリシー設定です。SSH 検証による自動承認はデフォルトで有効です。CIDR による自動承認は、信頼する CIDR/IP の許可リストを明示的に設定しない限り無効のままです。`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`Gateway ノードのペアリングを自動承認する CIDR`},help:{"v1-1m6jsxj-6x":`要求スコープのないノードロールのデバイスの初回ペアリングを自動承認するための、任意設定の CIDR/IP 許可リストです。未設定の場合は無効です。オペレーター、ブラウザー、Control UI のペアリング、およびロール、スコープ、メタデータ、公開鍵のアップグレードを伴うペアリングには、引き続き手動承認が必要です。`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Gateway ノードのローカルペアリングの自動承認`},help:{"v1-glzm36-41":`信頼するローカルペアリングとアクセス権のアップグレードを確認なしで承認します（デフォルト: true）。利便性よりもすべてのデバイスの明示的な承認を優先する場合は、false に設定してください。`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Gateway ノードのペアリングの SSH 検証`},help:{"v1-1e4da92-ct":"ノードロールのデバイスの初回ペアリングを SSH 検証により自動承認します（デフォルト: 有効）。Gateway はペアリング元のホストに SSH で接続し（BatchMode、厳密なホスト鍵検証）、リモートの `openclaw node identity` の出力が承認待ちのデバイス鍵と一致する場合にのみ承認します。SSH 検証を無効にするには false に設定してください（autoApproveCidrs とは独立しており、そちらは引き続き有効です）。ペアリングを手動承認のみにするには、autoApproveCidrs も未設定にしてください。user/identity/timeoutMs/cidrs を上書きするには、オブジェクトを渡してください。"}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Gateway ノードのプラグインツール`},help:{"v1-1c24iq3-28":`ペアリング済みノードが、エージェントから参照できるプラグインツールの記述子を公開できるかどうかを制御します。`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Gateway ノードのプラグインツールを有効化`},help:{"v1-14lgfu6-47":`ペアリング済みノードが公開する、エージェントから参照可能なプラグインツールの記述情報を受け入れます（デフォルト: true）。false に設定すると、ノードが公開するすべてのプラグインツールを無視して削除します。`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway ポート`},help:{"v1-for8t5-54":`API、Control UI、およびチャネル向けの受信経路で Gateway リスナーが使用する TCP ポートです。専用のポートを使用し、リバースプロキシやローカルの開発用サービスとの競合を避けてください。`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gatewayポータル`},help:{"v1-1v2lkw9-1c":`ポータルの公開とプライベートイングレスの設定。`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`プライベートポータルイングレス`},help:{"v1-20w4gq-69":`任意で使用できる、運用担当者が管理するプライベートHTTPSワイルドカードリバースプロキシです。元のHost、パス、WebSocketアップグレードを専用のループバックリスナーに転送してください。ポータルのBearer認証は引き続き必要です。Gatewayの再起動が必要です。`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`ポータルのワイルドカードドメイン`},help:{"v1-1ipbfad-53":`ランダムなポータルサブドメイン用のDNSドメイン名（例：previews.example.net）。プロトコルやパスは含めません。ワイルドカードDNSとHTTPSはプライベート環境で設定してください。GatewayまたはControl UIのホスト名の名前空間と共用しないでください。`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`ポータルイングレスのループバックポート`},help:{"v1-1mb98cv-4g":`プライベートワイルドカードHTTPSプロキシからのリクエストを受信する専用のループバックHTTPポート。Gatewayポートとは異なるポートを指定する必要があります。これはバックエンドのポートであり、公開HTTPSポートではありません。`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Gateway 公開オリジン`},help:{"v1-17vekvx-87":`外部からアクセス可能な Gateway の HTTPS オリジンです。HTTP は localhost、127.0.0.1、または [::1] でのみ許可されます。リクエスト元ごとの MCP OAuth は、これを使用して /oauth/mcp/callback のコールバック URL を構築します。チャネルのセッションリンクやプラグインが生成するビューアーリンクは、これを使用して Control UI と Gateway のルートにアクセスします。`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gateway プッシュ配信`},help:{"v1-h23oz7-5s":`ペアリング済みデバイスのスリープ解除や通知が必要なときに Gateway が使用するプッシュ配信設定です。公式 iOS ビルド向けのリレー経由の APNs はここで設定します。ローカルビルドや手動ビルドでの直接 APNs 認証は、引き続き環境変数で設定します。`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gateway APNs 配信`},help:{"v1-4bbafr-4e":`この Gateway とペアリング済みの iOS デバイス向け APNs 配信設定です。外部プッシュリレー経由で登録する公式 App Store ビルドには、リレー設定を使用してください。`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Gateway APNs リレー`},help:{"v1-7glbel-6x":`リレー経由のAPNs送信に使用する外部リレーの設定です。ペアリング済みの公式iOSビルドがリレー経由の登録情報を公開すると、Gatewayはpush.test、ウェイクの促進、再接続時のウェイクに、デフォルトのホスト型OpenClawリレーまたはこのカスタムリレーを使用します。`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Gateway APNsリレーのベースURL`},help:{"v1-1o8mgnq-69":`公式App Store iOSビルドが使用する外部APNsリレーサービスのカスタムベースHTTPS URL（任意）です。登録と送信のトラフィックが同じデプロイ先に届くように、iOSビルドに組み込まれたリレーURLと一致させてください。`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Gateway APNsリレーのタイムアウト（ミリ秒）`},help:{"v1-a0jkb1-4z":`GatewayからAPNsリレーへのリレー送信リクエストのタイムアウト時間（ミリ秒、デフォルト：10000）です。リレーやネットワークが遅い場合は値を大きくし、ウェイク試行をより早く失敗と判定する場合は小さくしてください。`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`設定の再読み込み`},help:{"v1-d02mvq-4w":`編集内容の適用方法と完全な再起動のタイミングを定める、実行中の設定再読み込みポリシーです。再読み込みの内部処理をデバッグする場合を除き、運用中の更新を最も安全に行うため、ハイブリッド動作を維持してください。`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`設定の再読み込みモード`},help:{"v1-1q1etcf-3m":`設定の編集内容の適用方法を制御します。"off"は実行中の編集を無視し、"hybrid"は実行中でも安全に適用できる変更を反映した後、必要に応じて再起動します。`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`リモートGateway`},help:{"v1-6xv7gd-5a":`このインスタンスが別のランタイムホストへのプロキシとして動作する場合の、直接接続またはSSH経由のリモートGateway接続設定です。リモートモードは、ホストを分けた運用を意図的に構成している場合にのみ使用してください。`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`リモート Gateway のエッジ認証ヘッダー`},help:{"v1-jg9p7d-5o":`設定済みのリモート Gateway の手前にある ID 認識型プロキシに送信する、シークレットに基づく HTTP ヘッダーです。ヘッダーは WSS 経由で gateway.remote.url と完全に一致するオリジンにのみ送信され、リダイレクトには一切追従しません。`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`リモート Gateway のパスワード`},help:{"v1-16jc0yx-7y":`このクライアントをリモート Gateway に認証するために、password フィールドで送信する共有シークレットです。サーバーの gateway.auth.mode によって、設定済みのシークレットが選択されます。クライアントの token フィールドと password フィールドのどちらも使用できます。このシークレットは外部で管理し、コミットする設定に平文の値を含めないでください。`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`リモート Gateway の SSH ホストキーポリシー`},help:{"v1-7qoxtb-49":`macOS の SSH ホストキー検証ポリシーです。"strict" では、すでに信頼されているホストキーが必要です。"openssh" では、有効な OpenSSH 設定に検証を明示的に委ねます。`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`リモート Gateway の SSH ID`},help:{"v1-hz2hsm-1f":`SSH ID ファイルのパス（任意）。ssh -i に渡されます。`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`リモート Gateway の SSH 接続先`},help:{"v1-85w39w-2t":`SSH 経由で接続するリモート Gateway（Gateway のポートを localhost にトンネリングします）。形式：user@host または user@host:port。`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`リモート Gateway の TLS フィンガープリント`},help:{"v1-1ri16lk-23":`リモート Gateway の想定される sha256 TLS フィンガープリント（中間者攻撃を防ぐために固定します）。`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`リモート Gateway のトークン`},help:{"v1-1pb9q8w-7v":`このクライアントをリモート Gateway に対して認証するために、token フィールドで送信される共有シークレットです。サーバーの gateway.auth.mode によって、設定済みのシークレットが選択されます。クライアントの token フィールドと password フィールドのどちらも使用できます。シークレットまたは環境変数の置換を使用して保存し、リモート Gateway の認証設定の変更に合わせてローテーションしてください。`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`リモート Gateway のトランスポート`},help:{"v1-1acfs7m-54":`リモート接続のトランスポートです。"direct" は設定済みの URL を使用して接続し、"ssh" は SSH 経由でトンネリングします。リモートポートを公開せずに暗号化トンネルを使用する必要がある場合は、SSH を使用してください。`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`リモート Gateway の URL`},help:{"v1-va7exe-1b":`リモート Gateway の WebSocket URL（ws:// または wss://）。`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Gateway のオペレーターロール`},help:{"v1-b59sc5-6w":`チーム用 Gateway で使用する、プロファイルに紐づく任意のオペレーターロールです。各名前付きロールは、他のユーザーのセッションへのアクセス、サンドボックスの分離、セッションおよび実行で使用するエージェント、付与されるオペレータースコープを制御します。このセクションを省略すると、既存のオペレーターの動作が維持されます。`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`デフォルトのオペレーターロール`},help:{"v1-1v8add8-4u":`オペレーターロールが設定されている場合に、有効な明示的割り当てがない認証済みプロファイルへ割り当てられる必須のロールです。名前は、設定済みのロール定義と一致する必要があります。`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`オペレーターロールの定義`},help:{"v1-uv91an-53":`管理者が名前を付ける、空にできないロール定義です。認証済みユーザープロファイルに適用される、選択肢が限定されたセッション共有、サンドボックス分離、エージェントアクセス、オペレータースコープの各ポリシーをまとめます。`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`オペレーターロールの定義`},help:{"v1-p8tfws-6q":`名前付きのオペレーターロールを1つ定義します。各定義には、セッション共有ポリシー、セッションおよび実行に許可するエージェント、オペレータースコープの上限を明示する必要があります。また、新規作成セッションのサンドボックス隔離や、プラグインのアクセスポリシーを必須にすることもできます。`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`オペレーターロールのアクセスポリシープラグイン`},help:{"v1-1gq4q08-9n":`このロールの認可をGatewayアクセスポリシーに要求するプラグインの正確なIDです。指定は任意です。プラグインが存在しない、無効になっている、読み込みに失敗する、または現在有効な認可情報を提供しない場合、アクセスは拒否されます。利用できないプラグインIDも設定としては有効なままなので、独立したスタッフロールやGateway所有者がアクセスを修復できます。このフィールドを省略した場合、プラグインへの依存は追加されません。`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`オペレーターロールで許可するエージェント`},help:{"v1-fvun18-4v":`このロールがセッションを作成したり実行を開始したりする際に使用できるエージェントです。すべてのエージェントを許可するには "*" を設定し、特定のエージェントのみを許可するにはそのエージェントIDを指定します。両方の操作を無効にするには空のリストを使用します。`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`オペレーターロールのサンドボックス分離`},help:{"v1-sknx21-66":`新しく作成するセッションの実行環境を分離します。"inherit"（デフォルト）はエージェントのポリシーを使用します。"required" は、エージェントのサンドボックスモードがオフでもサンドボックスを永続的に必須とし、バックエンドが利用できない場合は安全のため実行を拒否します。`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`オペレーターロールのスコープ上限`},help:{"v1-1selr2i-4s":`このロールの接続権限の上限として付与するオペレータースコープを限定列挙したリストです。要求されたスコープ、ペアリングで付与されたスコープ、IDに基づいて付与されたスコープ、および昇格されたスコープは、このリストとの共通部分に制限されます。`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`オペレーターロールのセッションアクセス`},help:{"v1-hsoiop-45":`他の認証済みユーザーが作成したセッションについて、このロールに付与するセッション共有権限です。ユーザー自身のセッションには、引き続き所有者としてアクセスできます。`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`オペレーターロールの他のセッションへのアクセス`},help:{"v1-vf8umx-5r":`他のユーザーのセッションへのアクセス："none" は非表示、"view" は閲覧を許可、"suggest" は提案フローを許可、"write" は参加を許可します。明示的なセッションメンバーシップにより、追加のアクセス権が付与される場合があります。`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Gateway Tailscale`},help:{"v1-6ar9o-4x":`Serve/Funnel による公開と、Gateway の起動・終了時のライフサイクル処理に関する Tailscale 連携設定です。デプロイ環境で Tailscale 経由の受信アクセスを意図的に利用する場合を除き、オフのままにしてください。`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Gateway Tailscale モード`},help:{"v1-6l2099-5a":`Tailscale の公開モード：非公開または公開のアクセス経路に応じて、"off"、"serve"、"funnel" を指定します。tailnet 内のみのアクセスには "serve" を使用し、パブリックインターネットからのアクセスが必要な場合にのみ "funnel" を使用してください。`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Gateway Tailscale 外部 Funnel 移行ガード`},help:{"v1-1mntkor-7q":`mode='serve' 用の非推奨の移行ガードです。外部 Funnel が引き続き通常の Gateway リスナーを対象としている場合、OpenClaw は公開状態を変更せず、パスワード認証を設定してモードを 'funnel' に移行するまでは、プラグインで認証された Webhook のみが利用可能であることを警告します。`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`オペレーターターミナル`},help:{"v1-18f5rgm-8b":`Control UI とモバイルクライアントに提供されるオペレーターターミナルです。Gateway ホスト上の PTY ベースのシェルで、管理者スコープのオペレーターセッションに限定されます。対象エージェントのワークスペースで起動します。完全にサンドボックス化されたエージェント（sandbox.mode 'all'）では、制限のないホストシェルを提供するのではなく、利用を拒否します。`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`オペレーターターミナルのデタッチされたセッションのタイムアウト`},help:{"v1-k6qbgr-9e":`接続が切れた後（ノートPCのスリープ、ページの再読み込みなど）にターミナルセッションを維持する秒数です。この間は terminal.attach で再接続でき、直近の出力が再表示されます。接続が切れた時点で即座にセッションを終了するには、0 に設定します。デフォルト：300（5分）。切断されたセッションでもコマンドは実行され続けるため、共有ホストや外部に公開されたホストでは、この値を短くしてください。`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`オペレーター用ターミナルの有効化`},help:{"v1-1nez06v-7p":`管理者スコープのクライアント向けにオペレーターターミナルを有効にします（デフォルト：true）。これにより、Gatewayプロセスの環境を使用するシェルがブラウザーやモバイルから利用可能になります。管理者オペレーターにホストシェルを提供すべきでないデプロイ環境では、falseに設定して無効にしてください。変更はGatewayを再起動せずに適用されます。`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`オペレーター用ターミナルのシェル`},help:{"v1-19mfe6t-5i":`オペレーター用ターミナルが起動するシェル実行ファイルです。未設定の場合はホストのログインシェル（Unix では $SHELL、Windows では %ComSpec%）を使用します。オペレーターの環境を統一するには、インタープリターを明示的に指定してください。`}},"gateway%2Etls":{label:{"v1-103eqog-b":`Gateway TLS`},help:{"v1-1dx77dq-4z":`Gateway プロセス内で HTTPS を直接終端するための TLS 証明書と鍵の設定です。本番環境では証明書を明示的に指定し、信頼できないネットワーク上で平文通信を公開しないでください。`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Gateway TLS 証明書の自動生成`},help:{"v1-1ld6uiu-4w":`ファイルが明示的に設定されていない場合に、ローカル TLS 証明書と鍵のペアを自動生成します。ローカル環境や開発環境でのみ使用し、本番環境の通信には正式な証明書に置き換えてください。`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Gateway TLS CA パス`},help:{"v1-andqlu-52":`Gateway のエッジでクライアント検証やカスタム信頼チェーンの要件に対応するための、省略可能な CA バンドルのパスです。プライベート PKI やカスタム証明書チェーンを使用するデプロイ環境で設定してください。`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Gateway TLS 証明書パス`},help:{"v1-1wznaof-4q":`TLS が有効な場合に Gateway が使用する TLS 証明書ファイルのファイルシステム上のパスです。管理された証明書パスを使用し、自動更新の設定もこの場所に合わせてください。`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`Gateway TLS の有効化`},help:{"v1-ykhwp0-4o":`Gateway のリスナーで TLS 終端を有効にし、クライアントが HTTPS/WSS 経由で直接接続できるようにします。インターネットに直接公開する場合や、信頼できないネットワークとの境界では、有効にしておいてください。`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Gateway TLS 鍵パス`},help:{"v1-15knri0-4i":`TLS が有効な場合に Gateway が使用する TLS 秘密鍵ファイルのファイルシステム上のパスです。この鍵ファイルへのアクセス権限を制限し、セキュリティポリシーに従って鍵をローテーションしてください。`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Gateway ツール公開ポリシー`},help:{"v1-1ffol26-5a":`エージェントやツールのプロファイルとは独立して、実行時に利用可能なツールを制限できる、Gateway レベルのツール公開の許可・拒否ポリシーです。緊急時の大まかな制御や、本番環境のセキュリティ強化に使用してください。`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Gateway ツール許可リスト`},help:{"v1-163khb1-4y":`実行時に利用可能なツールを少数に絞りたい場合に使用する、Gateway レベルの明示的なツール許可リストです。ツールの利用範囲を厳密に管理する必要がある、制限の厳しい環境で使用してください。`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Gateway ツール拒否リスト`},help:{"v1-1lhssnf-4o":`下位レベルのポリシーで許可されていても、リスクの高いツールをブロックする、Gateway レベルの明示的なツール拒否リストです。緊急対応や多層防御の強化に拒否ルールを使用してください。`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`Gateway の信頼済みプロキシ CIDR`},help:{"v1-n5zcvf-4f":`転送されたクライアントの識別情報ヘッダーの提供を許可する、上流プロキシの CIDR/IP 許可リストです。信頼できない中継点がユーザーになりすますことがないよう、このリストは必要最小限にしてください。`}},hooks:{label:{"v1-j9ywl7-5":`フック`},help:{"v1-1mzh0ry-5v":`外部イベントを OpenClaw のウェイクまたはエージェントのアクションにマッピングする、受信 Webhook の自動化インターフェースです。信頼済みネットワークの外部に公開する前に、トークン、セッション、エージェントの明示的な制御でアクセスを厳しく制限してください。`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`フックで許可するエージェント ID`},help:{"v1-hree88-7c":`フックリクエストとマッピングが対象にできる、実効エージェント ID の許可リストです。agentId が省略された場合のデフォルトエージェントへのルーティングも含まれます。自動化イベントの対象を専用のサービスエージェントに限定し、フックトークンが漏えいした場合の影響範囲を抑えるために使用してください。`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`フックで許可するセッションキーのプレフィックス`},help:{"v1-b346oh-4r":`呼び出し元によるキーの指定が有効な場合に、受信フックリクエストで受け入れるセッションキーのプレフィックスの許可リストです。任意のセッションキーの挿入を防ぐため、プレフィックスの範囲を絞ってください。`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`フックリクエストでのセッションキー指定を許可`},help:{"v1-11n9ps-52":`true の場合、呼び出し元がフックリクエストにセッションキーを指定でき、ルーティングを制御できるようになります。信頼済みの連携元が独自のセッション紐付けを明示的に必要とする場合を除き、false のままにしてください。`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`フックのデフォルトセッションキー`},help:{"v1-bzdgkn-57":`リクエストが許可されたチャネル経由でセッションキーを指定しない場合に、フック配信に使用されるフォールバック用のセッションキーです。無関係な自動化の会話が混在しないよう、固定かつ適切なスコープのキーを使用してください。`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`フックを有効化`},help:{"v1-1mixmjf-4n":`受信する Webhook リクエストに対して、フックエンドポイントとマッピング実行パイプラインを有効にします。外部イベントを Gateway にルーティングしていない場合は、無効のままにしてください。`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail フック`},help:{"v1-4cibmt-4r":`Pub/Sub 通知と、任意で有効にできるローカルコールバックの提供に使用される Gmail プッシュ連携の設定です。可能な限り、Gmail 自動化専用アカウントに対象を限定してください。`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Gmail フックのアカウント`},help:{"v1-12l1h96-4v":`このフック連携で Gmail の監視やサブスクリプション操作に使用される Google アカウントの識別子です。操作権限を分離するため、自動化専用のメールボックスアカウントを使用してください。`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Gmail フックで安全でない外部コンテンツを許可`},help:{"v1-1w3gdvs-55":`有効にすると、サニタイズ処理が不十分な Gmail の外部コンテンツを処理に渡すことを許可します。安全な既定設定を維持するため無効のままにし、変換処理が管理されている信頼できるメールストリームに対してのみ有効にしてください。`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Gmail フックのコールバック URL`},help:{"v1-19fhn6q-4z":`Gmail または仲介サービスが、このフックパイプラインに通知を配信するために呼び出す公開コールバック URL です。トークン検証とネットワークへの公開範囲の制限で、この URL を保護してください。`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Gmail フックに本文を含める`},help:{"v1-14cf1c3-52":`true の場合、後続のマッピングやエージェント処理のためにメール本文を取得して含めます。ペイロードのサイズが増え、機密性も高まるため、本文が必要な場合を除き false のままにしてください。`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Gmail フックのラベル`},help:{"v1-9zpdg8-4g":`フックイベントをトリガーするメッセージをラベルで限定する、任意の Gmail ラベルフィルターです。無関係な受信メールによって自動処理が大量に実行されないよう、フィルターの対象を絞ってください。`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Gmail フックの本文の最大バイト数`},help:{"v1-2aaxx1-4b":`includeBody が有効な場合に、イベントごとに処理する Gmail ペイロードの最大バイト数です。大きすぎるメッセージの処理コストとリスクを抑えるため、上限は控えめに設定してください。`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Gmail フックのモデル上書き`},help:{"v1-1var65t-59":`メールボックスの自動処理で専用のモデル動作が必要な場合に、Gmail をトリガーとする実行のモデルを上書きする任意の設定です。メールボックスのタスクに特化した設定が必要でない限り、未設定のままにしてエージェントの既定値を継承してください。`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Gmail フックのプッシュトークン`},help:{"v1-h1vx01-4o":`通知を処理する前に、Gmail プッシュフックのコールバックで必要となる共有シークレットトークンです。環境変数による置換を使用し、コールバックのエンドポイントを外部に公開する場合はトークンを定期的に更新してください。`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Gmail フックの更新間隔（分）`},help:{"v1-pr1z9-49":`Gmail の監視サブスクリプションの期限切れを防ぐための更新間隔（分単位）です。プロバイダーの有効期間より短く設定し、ログで更新の失敗を監視してください。`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Gmail フックのローカルサーバー`},help:{"v1-hom4wq-54":`独立したイングレス層を介さずに Gmail 通知を直接受信するためのローカルコールバックサーバーの設定ブロックです。このプロセス自体で Webhook トラフィックを終端する場合にのみ有効にしてください。`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Gmail フックサーバーのバインドアドレス`},help:{"v1-55bieu-4d":`フックを直接処理する際に使用するローカル Gmail コールバック HTTP サーバーのバインドアドレスです。外部からのアクセスが明示的に必要な場合を除き、ループバックのみに制限してください。`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Gmail フックサーバーのパス`},help:{"v1-1jqhcw4-4h":`ローカル Gmail コールバックサーバーでプッシュ通知を受け付ける HTTP パスです。イベントの取りこぼしを防ぐため、サブスクリプション設定と一致させてください。`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Gmail フックサーバーのポート`},help:{"v1-1yku7dz-43":`serve モードが有効な場合のローカル Gmail コールバック HTTP サーバーのポートです。ゲートウェイや制御インターフェースとの競合を避けるため、専用ポートを使用してください。`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail フックのサブスクリプション`},help:{"v1-127h8vg-5b":`設定されたトピックから Gmail の変更通知を受信するためにゲートウェイが使用する Pub/Sub サブスクリプションです。複数のコンシューマーが予期せず競合しないよう、サブスクリプションの所有者を明確にしてください。`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Gmail フックの Tailscale`},help:{"v1-7jzidp-4l":`Serve/Funnel ルートを通じて Gmail コールバックを公開するための Tailscale 公開設定ブロックです。パブリックなイングレス経路を有効にする前に、プライベート tailnet モードを使用してください。`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Gmail フックの Tailscale モード`},help:{"v1-vhm395-4u":`Gmail コールバック用の Tailscale 公開モード："off"、"serve"、"funnel"。プライベートな tailnet 内での配信には "serve" を使用し、パブリックインターネットからの受信が必要な場合にのみ "funnel" を使用してください。`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Gmail フックの Tailscale パス`},help:{"v1-fr8qi-4m":`有効時に Gmail コールバックを転送するために Tailscale Serve/Funnel が公開するパス。リクエストが想定したハンドラーに届くよう、Gmail の Webhook 設定と一致させてください。`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Gmail フックの Tailscale 転送先`},help:{"v1-1twwxge-47":`Tailscale Serve/Funnel の転送先となるローカルサービス（例：http://127.0.0.1:8787）。ルーティングの曖昧さを避けるため、ループバックの転送先を明示的に指定してください。`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Gmail フックの思考量の上書き`},help:{"v1-17owk9q-4z":`Gmail を起点とするエージェント実行の思考量の上書き設定："off"、"minimal"、"low"、"medium"、"high"。日常的な受信トレイの自動処理では、コストと遅延を抑えるため、デフォルトを控えめに設定してください。`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Gmail フックの Pub/Sub トピック`},help:{"v1-iled0e-4p":`Gmail の監視機能がこのアカウントの変更通知を配信するために使用する Google Pub/Sub トピック名。監視を有効にする前に、トピックの IAM で Gmail に公開権限が付与されていることを確認してください。`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`内部フック`},help:{"v1-piq9k-4v":`モジュールパスから読み込まれる、同梱またはカスタムのイベントハンドラー用の内部フック実行時設定。信頼できるプロセス内の自動処理に使用し、ハンドラーの読み込み範囲を厳密に制限してください。`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`内部フックを有効化`},help:{"v1-1wv0289-4c":`内部フックランタイムで、内部フックと設定済みエントリの処理を有効にします。内部フックを意図的に設定している場合を除き、無効のままにしてください。`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`内部フックのエントリ`},help:{"v1-1ovi38l-4o":`具体的なランタイムハンドラーとメタデータの登録に使用する、設定済みの内部フックエントリのレコードです。本番環境の動作を監査できるよう、エントリを明示的に定義し、バージョン管理してください。`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`内部フックローダー`},help:{"v1-11re5ph-4p":`起動時にハンドラーモジュールを検索する場所を制御する、内部フックローダーの設定です。読み込み元のルートを限定して、意図しないモジュールの競合やシャドーイングを減らしてください。`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`内部フックの追加ディレクトリ`},help:{"v1-1xfdqxg-4c":`デフォルトの読み込みパスに加えて、内部フックモジュールを検索するディレクトリです。意図しないモジュールのシャドーイングを減らすため、必要最小限に抑えて管理してください。`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`フックマッピング`},help:{"v1-frhp3v-5i":`受信したフックリクエストを照合し、wake または agent アクションを選択する、順序付きのマッピングルールです。必要に応じて配信先のルーティングも指定できます。広範なパターンのルールがすべてに一致しないよう、具体的なマッピングを先に配置してください。`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`フックマッピングのアクション`},help:{"v1-1r5zt5f-5f":`マッピングのアクション種別です。"wake" はエージェントの起動フローをトリガーし、"agent" はエージェントの処理に直接送信します。即時実行には "agent" を、ハートビートに基づく処理を優先する場合は "wake" を使用してください。`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`フックマッピングのエージェント ID`},help:{"v1-l0uioz-4y":`アクションのルーティングでデフォルトを使用しない場合に、マッピングの実行対象となるエージェントIDです。専用の自動化エージェントを使用して、Webhookの動作をオペレーターの対話型セッションから分離してください。`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`フックマッピングで安全でない外部コンテンツを許可`},help:{"v1-1np9426-57":`trueの場合、マッピングによって生成されるメッセージに、サニタイズが十分でない外部ペイロードデータが含まれることがあります。デフォルトではfalseのままにし、変換ロジックを確認済みの信頼できるソースに対してのみ有効にしてください。`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`フックマッピングの配信チャネル`},help:{"v1-oz7pu5-5s":`マッピング出力の配信チャネルを上書きします（例："last"、"telegram"、"discord"、"slack"、"signal"、"imessage"、"msteams"）。意図せず別のチャネルに送信されることを防ぐため、チャネルの上書きは明示的に指定してください。`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`フックマッピングの返信を配信`},help:{"v1-12tbbam-5o":`マッピングの実行結果をチャネルの送信先に配信するか、通知せずに処理するかを制御します。ユーザー向けの出力を投稿すべきでないバックグラウンドの自動処理では、配信を無効にしてください。`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`フックマッピングのファンアウトキー`},help:{"v1-1d593op-7e":`マッピングが各要素に処理を展開する、ペイロードの最上位の配列キーです。各要素がそれぞれのアクションを実行し、テンプレートや変換には、配列に現在の要素だけを含むペイロードが渡されます。GmailプリセットではforEach: messagesを使用するため、バッチ化されたプッシュ通知でもメールごとに1回の実行が行われます。`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`フックマッピングID`},help:{"v1-q1t4zw-57":`監査、トラブルシューティング、対象を指定した更新に使用する、フックマッピング項目の任意の固定識別子です。ログや設定の差分でマッピングを明確に参照できるよう、一意のIDを使用してください。`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`フックマッピングの一致条件`},help:{"v1-6u73k2-5a":`アクションのルーティングが適用される前に評価する、パスやソースなどのマッピング一致条件をまとめるオブジェクトです。無関係なWebhookトラフィックが自動処理を起動しないよう、一致条件を具体的に設定してください。`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`フックマッピングの一致パス`},help:{"v1-1d7dc5j-4k":`フックマッピングのパス一致条件です。通常は受信リクエストのパスと比較されます。Webhookエンドポイントのパスグループごとに自動処理の動作を分けるために使用します。`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`フックマッピングの一致ソース`},help:{"v1-177zgy7-52":`フックマッピングのソース一致条件です。通常は信頼できる上流のメタデータやアダプターのロジックによって設定されます。再試行時もルーティング結果が一定になるよう、固定のソース識別子を使用してください。`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`フックマッピングのメッセージテンプレート`},help:{"v1-ggqszl-5c":`構造化されたマッピング入力から、対象のアクションパスに送信する最終的なメッセージ内容を生成するためのテンプレートです。後続の解析や動作が安定するよう、同じ入力から常に同じ結果が得られるテンプレートにしてください。`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`フックマッピングのモデル上書き`},help:{"v1-10qyo4j-5e":`自動化でエージェントのデフォルトとは異なるモデルを使用する場合に、マッピングによってトリガーされる実行のモデルを任意で上書きします。マッピング実行時の動作を予測しやすくするため、使用は必要最小限にしてください。`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`フックマッピング名`},help:{"v1-zrd9tn-4v":`診断や運用担当者向けの設定UIで使用する、わかりやすいマッピングの表示名です。インシデント調査時にルーティングの意図が明確になるよう、簡潔で内容を表す名前にしてください。`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`フックマッピングのセッションキー`},help:{"v1-lfnt1n-58":`マッピング経由で配信されるメッセージのセッションキーを明示的に上書きし、スレッドの継続性を制御します。繰り返し発生するイベントを関連付けつつ、無関係な会話に混入しないよう、適切なスコープを持つ安定したキーを使用してください。`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`フックマッピングのセッションモード`},help:{"v1-1ggtdze-5k":`マッピングのセッション継続性を制御します。"isolated" は新しい実行セッションを開始し、"persistent" は解決済みの sessionKey を再利用します。連携で意図的に永続的なコンテキストが必要な場合を除き、isolated のままにしてください。`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`フックマッピングのテキストテンプレート`},help:{"v1-1rg732b-4y":`リッチなペイロード表示が不要、またはサポートされていない場合に使用する、テキストのみのフォールバックテンプレートです。チャット配信先に簡潔で一貫した要約文字列を提供するために使用します。`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`フックマッピングの思考設定の上書き`},help:{"v1-17hq8me-57":`マッピングによって起動される実行の思考量を上書きし、レイテンシと推論の深さを調整する任意の設定です。大量のフックを処理する場合は、深い推論が明らかに必要でない限り、低または最小に抑えてください。`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`フックマッピングのタイムアウト（秒）`},help:{"v1-1r44ox2-4i":`タイムアウト処理が適用されるまでに許容される、マッピングアクションの最大実行時間です。大量のWebhookを送信するソースには短めの制限を設定し、キューの滞留を防いでください。`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`フックマッピングの配信先`},help:{"v1-1p7928e-55":`マッピングの返信を固定の宛先に送る場合に使用する、選択したチャネル内の宛先識別子です。本番環境でマッピングを有効にする前に、プロバイダー固有の宛先形式を確認してください。`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`フックマッピングの変換`},help:{"v1-14igxpm-5m":`マッピングアクションの処理前に行う、モジュールとエクスポートによる前処理を定義する変換設定ブロックです。レビュー済みのコードパスにある変換のみを使用し、再現可能な自動化のために動作を決定論的に保ってください。`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`フック変換のエクスポート`},help:{"v1-atn8v-4b":`変換モジュールから呼び出す名前付きエクスポートです。省略すると、モジュールのデフォルトエクスポートが使用されます。1つのファイルに複数の変換ハンドラーがある場合に設定してください。`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`フック変換モジュール`},help:{"v1-56futq-4v":`配信前に受信ペイロードを書き換えるために、hooks.transformsDir から読み込む変換モジュールの相対パスです。モジュールはローカルに保持してレビューを行い、パストラバーサルのパターンが含まれないようにしてください。`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`フックマッピングの起動モード`},help:{"v1-1dzqfnw-59":`起動のスケジュールモードです。"now" は即座に起動し、"next-heartbeat" は次のハートビートサイクルまで起動を延期します。多少の遅延が許容される優先度の低い自動処理には、延期モードを使用してください。`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`フックのエンドポイントパス`},help:{"v1-1l9ijzv-4u":"ゲートウェイ制御サーバー上のフックエンドポイントで使用する HTTP パスです（例：`/hooks`）。多層防御のため、推測しにくいパスを使用し、トークン検証と組み合わせてください。"}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`フックのプリセット`},help:{"v1-dp8m0l-4v":`読み込み時に適用され、標準のマッピングと動作のデフォルト値を設定する、名前付きのフックプリセット群です。運用担当者が有効な自動処理を監査できるよう、プリセットの使用を明示してください。`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`フックの認証トークン`},help:{"v1-1ihf6mv-82":`マッピングの実行前に、フックの受信口でリクエスト認証のために検証される共有 Bearer トークンです。このトークンの保持者は、所有者以外の別ロールではなく、フックの受信インターフェースに対して完全に信頼された呼び出し元として扱ってください。Webhook エンドポイントにインターネットからアクセスできる場合は、環境変数による置換を使用し、トークンを定期的にローテーションしてください。`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`フックの変換ディレクトリ`},help:{"v1-1ayj9p0-4t":`マッピングの transform.module パスから参照されるフック変換モジュールのベースディレクトリです。動的インポートをレビュー可能かつ予測可能に保つため、管理されたリポジトリディレクトリを使用してください。`}},logging:{label:{"v1-rq08xq-7":`ログ`},help:{"v1-11an9pb-5e":`ログの重大度、出力先、形式、機密データのマスキングを制御します。有用な診断情報を維持しながら、本番環境に適した厳格なログレベルとマスキングを設定してください。`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`監査台帳`},help:{"v1-1lauvy2-6w":`運用担当者の確認用に、メタデータのみの監査履歴を上限付きで保持します。実行とツールの記録はデフォルトで有効です。メッセージのライフサイクルメタデータはプライバシーに関わるため、別途明示的に有効化する必要があります。バックグラウンドでの書き込みはベストエフォート方式であり、欠損のないコンプライアンス用アーカイブではありません。`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`監査台帳を有効化`},help:{"v1-snknxb-4v":`新しい実行、ツール、および有効化されたメッセージの監査イベントを記録します。デフォルト: true。変更は即座に適用されます。受け付け済みの書き込みは完了し、保持された行は有効期限が切れるまでクエリ可能です。`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`実行 ID の監査`},help:{"v1-1ucirwv-5b":`特定の実行を詳細に調べるため、実行 ID の帰属情報を制限付きで保持します。デフォルト: false。logging.audit.enabled が必要で、新たに受け付けられた実行に適用されます。既存のコンテキストは変更されません。`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`メッセージ監査の対象範囲`},help:{"v1-1yg4lc3-76":`内容を含まないメッセージのライフサイクル記録を制御します。"off"（デフォルト）、既知のダイレクト会話のみを対象とする "direct"、またはダイレクト、グループ、チャンネル、および種類不明の会話を対象とする "all" を指定します。logging.audit.enabled が必要です。変更は以降のライフサイクルイベントに適用されます。`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`コンソールのログレベル`},help:{"v1-16badbd-5u":`ターミナル出力を制御するコンソール専用のログしきい値："silent"、"fatal"、"error"、"warn"、"info"、"debug"、または "trace"。必要に応じて詳細なファイルログを保持しながら、ローカルコンソールの出力量を抑えるために使用します。`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`コンソールログのスタイル`},help:{"v1-d7u0iq-3q":`コンソール出力の形式："pretty" または "json"。機械解析用のパイプラインには json、人が読みやすいターミナル操作には pretty を使用します。`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`ログファイルのパス`},help:{"v1-16gaitv-4w":`コンソールログに加えて、またはその代わりに、ログ出力を永続保存するための任意のファイルパス。管理された書き込み可能なパスを使用し、保持期間とローテーションを運用ポリシーに合わせてください。`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`ログレベル`},help:{"v1-1r5yku0-5o":`実行時のロガー出力に適用する基本ログレベルのしきい値："silent"、"fatal"、"error"、"warn"、"info"、"debug"、または "trace"。本番環境では "info" または "warn" を維持し、debug/trace は調査時のみ使用してください。`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`カスタムマスキングパターン`},help:{"v1-1esa6eg-7k":`カスタム正規表現文字列は、ログやトランスクリプト出力用のデフォルト文字列リストを置き換え、安全境界の UI・ツール・診断ルールに追加されます。組み込みのフォーム本文、構造化認証情報、AWS の単独キーに対する保護は常に適用されます。デプロイ環境固有のトークンや識別子をマスクする場合に使用します。`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`OpenClaw が管理するグローバルな MCP サーバー定義。組み込みの OpenClaw やその他のランタイムアダプターは、ランタイムが所有するプロジェクト設定内にこれらのサーバーを保存することなく利用できます。`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP アプリ`},help:{"v1-amyd91-38":`MCP Apps UI のサポート。有効にすると、設定済みの MCP サーバーがツールの結果をインタラクティブな HTML ビューで提供できるようになります。`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps を有効化`},help:{"v1-ghqy98-3w":`MCP Apps のレンダリングとアプリからサーバーへのブリッジを任意で有効にします。アプリの UI リソースを提供する設定済みの MCP サーバーを信頼できる場合を除き、無効のままにしてください。`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`MCP Apps サンドボックスのオリジン`},help:{"v1-1sxv3mf-6v":`MCP Apps 専用の公開 HTTP(S) オリジン（任意）。リバースプロキシまたは TLS 終端の背後で使用し、設定済みの MCP Apps サンドボックスポートにのみプロキシしてください。Control UI のオリジンとは異なる必要があり、認証済みコンテンツを配信してはいけません。`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`MCP Apps サンドボックスのポート`},help:{"v1-1b8n71l-4p":`MCP Apps サンドボックス専用の待ち受けポート。デフォルトは Gateway のポート番号に 1 を加えた値です。別のローカルサービスまたは Gateway プロファイルがすでにそのポートを使用している場合は、未使用のポートを設定してください。`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP サーバー`},help:{"v1-157ozoz-42":`名前付きの MCP サーバー定義。OpenClaw はこれらを自身の設定に保存し、実行時にランタイムアダプターが対応するトランスポートを決定します。`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`MCP サーバー認証`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP クライアント証明書`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP クライアントキー`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP クライアント証明書`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP クライアントキー`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP 投影`},help:{"v1-slcmq1-6x":`Codex app-serverスレッド専用のOpenClaw反映用メタデータです。ACPセッションや汎用のCodexハーネス設定には影響しません。このブロックを省略すると、CodexのデフォルトのMCP承認動作で、すべてのCodex app-serverエージェントがこのサーバーを利用できます。`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCPエージェント`},help:{"v1-8q98n8-67":`Codex app-serverのスレッド設定にこのMCPサーバーを含めるOpenClawエージェントIDのリストです。任意指定ですが、空でない必要があります。空、空白のみ、または無効なリストを指定すると、安全のためアクセスが拒否されます。省略すると、すべてのCodex app-serverエージェントにサーバーが反映されます。`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Codex MCPツール承認`},help:{"v1-1xql0qr-3d":`同じサーバー単位のMCPツール承認モードを指定する、Codexネイティブの表記です。OpenClaw設定ではdefaultToolsApprovalModeを優先して使用してください。`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Codex MCPツール承認`},help:{"v1-y5vsqq-3s":`このサーバーのCodex MCPツール承認モード（任意指定）："auto"、"prompt"、または"approve"。明示的に信頼するMCPサーバーにのみ使用してください。`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`MCP接続タイムアウト（ms）`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCPサーバーの有効化`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`MCP OAuth認証プロファイル`},help:{"v1-fcrb4u-5z":`このリモート MCP サーバーに現在のベアラートークンを渡すために使用する、更新可能な認証プロファイル ID です。設定すると、OpenClaw は実行時にプロファイルを解決して更新し、更新に必要な情報を下流に渡しません。`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`MCP OAuth クライアントメタデータ URL`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth アイデンティティ`},help:{"v1-1ie6ys7-59":`このサーバーの OAuth 認証情報の所有者を指定します。運用者が管理する認証情報を使用する場合は、このフィールドを省略するか "shared" を使用してください。認証済みの各送信者が自分のアカウントを接続できるようにするには、"per-requester" を使用してください。`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`MCP OAuth リダイレクト URL`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`MCP OAuth スコープ`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`MCP リクエストのタイムアウト（ミリ秒）`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`MCP TLS 検証`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`MCP TLS 検証`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`MCP ツールの並列呼び出し`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`MCP ツールの並列呼び出し`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`MCP ツールの選択`},help:{"v1-10poyzb-4v":`サーバーごとに MCP ツールを選択します。選択した名前の MCP ツールのみを公開するには include を、選択した名前の MCP ツールを非表示にするには exclude を使用してください。項目には完全一致の名前と単純な '*' グロブを指定できます。`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`除外する MCP ツール`},help:{"v1-ijrc5y-1u":`このサーバーで非公開にするMCPツールの正確な名前、または単純な '*' グロブパターン。`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`公開対象のMCPツール`},help:{"v1-89fdfq-3o":`このサーバーで公開するMCPツールの正確な名前、または単純な '*' グロブパターン。省略すると、除外されたものを除くすべてのサーバーツールが公開対象になります。`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`MCPセッションのアイドルTTL（ms）`},help:{"v1-j9si74-87":`OpenClawセッションのMCPランタイムをアイドル時に破棄するまでの時間をミリ秒単位で指定する任意設定です。未設定または0の場合、セッションのクリーンアップまたはGatewayのシャットダウンまでランタイムを維持します。正の値は小数点以下を切り捨てます。有効なリースや取得待ちのリクエストがある場合は破棄されません。実行に紐づくランタイムは、この設定にかかわらず、その単発実行の終了時に停止します。`}},memory:{label:{"v1-oopaku-6":`メモリ`},help:{"v1-1wlx40m-13":`組み込みメモリの設定（グローバル）。`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`メモリの引用表示モード`},help:{"v1-1q6dxr5-4u":`返信内の引用の表示を制御します。"auto" は有用な場合に引用を表示し、"on" は常に表示、"off" は非表示にします。有用な情報とノイズのバランスが取れた既定の動作には、"auto" を維持してください。`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`メモリ検索`},help:{"v1-1ukbud1-25":`MEMORY.mdとmemory/*.mdを対象としたベクトル検索（エージェントごとの上書き設定に対応）。`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`メモリ検索の埋め込みキャッシュ`},help:{"v1-d8h2e4-5b":`計算済みのチャンク埋め込みをSQLiteにキャッシュし、インデックスの再作成と差分更新を高速化します（既定値：true）。キャッシュの正確性を調査する場合やディスク使用量を最小限に抑える場合を除き、有効のままにしてください。`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`メモリ検索のドキュメント入力タイプ`},help:{"v1-1ui33sv-5f":"ドキュメント用およびインデックス作成用のメモリ埋め込みに使用する、プロバイダー固有の任意の `input_type` 値です。パッセージまたはドキュメントのラベルを必要とする、OpenAI 互換の非対称埋め込みエンドポイントで使用します。"}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`メモリ検索を有効にする`},help:{"v1-14f11b9-4t":`このエージェントプロファイルでのメモリ検索のインデックス作成と取得の動作を一括で切り替えます。意味に基づく想起を行う場合は有効にし、完全にステートレスな応答が必要な場合は無効にしてください。`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`メモリ検索のセッションインデックス（実験的）`},help:{"v1-qvhv8z-3i":`セッションの会話記録をメモリ検索用にインデックス化します。ルートとエージェントごとで想起設定の継承が異なる場合は、この詳細な上書き設定を維持してください。`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`追加のメモリパス`},help:{"v1-ojqokq-7i":`デフォルトのメモリファイルに加えて、追加のディレクトリまたは .md ファイルをメモリインデックスに追加します。項目には、パス文字列またはルート相対の glob パターンを持つオブジェクトを指定できます。マルチモーダルメモリが有効な場合、これらのパス内で一致する画像・音声ファイルもインデックス作成の対象になります。`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`追加のメモリパス`},help:{"v1-b9mbq8-3m":`追加のメモリディレクトリまたはファイルを設定します。相対パスはエージェントのワークスペースを基準に解決されます。ファイルを直接指定した場合は、そのファイルがそのままインデックス化されます。`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`追加のメモリパスのパターン`},help:{"v1-j8br1v-4e":`ディレクトリ項目の対象を、このルート相対の glob（例："runbooks/**/*.md"）に一致するサポート対象ファイルに限定します。省略すると、サポート対象のすべてのファイルを再帰的にスキャンします。`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`メモリ検索のフォールバック`},help:{"v1-1r6368w-6p":`プライマリの埋め込み処理が失敗した場合に使用する予備のプロバイダー："openai"、"gemini"、"voyage"、"mistral"、"bedrock"、"lmstudio"、"ollama"、"local"、または "none"。本番環境の信頼性を確保するため、実際に使用できるフォールバックを設定してください。"none" は、明示的な失敗として扱いたい場合にのみ使用してください。`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`メモリ検索の入力タイプ`},help:{"v1-26vbwe-5u":"このオプションのプロバイダー固有の `input_type` 値は、クエリとドキュメントの埋め込みリクエストの両方に同じラベルを適用する場合にのみ使用してください。非対称のプロバイダーでは、queryInputType と documentInputType の使用を推奨します。"}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`ローカル埋め込みモデルのパス`},help:{"v1-13ymbnt-5q":"ローカルメモリ検索に使用するローカル埋め込みモデルのソースを、GGUF ファイルのパスや `hf:` URI などで指定します。provider が `local` の場合にのみ使用し、大規模なインデックス再構築の前にモデルの互換性を確認してください。"}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`メモリ検索モデル`},help:{"v1-11pohrl-59":`デフォルト以外のモデルが必要な場合に、選択したメモリプロバイダーが使用する埋め込みモデルを上書きします。プロバイダーのデフォルト設定を超えて、検索の再現率やコストを明示的に調整する必要がある場合にのみ設定してください。`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`メモリ検索のマルチモーダル設定`},help:{"v1-1jn02s-9e":'設定済みの追加パスにある画像ファイルと音声ファイルをインデックス化するための、オプションのマルチモーダルメモリ設定です。埋め込みモデルがクロスモーダル埋め込みを明示的にサポートしていない限り、無効のままにしてください。有効にする場合は、`memory.search.fallback` を "none" に設定してください。インデックス作成中に、該当するファイルが設定済みのリモート埋め込みプロバイダーにアップロードされます。'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`メモリ検索のマルチモーダル機能を有効にする`},help:{"v1-1dk5d7o-7e":`extraPaths にある画像・音声のメモリインデックス作成を有効にします。現在、この機能には Gemini embedding-2 が必要です。デフォルトのメモリルートは Markdown のみに制限され、メモリ検索のフォールバックプロバイダーは無効になります。また、条件に一致するバイナリコンテンツが、設定されたリモート埋め込みプロバイダーにアップロードされます。`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`メモリ検索のマルチモーダルファイルの最大バイト数`},help:{"v1-1mmdrvk-5d":`マルチモーダルファイルごとの最大許容バイト数を設定します。この値を超えるファイルは、メモリのインデックス作成時にスキップされます。アップロードコストとインデックス作成の遅延を抑えるために使用します。短い高品質の音声クリップを扱う場合は、値を引き上げてください。`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`メモリ検索のマルチモーダル対象種別`},help:{"v1-alp4vh-4l":`extraPaths からインデックスを作成するマルチモーダルファイルの種類を "image"、"audio"、"all" から選択します。大量のバイナリデータが意図せずインデックス化されないよう、対象を絞ってください。`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`メモリ検索の出力次元数`},help:{"v1-1f7zu53-93":`メモリの埋め込みに使用する出力ベクトルのサイズを、プロバイダーごとに上書きします。Gemini モデルは 128～3072 次元をサポートし、768、1536、3072 次元を推奨しています。Titan V2、Cohere V4、Nova などの Bedrock モデルファミリーでは、それぞれ使用可能なサイズが定められています。保存済みベクトルの次元数を統一する必要があるため、この値を変更するとインデックス全体の再作成が必要になります。`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`メモリ検索プロバイダー`},help:{"v1-5evseb-71":`メモリベクトルの構築と検索に使用する埋め込みバックエンドを選択します。デフォルトは "openai" です。別のバックエンドを使用する場合は、"openai-compatible"、"gemini"、"voyage"、"mistral"、"bedrock"、"deepinfra"、"github-copilot"、"lmstudio"、"ollama"、または "local" を設定してください。`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`メモリ検索の最大結果数`},help:{"v1-13ekath-4x":`後続の再ランキングとプロンプトへの挿入前に、検索から返されるメモリのヒット数の上限です。より幅広く取得するには値を大きくし、プロンプトをコンパクトにして応答を速めるには値を小さくしてください。`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`メモリ検索の最小スコア`},help:{"v1-1ww231l-4v":`メモリの検索結果を最終的な取得結果に含めるための、関連度スコアの下限です。関連性の低い一致やノイズを減らすには値を大きくし、取得条件を緩めるには値を小さくしてください。`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`メモリ検索のクエリ入力タイプ`},help:{"v1-831yrv-4q":"クエリ時のメモリ埋め込みに使用する、プロバイダー固有の任意の `input_type` 値です。クエリラベルを必要とする OpenAI 互換の非対称埋め込みエンドポイントで使用してください。"}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`会話をまたいで記憶`},help:{"v1-k1itm8-7y":`保護された会話履歴の取得を通じて、このエージェントの他のプライベートな会話から関連するコンテキストを使用します。グローバルの session.dmScope が未設定または "main" で、DM スコープを上書きするバインディングがない場合にのみ、デフォルトで有効になります。DM の分離が設定されている場合は、デフォルトで無効になります。明示的に指定された true または false が常に優先されます。`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`リモート埋め込み API キー`},help:{"v1-nfuuu-62":`メモリのインデックス作成時およびクエリ時の埋め込み生成に使うリモート呼び出し専用の API キーを指定します。メモリの埋め込み生成で、グローバルのデフォルト設定や環境変数とは異なる認証情報を使う場合に使用してください。`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`リモート埋め込みのベース URL`},help:{"v1-1ugvqgt-5p":`埋め込み API のエンドポイントを、OpenAI 互換プロキシやカスタムの Gemini ベース URL などに上書きします。独自のゲートウェイやベンダーのエンドポイントを経由する場合にのみ使用し、それ以外はプロバイダーのデフォルト設定を維持してください。`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`リモートのバッチ埋め込みを有効化`},help:{"v1-1fehqi-5x":`対応するプロバイダー（OpenAI/Gemini）のバッチ API を埋め込みジョブで有効にし、大規模なインデックス作成時のスループットを向上させます。プロバイダーのバッチ処理の失敗をデバッグする場合や、ごく小規模なワークロードを実行する場合を除き、有効のままにしてください。`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`リモート埋め込みのヘッダー`},help:{"v1-1uic0kd-5i":`リモートの埋め込みリクエストにカスタム HTTP ヘッダーを追加し、プロバイダーのデフォルトと統合します。プロキシ認証やテナントのルーティング用ヘッダーに使用し、機密メタデータの漏えいを避けるため、設定する値は必要最小限にしてください。`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`メモリ検索のソース`},help:{"v1-btxtzg-57":`インデックスを作成するソースを選択します。"memory" は MEMORY.md とメモリファイルを読み取り、"sessions" は会話履歴を含めます。過去のチャット記録から情報を取得する必要がなければ、["memory"] のままにしてください。`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`メモリ検索のベクトルインデックス`},help:{"v1-fbybkj-37":`sqlite-vec のセマンティックインデックスを制御します。ルートとエージェントごとのベクトルポリシーが異なる場合は、この詳細な上書き設定を維持してください。`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`メモリ検索のベクトル拡張機能のパス`},help:{"v1-1hysv5q-58":"自動検出された sqlite-vec 拡張ライブラリのパス（`.dylib`、`.so`、または `.dll`）を上書きします。ランタイムが sqlite-vec を自動的に検出できない場合や、動作確認済みのビルドに固定する場合に使用してください。"}},messages:{label:{"v1-1wwzqad-8":`メッセージ`},help:{"v1-i5k0iw-5k":`メッセージ基盤とエージェント間で共通のデフォルト設定です。ルート直下の同階層の項目は基盤とエージェント間で共通のデフォルト設定を、agents.defaults はエージェントループの動作を管理します。対応している場合、各エージェントのエントリでどちらも上書きできます。`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`受信確認リアクションの絵文字`},help:{"v1-1iip0zs-1x":`受信メッセージの確認に使用する絵文字リアクションです（空にすると無効）。`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`受信確認リアクションの範囲`},help:{"v1-1jvdg5n-7s":`受信確認リアクションを送信する条件です（"group-mentions"、"group-all"、"direct"、"all"、"off"、"none"）。"group-mentions" は、グループでメンションが必須かどうかにかかわらず、エージェントにメンションしたグループメッセージに受信確認を返します。"group-all" はすべてのグループメッセージに受信確認を返します。"off"/"none" は受信確認リアクションを完全に無効にします。`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`グループチャットのルール`},help:{"v1-chqsvh-4l":`メンションによるトリガーや履歴ウィンドウのサイズなど、グループメッセージの処理を制御します。グループチャンネルですべてのメッセージがトリガーにならないよう、メンションパターンは限定的に設定してください。`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`グループ履歴の上限`},help:{"v1-1mkbpw-9k":`グループセッションで、各ターンのコンテキストとして読み込む過去のグループメッセージの最大数です。会話の連続性を高めるには値を大きくし、応答を高速化してコストを抑えるには値を小さくします。自動的にプロンプトに含まれる履歴は200件までです。JSON整数の最大値を指定すると、無制限ではなく、チャンネルのデフォルトの履歴件数（共有グループ履歴では50件）が選択されます。`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`グループのメンションパターン`},help:{"v1-i7h7qc-6f":`グループチャット内の明示的なメンションやトリガーフレーズを検出するための、大文字と小文字を区別しない安全な正規表現パターンです。メッセージの多いチャンネルでは、誤検出を減らすために精密なパターンを使用してください。無効なパターンや、安全でない入れ子の繰り返しパターンは無視されます。`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`メンションのないグループ受信メッセージ`},help:{"v1-17wef8h-5f":`常時有効なグループチャットで、メンションのない会話を送信する方法を制御します。"user_request" はユーザーリクエストとして扱い、"room_event" は非表示のコンテキストとして送信します。この場合、表示される出力にはメッセージツールが必要です。`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`グループで表示する返信`},help:{"v1-qa4z1s-aa":`グループやチャンネルの会話で、モデルが生成した元の返信の扱いを上書きします。表示する返信のグローバルポリシーが設定されていない場合、デフォルトは "automatic" です。"message_tool" では、通常のアシスタント出力と汎用ツールのメディアに message(action=send) が必要です。明示的にホストが管理するランタイム出力は、バックグラウンドのルームイベントを除き、引き続き配信できます。"automatic" は従来どおり通常の返信を投稿します。`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`受信デバウンス`},help:{"v1-ebyu5x-4a":`キュー処理やターン処理の開始前に使用する、直接受信メッセージのデバウンス設定です。同じ送信者から短時間に連続して届くメッセージに対応するため、プロバイダーごとに設定してください。`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`チャンネル別の受信デバウンス（ms）`},help:{"v1-wbz54j-4g":`プロバイダーIDをキーとする、チャネルごとの受信デバウンス時間の上書き設定（ミリ秒）。一部のプロバイダーが他よりも頻繁にメッセージの断片を送信する場合に使用します。`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`受信メッセージのデバウンス（ms）`},help:{"v1-1616yo2-7w":`同じ送信者から立て続けに届くメッセージをまとめるための待機時間（ms）。グローバル設定でもチャネル設定でも上書きされていない場合、Telegram のデフォルトは 300ms、他のチャネルのデフォルトは 0 です。0 にすると通常の連続メッセージの一括処理は無効になりますが、Telegram では引き続き、文字数上限に近い長文メッセージの分割部分が再結合されます。`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`受信キュー`},help:{"v1-hm2o31-48":`セッションの実行中に届く受信メッセージのキュー処理方式。実行の方向修正、後続処理の延期、バッチ処理、割り込みを調整するために使用します。`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`チャネル別のキューモード`},help:{"v1-4rf8z8-54":`プロバイダーID（例：telegram、discord、slack）をキーとする、チャネルごとのキューモードの上書き設定。特定のチャネルのトラフィックパターンに、全体のデフォルトとは異なる動作が必要な場合に使用します。`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`キュー容量`},help:{"v1-16ql8c7-4j":`破棄ポリシーが適用される前にキューに保持できる受信項目の最大数。デフォルトは20です。メッセージの多いチャネルでは、メモリ使用量を予測可能に保つため、容量に適切な上限を設けてください。`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`チャネル別のキューフォールバックデバウンス（ms）`},help:{"v1-4tpyt7-4e":`プロバイダーIDをキーとする、キュー動作のチャネルごとのデバウンス上書き設定。メッセージの到着ペースが異なるチャット環境で、短時間に集中するメッセージの処理を個別に調整するために使用します。`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`キューの破棄方式`},help:{"v1-ydb2rw-6m":`キューの上限を超えた場合の破棄方法です。"summarize" は最も古い項目を破棄しますが、簡潔な要約を保持します。"old" は要約を残さずに最も古い項目を破棄します。"new" は最新の項目を拒否します。文脈が重要な長時間のチャットでは "summarize" を使用してください。`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`キューモード`},help:{"v1-19k7gy1-67":`実行中のキューモードです。実行中の処理にプロンプトを挿入するには "steer"、後で実行するには "followup"、互換性のあるメッセージを後でまとめて処理するには "collect"、最新のプロンプトを開始する前に実行中の処理を中止するには "interrupt" を使用してください。`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`送信応答のプレフィックス`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`使用量フッターのデフォルトモード`},help:{"v1-l3shsx-dv":`/usage でモードを選択していないセッションに初期設定される、返信ごとの使用量フッターのデフォルトモード（"off"|"tokens"|"full"）です。"tokens" の従来の別名である "on" も使用できます。モード単体、または "default" をフォールバックとするチャネル別のマップを指定できます。優先順位：セッションの値 -> チャネルの設定 -> default -> off。/usage で明示的に選択した値（off を含む）は永続化され、デフォルトより優先されます。セッションの上書き設定を解除し、この設定のデフォルトを再び継承するには、/usage reset（別名：inherit、clear、default）を使用してください。`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`ステータスリアクション`},help:{"v1-193764l-3s":`エージェントの進行状況（キュー待機中 → 思考中 → ツール使用中 → 完了/エラー）に応じて、トリガーとなったメッセージの絵文字を更新するライフサイクルのステータスリアクションです。`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`ステータスリアクションを有効にする`},help:{"v1-1qnmmnc-7x":`対応チャネルでライフサイクルのステータスリアクションを有効にします。Discordでは、確認リアクションが有効な場合、未設定でも有効として扱われます。Slack、Signal、Telegram、WhatsAppでは、ライフサイクルリアクションを使用するには、この設定をtrueにする必要があります。Slackでは、デフォルトでネイティブのアシスタントスレッドステータスを使用して進行状況を表示します。`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`使用量フッターテンプレート`},help:{"v1-1xibc23-47":`/usage fullのカスタムフッターテンプレート。インラインオブジェクトまたはJSONファイルのパスを指定します。テンプレートが無効または利用できない場合は、組み込みの使用量表示行にフォールバックします。`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`表示される返信`},help:{"v1-7yfwc2-8t":`ダイレクト、グループ、チャネルの会話で、モデルが作成した返信の表示を制御します。"message_tool"では、通常のアシスタント出力と汎用ツールのメディアにmessage(action=send)が必要です。ホストが明示的に管理するランタイム出力は、周辺的なルームイベントを除き、引き続き配信できます。"automatic"では、従来どおり通常の返信を投稿します。`}},meta:{label:{"v1-1xpfxac-m":`互換性メタデータ`},help:{"v1-1owqhgn-2w":`古いバイナリが安全でない設定のダウングレードを拒否できるように保持される、旧バージョンでも読み取り可能な互換性メタデータ。`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`設定の最終更新バージョン`},help:{"v1-qykpv1-1i":`この設定を最後に書き込んだOpenClawのバージョン。`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`設定移行マーカー`},help:{"v1-burt8q-1q":`完了した設定移行に対する、保持数に上限のある互換性マーカー。`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`モデルポリシー許可リストの移行`},help:{"v1-5psop1-1z":`従来のモデルマップの制限が保持または評価されたことを記録します。`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`ユーティリティモデル分離の移行`},help:{"v1-vzdfqx-2t":`ユーティリティモデルの選択を分離する前に、従来の暗黙的なプライマリモデルが保持されたことを記録します。`}},models:{label:{"v1-hzmwb-6":`モデル`},help:{"v1-1h1niol-5q":`プロバイダー定義、マージ／置換の動作、および任意のBedrock検出連携を設定するモデルカタログのルートです。本番環境のフェイルオーバー経路に依存する前に、プロバイダー定義を明示的に設定し、検証してください。`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`モデルカタログの更新`},help:{"v1-1hess4t-40":`同梱のモデルカタログのバックグラウンド更新を制御します。リモートのエントリはモデルのメタデータを更新できますが、プロバイダーのエンドポイントやヘッダーは変更できません。`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`モデルカタログの更新を有効化`},help:{"v1-1fogpjj-3j":`ホストされているモデルカタログの更新をバックグラウンドで取得します（デフォルト: true）。リモートのモデルカタログとの通信をすべて無効にするには、falseに設定してください。`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`モデルカタログの更新URL`},help:{"v1-e02ai2-44":`ホストされているモデルカタログのURLを、セルフホストのHTTPSミラーのURLで上書きします（テスト用にlocalhostのHTTPも使用できます）。変更はGatewayの再起動後に適用されます。`}},"models%2Emode":{label:{"v1-wl6vg8-i":`モデルカタログのモード`},help:{"v1-1ofrnsp-es":`プロバイダーカタログの動作を制御します。"merge"は組み込みのプロバイダーを保持し、カスタムプロバイダーを重ねて適用します。"replace"は設定したプロバイダーのみを使用します。"merge"では、プロバイダーIDが一致する場合、エージェントのmodels.json内の空でないbaseUrl値が保持されます。一方、apiKey値は、現在の設定／認証プロファイルのコンテキストでプロバイダーがSecretRef管理下にない場合にのみ保持されます。SecretRef管理下のプロバイダーは、現在のソースマーカーからapiKeyを更新します。また、一致するモデルのcontextWindow/maxTokensには、明示的なエントリと暗黙的なエントリのうち大きい方の値が使用されます。`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`モデルプロバイダー`},help:{"v1-1y5jg0v-8p":`プロバイダー ID をキーとし、接続・認証設定と具体的なモデル定義を格納するプロバイダーマップです。組み込みプロバイダーはプロバイダーレベルのオーバーレイで調整できます。カスタムプロバイダーには baseUrl と models が必要です。エージェントやツールからの参照を環境間で移植できるよう、安定したプロバイダーキーを使用してください。`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`モデルプロバイダーのランタイム`},help:{"v1-1luy4fb-5o":`このプロバイダーの低レベルなエージェントランタイムポリシー（省略可能）です。エージェント全体のランタイムを固定するのではなく、プロバイダーまたはモデルのランタイムポリシーを使用してください。省略時またはデフォルト設定時は、選択されたプロバイダーに応じて OpenClaw がランタイムを選択します。`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`モデルプロバイダーのランタイム ID`},help:{"v1-1gusd9s-69":`プロバイダーのエージェントランタイム ID です。"openclaw"、"auto"、"codex" などの登録済みプラグインハーネス ID、または "claude-cli" などのサポートされている CLI バックエンドエイリアスを指定します。公式エンドポイントの OpenAI では、省略時に Codex ハーネスが使用されます。`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`モデルプロバイダーの API アダプター`},help:{"v1-16c28rb-57":`モデル呼び出しのリクエストとレスポンスの互換性処理を制御するプロバイダー API アダプターの選択です。機能の不一致を避けるため、接続先プロバイダーのプロトコルに合ったアダプターを使用してください。`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`モデルプロバイダーの API キー`},help:{"v1-1p84k96-54":`プロバイダーがキーによる直接認証を要求する場合に、API キーベースの認証に使用するプロバイダーの認証情報です。シークレットまたは環境変数による置換を使用し、コミットする設定ファイルに実際のキーを保存しないでください。`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`モデルプロバイダーの認証モード`},help:{"v1-1l1lwxr-5p":`プロバイダーの認証方式を選択します。API キー認証には "api-key"、Bearer トークン認証には "token"、OAuth 認証情報には "oauth"、AWS 認証情報の解決には "aws-sdk" を使用します。プロバイダーの要件に合わせて設定してください。`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`モデルプロバイダーの Authorization ヘッダー`},help:{"v1-1gn3lt3-59":`true の場合、他の認証方式が利用可能でも、HTTP Authorization ヘッダー経由で認証情報を送信します。プロバイダーまたはプロキシが Authorization の転送を明示的に要求する場合にのみ使用してください。`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`モデルプロバイダーのベース URL`},help:{"v1-1ku88v8-53":`このプロバイダーエントリのモデルリクエストを処理するエンドポイントのベース URL です。HTTPS エンドポイントを使用し、必要に応じて設定テンプレートで環境ごとに URL を管理してください。`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`モデルプロバイダーのヘッダー`},help:{"v1-chg59u-4x":`テナントのルーティング、プロキシ認証、またはカスタムゲートウェイの要件に対応するため、プロバイダーへのリクエストに追加される静的な HTTP ヘッダーです。使用は必要最小限にとどめ、機密性の高いヘッダー値はシークレットに保存してください。`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`モデルプロバイダーの num_ctx 挿入（OpenAI 互換）`},help:{"v1-53rmcr-6n":"OpenAI 互換アダプター（`openai-completions`）で設定された Ollama プロバイダーに対して、OpenClaw が `options.num_ctx` を挿入するかどうかを制御します。デフォルトは true です。プロキシまたはアップストリームが `options` ペイロード内の未知のフィールドを拒否する場合にのみ false に設定してください。"}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`モデルプロバイダーのローカルサービス`},help:{"v1-19zkcow-4y":`このプロバイダー向けの、必要に応じて起動するローカルモデルサーバープロセス（任意）。OpenClaw は healthUrl を確認し、必要に応じてコマンドを起動して準備が整うのを待ち、その後モデルリクエストを送信します。`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`モデルプロバイダーのローカルサービス引数`},help:{"v1-t12wib-27":`シェル展開を行わずにローカルモデルサーバーのコマンドに渡す引数リスト。`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`モデルプロバイダーのローカルサービスコマンド`},help:{"v1-1x6hz64-4j":`ローカルモデルサーバープロセスの実行ファイルの絶対パス。プロバイダーの起動がシェルの PATH 検索に依存せず、常に同じように行われるよう、このパスを明示的に指定してください。`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`モデルプロバイダーのローカルサービス作業ディレクトリ`},help:{"v1-fi3xlx-1h":`ローカルモデルサーバープロセスの作業ディレクトリ。`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`モデルプロバイダーのローカルサービス環境`},help:{"v1-1lwb9k1-3k":`ローカルモデルサーバープロセスの追加環境変数。機密情報と思われる値は、設定スナップショットではマスクされます。`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`モデルプロバイダーのローカルサービスヘルスチェック URL`},help:{"v1-jv7aw-35":`モデルリクエストの前に準備状態を確認する URL。省略した場合、OpenClaw はプロバイダーの baseUrl に /models を追加した URL を使用します。`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`モデルプロバイダーのローカルサービスのアイドル時停止`},help:{"v1-1efg054-3z":`最後のリクエストが完了してから、OpenClaw が起動したローカルモデルサーバーを稼働させておく時間（ミリ秒）。0 に設定すると、OpenClaw が終了するまで稼働し続けます。`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`モデルプロバイダーのローカルサービス準備完了タイムアウト`},help:{"v1-4gp0f0-2r":`プロセスの起動後、ローカルモデルサーバーの準備完了プローブを待機する最大時間（ミリ秒）。`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`モデルプロバイダーの最大トークン数`},help:{"v1-fnj50y-38":`モデルエントリで maxTokens が設定されていない場合に、このプロバイダーのモデルに適用されるデフォルトの最大出力トークン数。`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`モデルプロバイダーのモデル一覧`},help:{"v1-1vbm0gt-63":`プロバイダーに対して宣言するモデル一覧。識別子、メタデータ、プロバイダー固有のパラメーター、および任意の互換性やコストに関するヒントを含みます。選択とフォールバックが正しく機能するよう、ID はプロバイダーのカタログ値と完全に一致させてください。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`モデルランタイム`},help:{"v1-1k70g2n-3g":`このモデル専用の任意の低レベルエージェントランタイムポリシー。モデルのランタイムポリシーは、プロバイダーのランタイムポリシーより優先されます。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`モデルランタイム ID`},help:{"v1-1llzv33-42":`モデルのエージェントランタイム ID："openclaw"、"auto"、"codex" などの登録済みプラグインハーネス ID、または "claude-cli" などのサポート対象の CLI バックエンドエイリアス。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`モデルのメディア入力`},help:{"v1-wxtj8e-2x":`モデルのメディア対応機能に関する任意のメタデータです。ツールが画像圧縮の安全側のデフォルト設定を選ぶために使用します。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`モデルの画像入力`},help:{"v1-1nviirq-3c":`このモデルの画像入力に関する任意の制限設定です。最大辺長、最大ピクセル数、圧縮時の推奨辺長などを指定します。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`モデルの画像の最大バイト数`},help:{"v1-c2469j-23":`このモデルでプロバイダーが受け入れる、エンコード済み画像ペイロードの最大サイズです。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`モデルの画像の最大ピクセル数`},help:{"v1-9d6yqp-1u":`このモデルでプロバイダーが受け入れる画像の最大ピクセル数です。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`モデルの画像の最大辺長`},help:{"v1-1gbci08-1y":`このモデルでプロバイダーが受け入れる画像の幅または高さの最大値です。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`モデルの画像の推奨辺長`},help:{"v1-1u1mpcg-2x":`バランスの取れた圧縮を行うための、画像リサイズ時の推奨辺長です。未設定の場合は、OpenClawの安全側のデフォルト値を使用します。`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`モデルの画像トークンモード`},help:{"v1-1oy6z7v-1z":`プロバイダーの画像トークン計算方式："tile"、"detail"、または "provider"。`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`モデルプロバイダーの実行時パラメーター`},help:{"v1-464sgu-4t":`プロバイダープラグインが解釈する、プロバイダー固有の実行時パラメーターです。プロバイダーのドキュメントに記載されたキーを使用し、その場しのぎの共通の仮定よりも、プロバイダーのドキュメントに明記された内容を優先してください。`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`モデルプロバイダーのリージョン`},help:{"v1-yq7rxk-5h":`リージョン別エンドポイントを提供するプロバイダーが解釈する、任意のデプロイ先/APIリージョンです。サポートされる値はプロバイダーのドキュメントを参照してください。両方が設定されている場合、通常は baseUrl による上書きが優先されます。`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`モデルプロバイダーのリクエスト設定の上書き`},help:{"v1-1lkxryk-87":`モデルプロバイダーへのリクエストに適用する任意の上書き設定です。追加ヘッダー、認証設定の上書き、プロキシルーティング、TLSクライアント設定、および信頼できるセルフホスト型エンドポイント向けの任意の allowPrivateNetwork が含まれます。上流サービスや企業ネットワークの経路で通信のカスタマイズが必要な場合にのみ使用してください。`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`モデルプロバイダーのリクエストでプライベートネットワークを許可`},help:{"v1-1nbtcjk-fo":`true の場合、プロバイダーの HTTP フェッチガード（fetchWithSsrFGuard）を介して、プライベート、CGNAT、または同様のアドレス範囲へのモデルプロバイダーの HTTP リクエストを許可します。カスタムまたはローカルプロバイダーのベース URL では、メタデータ、リンクローカル、ローカル用途の NAT64（64:ff9b:1::/48）のオリジンを除き、設定されたオリジンそのものがすでに信頼されています。この信頼を無効にするには、false に設定してください。OpenAI Responses WebSocket はヘッダーと TLS に request を再利用しますが、このフェッチの SSRF 経路は使用しません。true は、設定された baseUrl のオリジン以外のプライベートオリジンへのアクセスが必要な、運用者が管理するセルフホスト型エンドポイントにのみ使用してください。`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`モデルプロバイダーのリクエスト認証の上書き`},help:{"v1-ucdgnf-1w":`このプロバイダーのリクエスト認証の動作を上書きします。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`モデルプロバイダーのリクエスト認証ヘッダー名`},help:{"v1-1881nqr-1i":`認証モードが header の場合に使用するカスタム認証ヘッダー名です。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`モデルプロバイダーのリクエスト認証モード`},help:{"v1-1lhv8hs-24":`認証の上書きモード："provider-default"、"authorization-bearer"、または "header"。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`モデルプロバイダーのリクエスト認証ヘッダーのプレフィックス`},help:{"v1-1rbm9lz-21":`認証モードが header の場合に request.auth.value の先頭に付加する任意のプレフィックスです。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`モデルプロバイダーのリクエスト Bearer トークン`},help:{"v1-6rcasw-1l":`認証モードが authorization-bearer の場合に使用する Bearer トークン。`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`モデルプロバイダーへのリクエストの認証ヘッダー値`},help:{"v1-1v69ej-1j":`認証モードが header の場合に使用するカスタム認証ヘッダー値。`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`モデルプロバイダーへのリクエストヘッダー`},help:{"v1-zj3orj-2i":`デフォルトの帰属情報と認証情報の解決後に、プロバイダーへのリクエストに統合される追加ヘッダー。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`モデルプロバイダーへのリクエスト用プロキシ`},help:{"v1-md5uj8-4j":`モデルプロバイダーへのリクエスト用の任意のプロキシ上書き設定。環境のプロキシ設定を使用するには "env-proxy" を、特定のプロキシ URL を経由するには "explicit-proxy" を使用します。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`モデルプロバイダーへのリクエスト用プロキシモード`},help:{"v1-1dx0ozg-29":`モデルプロバイダーへのリクエスト用のプロキシ上書きモード："env-proxy" または "explicit-proxy"。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`モデルプロバイダーへのリクエスト用プロキシの TLS`},help:{"v1-rdx62w-1v":`設定済みのプロキシへの接続時に使用する任意の TLS 設定。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`モデルプロバイダーへのリクエスト用プロキシの TLS CA`},help:{"v1-11pg2fd-1s":`プロキシの TLS 証明書チェーンの検証に使用するカスタム CA バンドル。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`モデルプロバイダーへのリクエスト用プロキシの TLS 証明書`},help:{"v1-x8nk2q-22":`相互TLSが必要な場合にプロキシに提示するクライアントTLS証明書。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`モデルプロバイダーへのリクエスト用プロキシのTLS検証をスキップ`},help:{"v1-12vjdm9-2j":`プロキシのTLS証明書検証をスキップします。管理された開発環境でのみ使用してください。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`モデルプロバイダーへのリクエスト用プロキシのTLSキー`},help:{"v1-1skyr56-1w":`プロキシの相互TLS用にrequest.proxy.tls.certと対になる秘密鍵。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`モデルプロバイダーへのリクエスト用プロキシのTLSパスフレーズ`},help:{"v1-wjvoxd-1m":`request.proxy.tls.keyの復号に使用する任意のパスフレーズ。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`モデルプロバイダーへのリクエスト用プロキシのTLSサーバー名`},help:{"v1-b4oabu-22":`プロキシへのTLS接続を確立する際に使用する、任意のSNI／サーバー名の上書き設定。`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`モデルプロバイダーへのリクエスト用プロキシのURL`},help:{"v1-kvbgou-48":`request.proxy.modeがexplicit-proxyの場合に使用する、明示的に指定されたプロキシURL。URLに埋め込まれた認証情報は機密情報として扱われ、スナップショットでは伏せられます。`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`モデルプロバイダーへのリクエストのTLS`},help:{"v1-16u7v7h-2b":`上流のモデルエンドポイントに直接接続する際に使用する、任意のTLS設定です。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`モデルプロバイダーのリクエスト用TLS CA`},help:{"v1-ny8y3e-1v":`上流のTLS証明書チェーンの検証に使用するカスタムCAバンドルです。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`モデルプロバイダーのリクエスト用TLS証明書`},help:{"v1-1lltmhw-2e":`相互TLSが必要な場合に、上流のエンドポイントに提示するクライアントTLS証明書です。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`モデルプロバイダーのリクエスト用TLS検証のスキップ`},help:{"v1-1006cuy-2m":`上流のTLS証明書の検証をスキップします。管理された開発環境でのみ使用してください。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`モデルプロバイダーのリクエスト用TLS鍵`},help:{"v1-w2agir-1t":`上流との相互TLSで使用する、request.tls.certと対になる秘密鍵です。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`モデルプロバイダーのリクエスト用TLSパスフレーズ`},help:{"v1-10ds42f-1g":`request.tls.keyの復号に使用する、任意のパスフレーズです。`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`モデルプロバイダーのリクエスト用TLSサーバー名`},help:{"v1-18yt7x9-1y":`上流とのTLS接続を確立する際に使用する、任意のSNI／サーバー名の上書き設定です。`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`モデルプロバイダーのリクエストタイムアウト`},help:{"v1-t3yn8l-ih":`プロバイダーごとのモデルリクエストのタイムアウト（秒単位、省略可）。プロバイダーレベルのリクエスト設定は、そのプロバイダーに属する明示的なモデルエントリに適用され、暗黙的なモデルは作成しません。カスタムプロバイダーでは、プロバイダーの baseUrl および models と併せて設定してください。接続、ヘッダー、本文、リクエスト全体の中断処理を含むプロバイダーへの HTTP フェッチに適用されます。また、このプロバイダーの LLM アイドル／ストリーム監視の上限を、暗黙のデフォルト値である約120秒よりも引き上げます。低速なローカルまたはセルフホストのモデルサーバーや、推論トークンをバッファリングして通信上は無応答になるクラウドプロバイダー（Gemini preview、大きなツールペイロードを扱う Claude/Opus）には、エージェント全体のタイムアウトを変更する代わりにこの設定を使用してください。`}},nodeHost:{label:{"v1-nb8lk1-9":`ノードホスト`},help:{"v1-8recuz-4z":`この Gateway ノードから他のノードやクライアントに公開する機能を制御するノードホスト設定です。ノードネットワークを通じてローカル機能を意図的にプロキシする場合を除き、デフォルト設定を維持してください。`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`ノードのエージェント実行`},help:{"v1-4uz5ur-2k":`このヘッドレスノードホストで、承認を必要とするネイティブエージェントのターンを有効にします。デフォルトでは無効です。`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`ノードの Claude エージェント実行`},help:{"v1-g8az5y-2l":`このヘッドレスノードホストが、Claude CLI エージェントのターンを実行可能であることを Gateway に通知できるかどうかを制御します。`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`ノードの Claude エージェント実行を有効化`},help:{"v1-1ke804l-44":`ローカルの claude バイナリが利用可能な場合、ペアリング済みノードで Claude セッションを継続できることを通知します（デフォルト：false）。実行には引き続きノードの exec 承認が必要です。`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`ノードの自動更新`},help:{"v1-16xjk4e-5n":`パッケージ化されたヘッドレスノードホスト用の独立したランタイムの自動更新を制御します。1時間ごとに確認し、すべてのノード処理が完了してから再起動します。自動再起動の間隔は12時間以上です。`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`ノードの自動更新を有効化`},help:{"v1-1sa0yeg-7w":`長時間稼働するパッケージ化されたヘッドレスノードで、stableまたはbetaの自動更新を有効にします（デフォルト：true）。無効にするにはfalseを設定します。update.checkOnStart=falseまたはOPENCLAW_NO_AUTO_UPDATE=1でも無効になります。ソースのチェックアウト、ネイティブアプリ、プライベートワーカー、dev、extended-stableでは自動適用されません。`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`ノードのブラウザープロキシ`},help:{"v1-2xrew7-4f":`ノードルーティングを通じてローカルのブラウザ制御を公開するためのブラウザプロキシ設定をまとめます。リモートノードのワークフローでローカルのブラウザプロファイルが必要な場合にのみ有効にしてください。`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`ノードブラウザプロキシで許可するプロファイル`},help:{"v1-1ew5dkm-8b":`ノードプロキシルーティングを通じて公開するブラウザプロファイル名の任意の許可リストです。空のままにすると、プロファイルの作成・削除ルートを含む、デフォルトのすべてのプロファイル機能が維持されます。設定すると、OpenClaw はプロファイルへのアクセスを最小権限に制限し、プロキシ経由での永続プロファイルの作成・削除をブロックします。`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`ノードブラウザプロキシを有効化`},help:{"v1-pa04pd-5b":`ノードプロキシルーティングを通じてローカルのブラウザ制御サーバーを公開し、リモートクライアントがこのホストのブラウザ機能を利用できるようにします。リモート自動化で明示的に必要とされる場合を除き、無効のままにしてください。`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`ノードホストの MCP`},help:{"v1-1mdhrwl-48":`ヘッドレスノードホストが起動し、ペアリング済みの Gateway に公開した MCP サーバーを、エージェントツールとして使用します。このセクションを変更した後は、ノードホストを再起動してください。`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`ノードホストの MCP サーバー`},help:{"v1-19m002f-3x":`このノードのローカルにある、名前付きの MCP サーバー定義です。mcp.servers と同じサーバー定義形式を使用します。ノードホストは OAuth サーバーをサポートしていません。`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`ノードホストの Skills`},help:{"v1-v8txza-41":`このセクションでは、~/.openclaw/skills にインストールされたスキルをヘッドレスノードホストから公開します。スキルファイルを変更した後は、ノードホストを再起動してください。`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`ノードホストの Skills を有効化`},help:{"v1-1ggpkqb-36":`接続後に、ノードでホストされているスキルをスキャンして公開します（デフォルト：true）。ノードのスキル公開を無効にするには、false に設定してください。`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`ノードワーカーの実行`},help:{"v1-1w83rox-2p":`Gateway が管理するバンドルから、完全な OpenClaw ワーカーセッションのホスティングを有効にします。デフォルトでは無効です。`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`ノードワーカーの同時実行数`},help:{"v1-10nvk8f-3w":`このノードで同時にホストできるワーカーセッションの最大数（デフォルト：利用可能な CPU コア数）。1 から 1024 までの整数である必要があります。`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`ノードワーカー実行用コンテナイメージ`},help:{"v1-1oqx50o-5t":`コンテナで隔離されたワーカー用の任意の Node 24.16+ または 26.1+ イメージ（デフォルト："node:24.19.0-slim"）。必要に応じて、ダイジェストで固定したイメージ、プライベートレジストリのイメージ、または事前に読み込んだイメージを使用してください。存在しないイメージは初回使用時に取得されます。`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`ノードワーカーの実行を有効化`},help:{"v1-b3t0xp-2t":`このペアリング済みノードが、その Gateway によってインストールされたバンドルと完全に一致するバンドルからセッションをホストすることを許可します（デフォルト：false）。`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`ノードワーカー実行の隔離`},help:{"v1-19i6swo-58":`ワーカーセッションのプロセス境界を選択します。"none" はノードホスト上で直接実行します（デフォルト）。"container" には動作する Docker 互換エンジンが必要で、ホスト上での実行にフォールバックすることはありません。`}},plugins:{label:{"v1-10renyj-7":`プラグイン`},help:{"v1-1qbev2k-5c":`拡張機能の有効化、読み込み範囲の制限、エントリの設定、インストールの追跡を行うプラグインシステムの制御設定です。本番環境では、プラグインポリシーを明示的に定義し、最小権限を維持してください。`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`プラグイン許可リスト`},help:{"v1-pupwbe-7z":`プラグインIDの任意の許可リストです。設定すると、リストに含まれるプラグインのみが読み込み対象になります。ただし、設定済みの同梱チャットチャンネルは、設定で明示的に有効になっている場合、同梱プラグインを引き続き有効化できます。管理された環境で、承認済みの拡張機能のみを使用するために利用してください。`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`プラグイン拒否リスト`},help:{"v1-4gyt4z-4i":`許可リストやパスに含まれていてもブロックするプラグインIDの任意の拒否リストです。緊急時のロールバックや、リスクのあるプラグインの強制ブロックに拒否ルールを使用してください。`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`プラグインを有効にする`},help:{"v1-pnygd7-50":`起動時および設定の再読み込み時に、プラグインや拡張機能の読み込みを全体で有効または無効にします（デフォルト：true）。運用環境で拡張機能が必要な場合にのみ有効にしてください。`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`プラグインエントリ`},help:{"v1-cn74rf-54":`プラグインIDをキーとするプラグインごとの設定です。有効化の設定や、プラグイン固有の実行時設定データを含みます。全体の読み込みポリシーを変更せずに、個別のプラグインを調整するために使用してください。`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`プラグインAPIキー`},help:{"v1-ctytg2-53":`エントリ設定でキーの直接指定に対応するプラグインが使用する、任意のAPIキーフィールドです。シークレットや環境変数による置換を使用し、実際の認証情報を設定ファイルに含めてコミットしないでください。`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`プラグイン設定`},help:{"v1-1he672p-51":`プラグインが定義する設定データで、そのプラグイン独自のスキーマと検証ルールに従って解釈されます。設定が無視されたり無効になったりすることを防ぐため、プラグインのドキュメントに記載されたフィールドのみを使用してください。`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`プラグインを有効化`},help:{"v1-12soc0h-9a":`特定のエントリに対して、グローバルなプラグインポリシーより優先されるプラグイン単位の有効化設定です。デフォルトのハイブリッド再読み込みモードでは、このパスの変更にプラグインが再起動を必要としない限り、Gatewayを再起動せずにプラグインランタイムをホットリロードし、新しいエージェントターンから変更を適用します。環境ごとにプラグインを段階的に展開する際に使用してください。`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`プラグインの環境変数`},help:{"v1-p39pu4-52":`そのプラグインのランタイムコンテキストにのみ注入される、プラグイン単位の環境変数マップです。プロセス全体の環境を共有する代わりに、プロバイダーの認証情報を1つのプラグインに限定する際に使用してください。`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`プラグインのフックポリシー`},help:{"v1-1oslnrf-4c":`コアが強制適用する安全性チェックに対応した、プラグイン単位の型付きフックポリシー設定です。プラグイン全体を無効にせず、影響の大きいフックカテゴリを制限する際に使用してください。`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`会話アクセスフックを許可`},help:{"v1-xqz31z-7e":"このプラグインが、`before_agent_run`、`before_model_resolve`、`before_agent_reply`、`llm_input`、`llm_output`、`before_agent_finalize`、`agent_end`などの型付きフックから会話の生の内容を読み取れるかどうかを制御します。同梱されていないプラグインでは、明示的に許可する必要があります。"}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`プロンプトインジェクションフックを許可`},help:{"v1-7y6cny-32":"このプラグインが型付きフックを通じてプロンプトを変更できるかどうかを制御します。`before_prompt_build`をブロックするには、falseに設定してください。"}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`プラグインフックのタイムアウト（ミリ秒）`},help:{"v1-4ra6b7-74":`このプラグインの型付きフックに対するデフォルトのタイムアウト（ミリ秒）。上限は 600000 です。未設定の場合、各フックはプラグインで宣言されたタイムアウト、または Gateway のフックごとのポリシーを使用します。単一の固定デフォルト値はありません。hooks.timeouts のフックごとの値が優先されます。`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`プラグインフックのタイムアウトの上書き`},help:{"v1-yphl9b-5s":`型付きフック名をキーとして指定する、フックごとのタイムアウトの上書き値（ミリ秒）です。上限は600000です。すべてのフックのタイムアウトを延長するのではなく、before_prompt_buildやagent_endなど、処理が遅いとわかっているフックに限定して上書きしてください。`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`プラグインのLLMポリシー`},help:{"v1-dlca6c-4j":`api.runtime.llm.completeでモデルやエージェントの上書きを信頼するかどうかを、プラグインごとに制御します。プラグインがホスト管理の補完呼び出しを明示的に制御する必要がない限り、未設定のままにしてください。`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`プラグインによるLLMエージェントの上書きを許可`},help:{"v1-k8c08b-4n":`このプラグインがデフォルト以外のエージェントIDを対象にapi.runtime.llm.completeをリクエストすることを明示的に許可します。エージェントをまたぐモデルアクセスを任せられる信頼済みのプラグインでない限り、falseのままにしてください。`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`プラグインによるLLM認証プロファイルの上書きを許可`},help:{"v1-9ityw9-4x":`このプラグインが、分離されたエージェントランタイムでの補完にデフォルト以外の認証プロファイルを選択することを許可します。分離環境での明示的な認証情報のルーティングを任せられる信頼済みのプラグインでない限り、falseのままにしてください。`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`プラグインのLLMで許可する補完モデル`},help:{"v1-1ul08he-54":`すべてのプラグイン LLM 補完で許可する対象を、正規形式の "provider/model" 参照で指定します。ホストが解決したデフォルトとオーバーライドも含まれます。意図的に任意のモデルを許可する場合にのみ "*" を使用してください。`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`プラグイン LLM の許可モデル`},help:{"v1-154sk45-47":`信頼されたプラグインの LLM 呼び出しで許可するオーバーライド先を、正規形式の "provider/model" 参照で指定します。意図的に任意のモデルへのオーバーライドを許可する場合にのみ "*" を使用してください。`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`プラグイン LLM のモデルオーバーライドを許可`},help:{"v1-uw4jmc-47":`このプラグインが api.runtime.llm.complete でモデルのオーバーライドを要求することを明示的に許可します。モデル選択を任せられる信頼性のあるプラグインでない限り、false のままにしてください。`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`プラグインのサブエージェントポリシー`},help:{"v1-wbf4m1-4d":`モデルオーバーライドの信頼設定と許可リストを管理する、プラグインごとのサブエージェント実行時制御です。プラグインがサブエージェントのモデル選択を明示的に制御する必要がない限り、未設定のままにしてください。`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`プラグインのサブエージェントの許可モデル`},help:{"v1-2pvkow-42":`信頼されたプラグインのサブエージェント実行で許可するオーバーライド先を、正規形式の "provider/model" 参照で指定します。意図的に任意のモデルを許可する場合にのみ "*" を使用してください。`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`プラグインのサブエージェントのモデルオーバーライドを許可`},help:{"v1-1r5tzm1-4g":`このプラグインがバックグラウンドでのサブエージェント実行時にプロバイダーやモデルの上書きを要求することを明示的に許可します。モデル選択を任せられる信頼済みのプラグインでない限り、false のままにしてください。`}},"plugins%2Eload":{label:{"v1-9stn89-d":`プラグインローダー`},help:{"v1-1myjwbi-52":`プラグインの検出先となるファイルシステムパスを指定するためのプラグインローダー設定グループです。信頼できない拡張機能を誤って読み込まないよう、読み込みパスは明示的に指定し、確認してください。`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`プラグイン読み込みパス`},help:{"v1-o689p1-4z":`組み込みの既定パスに加えて、ローダーがスキャンするプラグインファイルまたはディレクトリです。拡張機能専用のディレクトリを使用し、無関係な実行可能コンテンツを含む広範なパスは避けてください。`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`プラグインスロット`},help:{"v1-zx6crl-5f":`メモリなどの排他的なランタイムスロットをどのプラグインに割り当てるかを選択し、その機能を単一のプラグインのみが提供するようにします。動作が競合するプロバイダーの重複を避けるため、スロットの割り当てを明示的に指定してください。`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`コンテキストエンジンプラグイン`},help:{"v1-4v13iw-2t":`有効にするコンテキストエンジンプラグインを ID で選択し、単一のプラグインがコンテキストのオーケストレーションを担うようにします。`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`メモリプラグイン`},help:{"v1-80ngcl-23":`有効にするメモリプラグインを ID で選択します。メモリプラグインを無効にするには "none" を指定してください。`}},presence:{label:{"v1-10fdwo4-8":`プレゼンス`}},proxy:{label:{"v1-ji57pa-d":`管理対象プロキシ`},help:{"v1-vui6bx-58":`OpenClaw ランタイムの HTTP、HTTPS、WebSocket、およびサポート対象の直接外向き通信経路に適用される、運用者管理のフォワードプロキシルーティングです。デプロイ環境の境界で外向き通信を一元管理する場合に使用してください。`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`マネージドプロキシの有効化`},help:{"v1-1456xdw-49":`マネージドプロキシの動作を明示的に上書きします。URL が存在すると、デフォルトでルーティングが有効になります。設定済みまたは環境変数のプロキシ URL を削除せずに無視するには、false に設定してください。`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`マネージドプロキシのループバックモード`},help:{"v1-1kaiuh0-3c":`マネージドプロキシモードが有効な間の Gateway のループバック制御プレーンのルーティングを制御します。指定できる値は "gateway-only"、"proxy"、"block" です。`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`マネージドプロキシの URL`},help:{"v1-p36b5l-3v":`マネージドフォワードプロキシの URL。通常の CONNECT プロキシには http:// を使用し、プロキシエンドポイント自体への接続に TLS が必要な場合は https:// を使用してください。`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`マネージドプロキシの TLS`},help:{"v1-6i0vu-3q":`マネージドプロキシのエンドポイントへの接続時に使用する TLS 設定です。これらの設定はプロキシの TLS に適用され、CONNECT 後の接続先の TLS には適用されません。`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`マネージドプロキシの TLS CA ファイル`},help:{"v1-1ntzjia-2p":`HTTPS マネージドプロキシのエンドポイント証明書を検証するために使用するカスタム CA バンドルのファイルシステムパスです。`}},secrets:{label:{"v1-1sihgpy-7":`シークレット`},help:{"v1-jgn0o9-2l":`シークレット参照プロバイダー、共有ストアの動作、および任意で有効にできるサブプロセスの外向き通信保護。`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`シークレットの外向き通信プロキシ`},help:{"v1-1qfgid-4n":`外向きリクエスト時にのみ共有ストアのシークレットセンチネルを置き換える、Gateway が管理するループバックプロキシです。このセクションの設定は起動時に適用されるため、変更後は Gateway を再起動してください。`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`シークレットの外向き通信プロキシの許可ホスト`},help:{"v1-9ypodl-6t":`リクエストと CONNECT トンネルに適用する、任意設定のトラフィック許可リストです。設定した場合、宛先はこのリスト、シークレットごとのホストバインディング、または bypassHosts のいずれかに含まれている必要があります。空のリストでは、バインド済みまたはバイパス対象のホストのみが許可されます。変更後は Gateway を再起動してください。`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`シークレット送信プロキシのバイパス対象ホスト`},help:{"v1-1oiiomv-57":`証明書ピンニングを使用するクライアント向けに、認証済みのブラインド CONNECT トンネルを使用するホスト名の完全一致リストです。センチネルは暗号文のまま維持され、平文が漏えいする代わりにベンダー認証が失敗します。`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`シークレット送信プロキシの有効化`},help:{"v1-u99b1i-2h":`Gateway 上で実行されるエージェントのサブプロセスに対して、送信時のシークレット置換を有効にします。デフォルト：false。`}},session:{label:{"v1-8yh9jr-7":`セッション`},help:{"v1-j86s32-5d":`会話履歴の動作を制御する、グローバルなセッションルーティング、リセット、配信ポリシー、およびメンテナンス設定です。分離、保持、配信に関してより厳しい制約が必要な場合を除き、デフォルトのままにしてください。`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`DM セッションのスコープ`},help:{"v1-ql362c-5l":`DM セッションのスコープ設定です。"main" は継続性を維持し、"per-peer"、"per-channel-peer"、"per-account-channel-peer" は分離を強化します。共有受信トレイや複数アカウントの環境では、分離モードを使用してください。`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`グループセッションのスコープ`},help:{"v1-1fdezx2-6i":`グループ／チャンネルのセッションスコープ設定です。"per-group" は dmScope とは独立して各ルームを分離し、エージェントのメインセッションがバックグラウンドでそれらを監視します。"main" はルームのコンテキストをメインセッションに統合するため、監視は不要です。"main" は信頼できるルームにのみ使用してください。`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`セッションの ID リンク`},help:{"v1-1y5jnsm-5n":`正規のIDをプロバイダー接頭辞付きのピアIDに対応付け、同一ユーザーが1つのDMスレッドに解決されるようにします（例：telegram:123456）。同じ人物が複数のチャネルやアカウントを使用する場合に利用します。`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`セッションのメインキー`},help:{"v1-18p638h-3q":`指定は可能ですが、無視されます。エージェントごとのメインセッションの接尾辞は常に "main" です。このフィールドは省略してください。グローバルセッションスコープでは、代わりに "global" が使用されます。`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`セッションのメンテナンス`},help:{"v1-imr441-66":`セッションストアの自動メンテナンス設定です。ダッシュボードのアーカイブ、削除までの経過期間、エントリ数の上限、リセット時のアーカイブ保持期間、ディスク容量制限に基づくクリーンアップを制御します。まず warn モードで影響を確認し、しきい値を調整してから enforce に切り替えてください。`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`非アクティブなダッシュボードセッションをアーカイブするまでの期間`},help:{"v1-1frdtub-5n":"指定した期間（例：`7d`）が経過すると、非アクティブなダッシュボードセッションをアーカイブします。これにより、アクティブなセッション一覧を圧迫せずに、引き続きセッションを利用できます。ダッシュボードの自動アーカイブを無効にするには、`false` または `0` を設定してください。"}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`トランスクリプトのコールドストレージ`},help:{"v1-1kp9s9h-5s":`セッションメタデータを保持したまま、非アクティブなトランスクリプトを圧縮JSONLアーカイブに移動します。アーカイブファイルは必須の履歴となるため、バックアップに含める必要があります。変更はGatewayを再起動せずに適用されます。`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`アーカイブまでの非アクティブ日数`},help:{"v1-zay1q3-5b":`指定した日数（正の整数、デフォルトは30日）にわたって非アクティブなトランスクリプトをアーカイブします。進行中の作業は保護されます。しきい値の変更はGatewayの再起動なしで、次回のワーカー処理時に反映されます。`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`古いトランスクリプトを自動的にアーカイブ`},help:{"v1-6p6vmb-5a":`バックグラウンドでのトランスクリプトのアーカイブを有効にします（デフォルトは false）。ワーカーが毎分、対象のトランスクリプトを確認します。この明示的なアーカイブポリシーは、削除やディスク容量上限に基づくクリーンアップとは別のものです。`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`セッションのディスク使用量の目標上限`},help:{"v1-143vh09-7z":`ディスク容量制限に基づくクリーンアップ後の目標サイズ（上限基準値）です。デフォルトは maxDiskBytes の80%です。ディスク容量が限られている場合は、明示的に設定することで、より厳密に容量を回収できます。ゼロと評価される値を指定するとデフォルトに戻ります。負の値は無効です。容量制限を無効にするには、代わりに maxDiskBytes を使用してください。`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`セッションの最大ディスク容量制限`},help:{"v1-147lxk3-cj":'SQLite のメインファイルと WAL、および集計対象のセッションディレクトリ内の生成物を含む、エージェントごとの物理ディスク使用量の上限（例：`500mb`）。デフォルトは `10gb` です。保護されたデータにより、使用量が目標値を超えたままになる場合があります。上限を超えた場合、warn モードでは容量の逼迫を報告し、enforce モードでは古いリセット・削除時の生成物、参照されていない履歴、上限適用によって作成されたアーカイブの順に削除します。手動、保存期間、ダッシュボード、復旧処理によるアーカイブ、およびレガシーアーカイブは引き続き保護されます。無効にするには `false`、`0`、または `"0"` を設定します。'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`セッションの最大エントリ数`},help:{"v1-1w2egrh-7u":`未アーカイブのセッションエントリ数に上限を設けます（デフォルトは 5000）。上限を超えた永続保存対象の会話のうち、条件を満たすものは履歴とともにアーカイブされ、使い捨ての自動化エントリは削除されます。既存のアーカイブは上限にカウントされません。保護されたアクティブなエントリは引き続きカウントされるため、保存エントリ数が上限を超えたままになる場合があります。`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`セッションメンテナンスモード`},help:{"v1-bq39hk-6v":`プルーニングとディスク容量上限のポリシーについて、報告のみを行うか（"warn"）、実際に適用するか（"enforce"）を指定します。導入中は "warn" のままにし、安全な閾値を検証してから "enforce" に切り替えてください。コールドストレージには、明示的に有効化するための独立した enabled 設定があります。`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`最近のセッションを保持`},help:{"v1-138q5wx-89":"指定した期間内（例：`7d`）にアクティブだった対話型セッションを、経過期間、件数、ディスク使用量の上限に基づく自動的な履歴削除から保護します。未設定または `false` の場合は、通常の古いものから順に処理するポリシーを維持します。自動生成されたモデル実行、cron、フック、ハートビート、ACP、サブエージェントの行は、引き続き上限に基づくクリーンアップの対象となります。"}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`セッション削除までの期間`},help:{"v1-1xn50w7-76":"この期間（デフォルトは `30d`、例：`12h`）を超えた、対象となる永続的な会話をアーカイブし、一時的な自動化エントリを削除します。アーカイブされた会話の履歴は保持され、復元できます。保護されている会話やルーティング可能な会話はアクティブなまま維持されます。"}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`セッションリセットのアーカイブ保持期間`},help:{"v1-16amrs1-7r":"アーカイブされた会話記録（`*.reset.<timestamp>` および `*.deleted.<timestamp>`）の経過時間に基づく保持設定です。デフォルトでは、ディスク容量の上限により古い順に削除されるまでアーカイブを保持します。実時間の経過に基づく削除を有効にするには期間（例：`30d`）を設定し、明示的に無効にするには `false` を設定します。"}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`セッション作成時にホームに通知`},help:{"v1-c4prn5-8b":`セッションが作成されたときに、所有エージェントのホームセッションでシステム通知をキューに追加します（デフォルト: true）。通知には、利用可能なタイトルと作成者のメタデータが含まれ、ホームでの次のターンまたはハートビートで読み取られます。無効にするには false に設定してください。下書き、シークレットセッション、内部セッション、およびスケジュールされた cron 実行は対象外です。`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`セッションリセットポリシー`},help:{"v1-1hmt7n3-6r":`タイプ別またはチャネル別の上書き設定が適用されない場合に使用する、デフォルトのリセットポリシーオブジェクトを定義します。デフォルトではセッションは自動的にリセットされません。有効にするには、毎日またはアイドル時のスケジュールを設定してください。/new と /reset はいつでも使用できます。`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`セッションの毎日のリセット時刻`},help:{"v1-wry8cv-59":`毎日リセットするモードで、セッションが予測可能な時刻に切り替わるよう、現地時間の区切り（0～23時）を設定します。mode=daily と併用し、運用者が想定するタイムゾーンに合わせることで、わかりやすい動作になります。`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`セッションリセットまでのアイドル時間（分）`},help:{"v1-1kzj0id-5e":`アイドルモードでリセットするまでの非アクティブ時間を設定します。毎日リセットするモードでも、補助的な条件として機能します。継続性を保つには大きい値を、短期間のスレッドをより頻繁に新しくするには小さい値を使用してください。`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`セッションリセットモード`},help:{"v1-e5ie4w-5b":`リセット方式を選択します。「none」は自動リセットを無効にし（デフォルト）、「daily」は設定した時刻にリセットし、「idle」は操作のない状態が続くとリセットします。どのモードでも /new と /reset は引き続き使用できます。`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`チャンネル別のセッションリセット`},help:{"v1-1uxsulx-5h":`プロバイダー/チャンネル ID をキーとして、チャンネル固有のリセット設定を上書きし、動作を細かく制御します。特定のチャンネルで、種類別のポリシーとは異なる例外的なリセット動作が必要な場合にのみ使用してください。`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`チャットの種類別のセッションリセット`},help:{"v1-ypdr7u-52":`デフォルト設定では不十分な場合に、チャットの種類（ダイレクト、グループ、スレッド）ごとにリセット動作を上書きします。グループやスレッドでのやり取りに、ダイレクトメッセージとは異なるリセット間隔が必要な場合に使用してください。`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`セッションリセット（ダイレクト）`},help:{"v1-fjnlp5-56":`ダイレクトチャットのリセットポリシーを定義し、この種類に対する基本の session.reset 設定より優先されます。従来の dm エイリアスではなく、ダイレクトメッセージ用の正式な上書き設定として使用してください。`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`セッションリセット（グループ）`},help:{"v1-hl1200-4u":`会話の継続性やノイズのパターンがダイレクトメッセージとは異なる、グループチャットセッションのリセットポリシーを定義します。やり取りの多いグループでコンテキストのずれが問題になる場合は、アイドル時間を短く設定してください。`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`セッションリセット（スレッド）`},help:{"v1-1hgpeke-4w":`特定のチャンネルスレッドに集中したワークフローを含む、スレッド単位のセッションのリセットポリシーを定義します。スレッドのセッションを、他の種類のチャットより早く、または遅く期限切れにする場合に使用してください。`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`セッションリセットのトリガー`},help:{"v1-rcabsw-5a":`受信内容に一致するとセッションを強制的にリセットするメッセージトリガーの一覧です。通常の会話中にコンテキストが予期せず失われないよう、明示的なリセット用フレーズに限定して使用してください。`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`セッションのスコープ`},help:{"v1-axt4ds-5z":`セッションの基本的なグループ化方式を設定します。"per-sender" は送信者ごとに分離し、"global" はチャネルのコンテキストごとに1つのセッションを共有します。コンテキストの共有が意図的に必要な場合を除き、複数ユーザーでより安全に利用できるよう "per-sender" を維持してください。`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`セッションの送信ポリシー`},help:{"v1-17qpipb-5l":`channel、chatType、キープレフィックスに対して評価される許可・拒否ルールを使用して、セッション間の送信権限を制御します。複雑な環境でセッションツールがメッセージを配信できる宛先を制限するために使用します。`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`セッション送信ポリシーのデフォルトアクション`},help:{"v1-15plhut-53":`どの sendPolicy ルールにも一致しない場合のフォールバックアクションを "allow" または "deny" に設定します。シンプルな構成では "allow" を維持し、すべての宛先に明示的な許可ルールが必要な場合は "deny" を選択してください。`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`セッション送信ポリシーのルール`},help:{"v1-o217za-5h":'デフォルトアクションより前に順番に評価される許可・拒否ルールです。例：`{ action: "deny", match: { channel: "discord" } }`。広範なルールによって例外が適用されなくなることを防ぐため、最も具体的なルールを先に配置してください。'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`セッション送信ルールのアクション`},help:{"v1-178vm80-54":`対応する一致条件が満たされたときのルールの判定を "allow" または "deny" として定義します。明示的な許可例外を設けつつ厳格な制限を適用する場合は、拒否ルールを先に配置してください。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`セッション送信ルールの一致条件`},help:{"v1-18qh5qg-5d":`channel、chatType、キープレフィックスの制約を組み合わせられる、任意のルール一致条件を定義します。ポリシーの意図を読み取りやすくし、デバッグを容易に保つため、一致条件は絞り込んでください。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`セッション送信ルールのチャンネル`},help:{"v1-u5erwx-50":`特定のチャンネル／プロバイダー ID（例：discord、telegram、slack）に一致する場合にルールを適用します。あるチャンネルで、他のチャンネルとは独立して配信を許可または拒否する必要がある場合に使用してください。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`セッション送信ルールのチャットタイプ`},help:{"v1-7cv4f9-4z":`チャットタイプ（direct、group、thread）に一致する場合にルールを適用し、会話形式に応じて動作を変えます。DM とグループの送信先で異なる安全上の制限が必要な場合に使用してください。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`セッション送信ルールのキープレフィックス`},help:{"v1-ac4dee-5n":`ポリシーを使用する側での内部的なキー正規化処理後に、正規化されたセッションキーのプレフィックスと照合します。一般的なプレフィックス制御にはこれを使用し、完全なキーとの厳密な照合が必要な場合は rawKeyPrefix を優先してください。`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`セッション送信ルールの未加工キープレフィックス`},help:{"v1-1g9w044-5e":`正規化されていない生のセッションキーのプレフィックスに一致させ、完全なキーを対象とするポリシーを正確に適用します。正規化された keyPrefix では対象が広すぎる場合や、エージェントのプレフィックスまたはトランスポート固有の精度が必要な場合に使用してください。`}},"session%2Esharing":{label:{"v1-ua4axr-l":`セッション共有モード`},help:{"v1-xbh52d-5a":`セッションの所有者と管理者が選択できるコラボレーションモードを制御します。省略されたブール値はデフォルトで有効になります。モードを false に設定すると、選択肢から削除され、新たな選択が拒否されます。`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`下書きセッションを許可`},help:{"v1-1lzap27-2p":`公開範囲を下書きに設定できるようにします。所有者でも管理者でもないオペレーターにはセッションが表示されません。デフォルト：true。`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`読み取り専用セッションを許可`},help:{"v1-upl3nu-21":`参加者以外に対してセッションを読み取り専用にできるようにします。デフォルト：true。`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`提案セッションを許可`},help:{"v1-4i8owu-4g":`公開範囲を提案モードに設定できるようにします。現段階では読み取り専用と同じアクセス許可ポリシーが適用されます。提案キューは今後の機能で設定されます。デフォルト：true。`}},"session%2Estore":{label:{"v1-1udxgtl-i":`セッションストアのパス`},help:{"v1-hreznz-56":`再起動後もセッション記録を保持するために使用するセッション保存ファイルのパスを設定します。独自のディスク構成、バックアップ先の指定、またはマウントされたボリュームへの保存が必要な場合にのみ、明示的なパスを指定してください。`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`セッションのスレッド紐付け`},help:{"v1-zbzihu-4s":`対応チャネル全体で、スレッドに紐づくセッションの生成とルーティングに使用する共通のデフォルト設定です。ここでグローバルなデフォルトを設定し、動作が異なる場合にのみチャネルごとに上書きしてください。`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`スレッド生成時のコンテキスト`},help:{"v1-1set6nw-4c":`スレッドに紐づく生成で使用する、ネイティブサブエージェントのデフォルトのコンテキストです。リクエスト元の会話履歴から開始するには "fork"、履歴のない子セッションを作成するには "isolated" を使用してください。デフォルト："fork"。`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`スレッド紐づけを有効化`},help:{"v1-foomtc-3f":`スレッドに紐づくセッションの生成、ルーティング、配信を制御するグローバルなマスタースイッチです。無効にすると、スレッド紐づけが全体でオフになります。`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`スレッド紐づけのアイドルタイムアウト（時間）`},help:{"v1-gffnx3-3h":`プロバイダーやチャネル全体で、スレッドに紐づくセッションに適用されるデフォルトの非アクティブ許容時間です（0 にするとアイドル状態による期限切れを無効化）。デフォルト：24。`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`スレッド紐づけの最大存続時間（時間）`},help:{"v1-1xfcyhw-39":`プロバイダーやチャネル全体で、スレッドに紐づくセッションに適用する厳密な最大存続時間です。任意で設定できます（0 にすると上限を無効化）。デフォルト：0。`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`スレッドに紐づくセッションの生成`},help:{"v1-1lqwbdl-46":`sessions_spawn および ACP スレッド生成による、スレッドに紐づく作業セッションの作成を許可するかどうかを決めるグローバルなデフォルト設定です。デフォルト：スレッド紐づけが有効な場合は true。`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`許可するスキルのシンボリックリンク先`},help:{"v1-xzybiq-4t":`スキルのシンボリックリンクの解決先が設定済みのソースルート外にある場合に許可する、信頼できる実体のターゲットルートです。兄弟リポジトリのスキルディレクトリなど、狭い範囲に限定してください。`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`追加のスキルディレクトリ`},help:{"v1-11o7opu-53":`最も低い優先順位でスキャンする、追加の共有スキルルートです。OpenClaw ワークスペースにコピーせずに利用したい兄弟リポジトリや共有スキルパックに使用してください。`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Skills を監視`},help:{"v1-1ckr2l5-5d":`スキル定義の変更を検出するファイルシステム監視を有効にし、プロセス全体を再起動せずに更新を適用できるようにします。開発ワークフローでは有効にし、変更不可の本番イメージでは無効にしてください。`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Skill Workshop 自律モード`},help:{"v1-1s3kgit-6j":`バックグラウンド学習を制御します。「off」では提案を促す通知のみを維持し、「propose」では保留中の提案を作成します。「auto」では収集した提案を適用し、通常のファイル編集を通じて Workshop が管理するスキルの週次レビューを実行します。デフォルト：「auto」。`}},surfaces:{label:{"v1-exl2ye-g":`サーフェスポリシー`},help:{"v1-vgtjbs-50":`解決済みの配信サーフェス ID をキーとする、サーフェスごとのメッセージポリシーの上書き設定です。デプロイ済みの特定のサーフェスで、エージェントのデフォルトより厳格なサイレント返信処理が必要な場合にのみ使用してください。`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`サーフェスのサイレント返信ポリシー`},help:{"v1-12zgc3n-60":`解決済みの単一の配信サーフェスについて、サイレント返信ポリシーを上書きします。未設定のフィールドは agents.defaults.silentReply を継承します。内部向けまたはグループ固有の動作が他の配信先に影響しないよう、対象範囲を絞ったサーフェス ID を使用してください。`}},talk:{label:{"v1-15ukbjj-4":`会話`},help:{"v1-1gx10xa-5g":`Talk モードの音声合成設定です。声の種類、モデルの選択、出力形式、割り込み動作を設定します。このセクションで、遅延とコストを抑えながら、ユーザー向けの音声 UX を調整できます。`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Talk エージェント`},help:{"v1-iee5l9-2b":`エージェントスコープの明示的なセッションキーなしで作成された Talk セッションを所有するエージェントです。`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Talk 相談の高速モード`},help:{"v1-syf3xk-2o":`Talk のリアルタイム相談の背後で実行される通常のエージェントの高速モードを、true または false に設定します。`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Talk 相談の思考レベル`},help:{"v1-1ft5njw-2o":`Talk のリアルタイム相談の背後で実行される通常のエージェントの思考レベルを上書きします。`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Talk での発話による割り込み`},help:{"v1-8n9q4o-3l":`true（デフォルト）の場合、Talk モードでユーザーが話し始めると、アシスタントの発話を停止します。交互に会話するには、有効のままにしてください。`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Talk のアクティブなプロバイダー`},help:{"v1-wgnxhg-1g":`Talk のアクティブなプロバイダー ID（例："acme-speech"）です。`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Talk プロバイダー設定`},help:{"v1-oh0yuv-30":`プロバイダー ID をキーとする、プロバイダー固有の Talk 設定です。移行時は、従来の talk.* キーよりもこちらを優先してください。`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Talk プロバイダー構成`},help:{"v1-36pblg-1r":`対応するプロバイダー ID のプロバイダーが管理する Talk 構成フィールドです。`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Talk プロバイダー API キー`},help:{"v1-1a1p9wp-v":`Talk モード用のプロバイダー API キーです。`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk リアルタイム`},help:{"v1-c2re7j-3z":`リアルタイム Talk のプロバイダー、モデル、音声、モード、トランスポート、推論戦略。音声認識/TTS プロバイダーの設定は talk.provider と talk.providers に保持してください。`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Talk リアルタイム推論`},help:{"v1-opsatw-37":`Talk の推論戦略：Gateway を介したエージェント支援には agent-consult、ローカルのツール呼び出しには direct-tools、使用しない場合は none。`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Talk リアルタイム相談ルーティング`},help:{"v1-10qjcvk-5f":`リアルタイムプロバイダーが openclaw_agent_consult をスキップした場合に、ユーザー発話の確定済み文字起こしを Gateway 経由で中継するフォールバック。provider-direct はプロバイダーの応答を維持し、force-agent-consult は OpenClaw 経由でルーティングします。`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Talk リアルタイム指示`},help:{"v1-1jaaj84-5p":`OpenClaw の組み込みリアルタイム Talk プロンプトに追加されるシステム指示。agent-consult のガイダンスを維持しながら、音声のスタイル、トーン、その他のプロバイダー向けリアルタイム動作を指定するために使用します。`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Talk リアルタイムモード`},help:{"v1-1u2xui1-1l":`Talk の実行モード：realtime、stt-tts、または transcription。`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Talk リアルタイムモデル`},help:{"v1-amou5a-27":`ブラウザーまたは Gateway が管理する Talk セッション用のリアルタイムプロバイダーのモデル ID の上書き。`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Talk リアルタイム先頭パディング（ms）`},help:{"v1-1cwg07n-22":`リアルタイムの発話検出前に保持する音声の長さ（ミリ秒）。`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Talk リアルタイムプロバイダー`},help:{"v1-wwsmpt-1o":`有効なリアルタイム音声プロバイダーの ID（openai や google など）。`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Talk リアルタイムプロバイダー設定`},help:{"v1-ruagcu-1r":`プロバイダー ID をキーとする、プロバイダー固有のリアルタイム音声設定。`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Talk リアルタイムプロバイダー構成`},help:{"v1-edfpxm-1u":`対応するプロバイダー ID に対してプロバイダーが管理するリアルタイム音声構成。`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Talk リアルタイムプロバイダー API キー`},help:{"v1-1fbmgpx-z":`リアルタイム Talk 用のプロバイダー API キー。`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Talk リアルタイム推論強度`},help:{"v1-157xd3e-2t":`リアルタイム Talk セッションでのプロバイダー固有の推論強度（minimal、low、medium、high など）。`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Talk リアルタイム無音時間（ms）`},help:{"v1-1grnu06-1y":`リアルタイム Talk でユーザーの発話ターンが確定されるまでの無音時間（ミリ秒）。`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talk リアルタイム話者音声`},help:{"v1-1kgb166-2h":`ブラウザーまたは Gateway が管理する Talk セッションで、リアルタイムプロバイダーの話者音声名を上書きする設定。`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talk リアルタイム話者音声 ID`},help:{"v1-1k8w6vk-2f":`ブラウザーまたは Gateway が管理する Talk セッションで、リアルタイムプロバイダーの話者音声 ID を上書きする設定。`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Talk リアルタイムトランスポート`},help:{"v1-2otjgn-2g":`Talk のバイト／セッション転送方式：webrtc、provider-websocket、gateway-relay、または managed-room。`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Talk リアルタイム VAD しきい値`},help:{"v1-nf5l2t-2j":`リアルタイム音声区間検出のしきい値。0（感度が最も高い）から 1（感度が最も低い）までの値を指定します。`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Talk 無音タイムアウト（ms）`},help:{"v1-1kim32f-59":`Talk モードで現在の文字起こしを確定して送信するまでの、ユーザーの無音時間（ミリ秒）。未設定の場合、プラットフォームのデフォルトの待機時間（macOS と Android では 700 ms、iOS では 900 ms）が使用されます。`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Talk 音声ロケール`},help:{"v1-1un3x4l-4c":`デバイスノードでの Talk 音声認識と、iOS のシステム音声へのフォールバックに使用する BCP 47 ロケール ID（例："ru-RU"）。未設定の場合、各デバイスのデフォルトが使用されます。`}},telemetry:{label:{"v1-sqprmo-9":`テレメトリ`},help:{"v1-1o5tru3-55":`毎日の更新確認に添付される匿名の機能利用統計への明示的な同意。機能利用統計はデフォルトで無効になっており、メッセージ、認証情報、識別子が含まれることはありません。`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`機能利用統計への同意タイムスタンプ`},help:{"v1-1t051az-3t":`運用担当者が匿名の機能利用統計に同意または拒否した日時を記録する ISO タイムスタンプ。セットアップウィザードでの再確認を防ぎます。`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`匿名の機能利用統計`},help:{"v1-1ptrwuq-4r":`毎日の更新確認時に、有効なチャネルとプロバイダーの名前、プラグイン数、最近のセッション数を共有します。デフォルトでは無効で、DO_NOT_TRACK=1 の場合は常に無効になります。`}},tools:{label:{"v1-15cdqf0-5":`ツール`},help:{"v1-1el54kl-5h":`ツールのインフラストラクチャとエージェント間のデフォルト設定。ルート直下の同階層の項目はインフラストラクチャとエージェント間のデフォルト設定を管理し、agents.defaults はエージェントループの動作を管理します。各エージェントの設定では、サポートされている範囲でいずれも上書きできます。`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`エージェント間のツールアクセス`},help:{"v1-1ynpa5f-cf":`エージェント間のセッションツール呼び出し（送信、一覧取得、履歴取得、検索、ステータス読み取り）のポリシーです（デフォルト：有効）。allow を使用すると、エージェントの組み合わせを制限できます。enabled=false にすると、通常のエージェント間アクセスがブロックされます。可視性が tree または all の場合、リクエスト元が所有するネイティブサブエージェントと ACP 子セッションには引き続きアクセスできます。厳密に分離するには、tools.sessions.visibility を agent または self に設定するか（tree ではリクエスト元が所有するネイティブ/ACP の子セッションへのアクセスが引き続き許可されます）、個別のゲートウェイを使用してください。`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`エージェント間のアクセス対象許可リスト`},help:{"v1-1jt2ari-76":`エージェント間の呼び出しに参加できるエージェントの ID または * パターンです。リクエスト元と対象のエージェントの両方が一致する必要があります。エージェント間アクセスはデフォルトで有効になっており、allow を省略するか空にすると、すべての組み合わせが許可されます。アクセスを制限するには、明示的なリストを設定してください。空白のエントリはアクセスを拒否します。`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`エージェント間ツールを有効にする`},help:{"v1-w950oq-ba":`エージェント間のセッションツールアクセスを有効にします（デフォルト：true）。allow を省略するか空にすると、すべてのエージェントの組み合わせが許可されます。通常のエージェント間アクセスをブロックするには、false に設定してください。可視性が tree または all の場合、リクエスト元が所有するネイティブサブエージェントと ACP 子セッションには引き続きアクセスできます。厳密に分離するには、tools.sessions.visibility を agent または self に設定するか（tree ではリクエスト元が所有するネイティブ/ACP の子セッションへのアクセスが引き続き許可されます）、個別のゲートウェイを使用してください。`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`ツール許可リスト`},help:{"v1-1is3eaq-4v":`厳格な環境向けに、プロファイル由来のデフォルト設定を置き換える絶対的なツール許可リストです。ツール機能を厳選した一部に意図的に限定して実行する場合にのみ使用してください。`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`ツール許可リストへの追加`},help:{"v1-1xw9zp8-57":`選択したツールプロファイルとデフォルトポリシーに追加で統合されるツール許可リストのエントリです。監査時に意図的なポリシー例外をすばやく特定できるよう、このリストは少数の明示的なエントリに留めてください。`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`プロバイダー別のツールポリシー`},help:{"v1-1ecljob-4y":`チャネル／プロバイダーIDをキーとして、プロバイダーごとにツールの許可／拒否を上書きし、利用先に応じて機能を調整します。特定のプロバイダーでグローバルなツールポリシーより厳しい制御が必要な場合に使用してください。`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`コードモード`},help:{"v1-1ecc39k-6k":'汎用の OpenClaw Code Mode。グローバル設定で省略した場合、デフォルトは `"auto"` です。オブジェクトを明示的に定義しても `enabled` がなければ、オフのままになります。有効化されたエージェント実行では、モデルには `exec` と `wait` のみが公開され、通常のツールにはカタログブリッジ経由でアクセスします。'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`コードモードを有効にする`},help:{"v1-rgstxz-aj":'OpenClaw Code Mode のグローバルな有効化設定。グローバル設定がまったく存在しない場合、デフォルトは `"auto"` です。オブジェクトを明示的に定義しても `enabled` がなければ、オフのままになります。`"auto"` はカタログで優先指定されたモデルに対して有効化し、`true` はツール対応の実行に対して有効化します。エージェントおよびモデルごとの有効化設定のオーバーライドが優先されます。有効化された実行でランタイムが利用できない場合は、ツール一覧全体を公開するのではなく、安全のため実行を停止します。'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`コードモードの実行エンジン`},help:{"v1-l8nlk2-6x":`JavaScript実行エンジン："node"（デフォルト）は信頼できるコードにNode vmを使用しますが、セキュリティサンドボックスではありません。"quickjs"は同梱のQuickJS WASMプラグインを使用し、ゲストコードの実行時のセキュリティを強化します。ツールの権限は両方に適用されます。選択した実行エンジンが存在しない場合、安全のため実行を拒否します。`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`コードモードの出力上限`},help:{"v1-1hmij9q-1n":`コードモードの出力として返される、シリアライズ後の最大バイト数です。`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`コードモードの保留中ツール呼び出し上限`},help:{"v1-3b5tyd-2i":`コードモード VM が、後で再開するために中断するまでに開始できる、同時実行のネストされたツール呼び出しの最大数。`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`コードモードの最大検索結果数`},help:{"v1-1gpue5r-28":`コードモードのプログラムが要求できる非表示カタログの検索結果の最大数。`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`コードモードのスナップショット上限`},help:{"v1-1mmgkqy-1x":`中断中の QuickJS スナップショット1件に対して保持されるシリアライズ済みデータの最大バイト数。`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`コードモードのメモリ上限`},help:{"v1-xetora-6n":`QuickJS ゲストのヒープ上限、または Node ワーカーの V8 ヒープに対するベストエフォートのメモリ予算（バイト単位）。Node ランタイムのオーバーヘッドとエンジンの最小メモリ割り当て量が実効予算に影響します。外部バッファとプロセスの RSS は対象外です。これはセキュリティを保証するものではありません。`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`コードモードの公開インターフェース`},help:{"v1-dsp2b9-2x":'モデル向けのインターフェース。"only" のみサポートされています。コードモードの `exec` と `wait` を公開し、通常のツールを非表示にします。'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`コードモードのデフォルト検索結果数`},help:{"v1-1io42lu-2m":"コードモード内の `catalog.search` が返す非表示カタログの検索結果のデフォルト件数。"}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`コードモードのスナップショット TTL`},help:{"v1-1nxfczz-28":"一時停止中の Code Mode の実行が、有効期限切れになるまで `wait` で再開できる期間。"}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`コードモードのタイムアウト`},help:{"v1-8csycm-1p":"コードモードの `exec` または `wait` 呼び出し1回あたりの最大時間（ミリ秒）。"}},"tools%2Edeny":{label:{"v1-fwuia7-d":`ツールの拒否リスト`},help:{"v1-wilr1b-4p":`プロファイルやプロバイダーのルールで許可されていても、指定されたツールをブロックするグローバルなツール拒否リストです。緊急時のアクセス遮断や長期的な多層防御に拒否ルールを使用してください。`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`ツールへの特権アクセス`},help:{"v1-ehcm0r-5a":`信頼できる送信者のみが利用できる特権コマンド機能に対する、ツールの特権アクセス制御です。運用ワークフローで特権操作が明示的に必要とされる場合を除き、無効のままにしてください。`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`特権ツールの許可ルール`},help:{"v1-1u9bhih-54":`特権ツールの利用を許可する送信者ルールです。通常は、チャネルやプロバイダーの識別子形式をキーとして指定します。意図しないユーザーが特権コマンドを実行できないよう、対象を限定した明示的な識別子を使用してください。`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`ツールへの特権アクセスを有効にする`},help:{"v1-1n8oyal-4l":`送信者とポリシーのチェックに合格した場合に、ツールの特権実行経路を有効にします。公開チャネルや共有チャネルでは無効のままにし、信頼できる所有者が運用する環境でのみ有効にしてください。`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`実行ツール`},help:{"v1-p5piic-56":`シェル実行ホスト、セキュリティモード、承認動作、ランタイムバインディングに関する実行ツールのポリシー設定群です。本番環境では安全重視のデフォルト設定を維持し、特権実行経路の制限を強化してください。`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`apply_patch のモデル許可リスト`},help:{"v1-4q5ovf-1x":`モデルIDの許可リスト（任意、例："gpt-5.4" または "openai/gpt-5.4"）。`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`apply_patchを有効化`},help:{"v1-1erkir4-31":`ツールポリシーで許可されている場合に、OpenAIおよびOpenAI Codexモデルでapply_patchを有効または無効にします（デフォルト：true）。`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patchをワークスペース内に限定`},help:{"v1-x2z207-3o":`apply_patchのパスをワークスペースディレクトリ内に制限します（デフォルト：true）。falseに設定すると、ワークスペース外への書き込みを許可します（危険）。`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`実行承認後の実行中通知の遅延（ミリ秒）`},help:{"v1-1gwwann-4z":`実行が承認されてから、実行中の通知を表示するまでの遅延時間（ミリ秒）。長くすると短時間で完了するコマンドによるちらつきを抑えられ、短くすると操作者にすばやくフィードバックを提供できます。`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`実行時の承認確認`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`実行コマンドのハイライト`},help:{"v1-kyxd4o-4n":`実行承認プロンプトに、パーサーの解析結果に基づくコマンドのハイライトを表示します（デフォルト：false）。有効にすると、実行承認ポリシーを変更せずにコマンドテキストをハイライト表示できます。`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`継続的な許可の有効期間（日）`},help:{"v1-5uxe2j-6r":`自動化の承認時にallow-alwaysで発行される継続的な許可の、デフォルトの有効期間（日数、1～3650）。未設定の場合、許可は取り消されるか、紐づく自動化が変更されるまで有効です。条件は発行時に確定するため、この設定の変更は今後発行される許可にのみ適用されます。`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`実行先`},help:{"v1-rno1mf-5q":`シェルコマンドの実行先を選択する方式を指定します。実行環境に応じた動作（利用可能なら sandbox、それ以外は gateway）には "auto" を使用します。実行先を固定する必要がある場合は、sandbox/gateway/node を明示的に指定します。`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`実行モード`},help:{"v1-1wi6t4l-5q":`正規化された実行ポリシーの選択設定です。承認条件を満たさない場合に分類器による審査を行うには "auto"、人間による審査を行うには "ask"、安全と確定できるコマンドのみを許可するには "allowlist"、信頼できるローカル環境での操作には "full" を使用します。`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`実行ノードのバインド`},help:{"v1-rfnz54-4s":`接続済みノードを介してコマンド実行を委任する際の、実行ツール用ノードバインド設定です。明示的なノードバインドは、複数ノード間のルーティングが必要な場合にのみ使用してください。`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`実行終了時に通知`},help:{"v1-1ounlvx-3q":`true（デフォルト）の場合、バックグラウンド実行セッションの終了時、およびノード実行のライフサイクルイベント発生時に、システムイベントをキューに追加し、ハートビートを要求します。`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`出力なしの実行成功時に通知`},help:{"v1-1wx4xxd-3d":`true の場合、バックグラウンド実行が出力なしで正常終了した場合でも、完了を示すシステムイベントをキューに追加します（デフォルト: false）。`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`実行時の PATH 先頭追加`},help:{"v1-s1aimc-1r":`実行時（gateway/sandbox）に PATH の先頭に追加するディレクトリ。`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`実行の審査担当`},help:{"v1-12y548k-4x":`自動モードで、人間による承認にフォールバックする前に使用する、モデルベースの exec レビュアーです。exec レビューをメインエージェントのモデルから分離するには、ここでレビュー専用のモデルの上書き設定を行います。`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`実行レビュアーの高速モード`},help:{"v1-175bx14-8u":`OpenClaw の承認レビュー用の任意の高速モード設定です。true は、対応する OpenAI Responses および ChatGPT/OAuth ルートで優先処理をリクエストし、false は標準処理をリクエストします。プロバイダーのデフォルト設定を維持するには省略してください。高速モードは料金が高くなる場合があり、利用できるかどうかはプロバイダーによって異なります。ネイティブの Codex Guardian は設定しません。`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`exec レビュアーのモデル`},help:{"v1-1lltiy5-3i":`exec レビュアーエージェントのプロバイダーとモデルの任意の上書き設定です。省略すると、対象エージェントに設定されたプライマリモデルを再利用します。`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`実行レビュアーの思考`},help:{"v1-yg2gby-6u":`OpenClaw のモデルを使用した承認レビューにおける、任意の推論労力設定です。minimal、low、medium、high、xhigh、max のいずれかを指定します。プロバイダーのデフォルト設定を維持するには省略してください。対応するレベルは、選択したモデルに合わせて正規化されます。ネイティブの Codex Guardian は設定しません。`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`exec レビュアーのタイムアウト（ミリ秒）`},help:{"v1-1o30chi-3w":`人間による承認にフォールバックするまでの、exec レビュアーのモデル準備と応答生成の各段階のタイムアウト時間（ミリ秒）です（デフォルト：30000）。`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`exec の安全なバイナリプロファイル`},help:{"v1-4cdcwe-29":`安全なバイナリごとに設定できる任意のプロファイルです（位置引数の制限と許可・拒否するフラグ）。`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`exec の安全なバイナリ`},help:{"v1-1of1m2s-21":`標準入力のみを使用する安全なバイナリを、明示的な許可リストへの登録なしで実行できるようにします。`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`exec の安全なバイナリ用の信頼済みディレクトリ`},help:{"v1-zljbcn-2v":`安全なバイナリのパスチェックで信頼する、明示的に指定した追加ディレクトリです（PATH のエントリが自動的に信頼されることはありません）。`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`exec のセキュリティ`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`インライン評価の承認を必須にする`},help:{"v1-jkmgo7-5z":"`python -c`、`node -e`、`ruby -e`、`osascript -e` など、インタープリターのインライン評価形式に明示的な承認を必須とします。許可リストが確認なしに再利用されるのを防ぎ、これらの形式では常に許可する設定を毎回確認する設定に変更します。"}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`実行タイムアウト（秒）`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`ファイルシステムツールをワークスペース内に制限`},help:{"v1-1mhuvka-2s":`ファイルシステムツール（read/write/edit/apply_patch）をワークスペースディレクトリ内に制限します（デフォルト: false）。`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI のアカウントと Git 作成者`},help:{"v1-1fl77im-5s":`エージェントツール用の管理対象ローカル GitHub CLI プロファイルと、任意の Git 作成者情報です。このオブジェクトを省略すると、Gateway の実行ユーザーが元から使用しているアカウントと作成者情報が維持されます。リポジトリのリモート認証情報が上書きされることはありません。`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Git 作成者のメールアドレス`},help:{"v1-kol5g6-1i":`プロセス内でのみ使用する Git 作成者とコミッターのメールアドレス（任意）。`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Git 作成者名`},help:{"v1-z5bl1f-1h":`プロセス内でのみ使用する Git 作成者とコミッターの名前（任意）。`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`GitHub 認証情報の種類`},help:{"v1-qi3qun-3q":`Gateway がローテーションされる更新用認証情報を所有する、管理対象 OAuth プロファイルであることを示します。この項目が省略されたプロファイルでは、個人アクセストークンを使用します。`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub プロファイルのバージョン`},help:{"v1-4lzl0-27":`管理対象の認証情報をアトミックに切り替えるために使用する、生成された不透明なプロファイルバージョンです。`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`リンクの内容理解を有効化`},help:{"v1-23t2io-59":`リンクの内容を自動的に理解する前処理を有効にし、エージェントの推論前に URL の内容を要約できるようにします。より豊富なコンテキストを得るには有効のままにし、処理を厳密に最小限に抑える必要がある場合は無効にしてください。`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`リンク理解の最大リンク数`},help:{"v1-ksxmcv-52":`リンク理解で1ターンあたりに展開するリンクの最大数です。やり取りの多いスレッドで遅延やコストを抑えるには値を小さくし、複数リンクの文脈が重要な場合は値を大きくしてください。`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`リンク理解モデル`},help:{"v1-6j3mnw-5a":`リンク理解タスクで優先するモデルのリストです。対応している場合は、フォールバック候補として順番に評価されます。通常の要約には軽量モデルを優先し、必要な場合のみ高負荷のモデルを使用してください。`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`リンク理解の適用範囲`},help:{"v1-183cwpa-55":`会話の文脈とメッセージの種類に応じて、リンク理解を実行する条件を制御します。リンクを処理する必要のないメッセージで不要な取得が発生しないよう、適用範囲を控えめに設定してください。`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`リンク理解のタイムアウト（秒）`},help:{"v1-61v30o-4p":`リンクごとの理解処理の制限時間（秒）です。時間内に処理できないリンクはスキップされます。外部サイトが遅い場合や到達できない場合に長時間停止しないよう、適切な上限を設定してください。`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`ツールループ検出`},help:{"v1-1e3rls8-5g":`直近の履歴に基づくツールループ検出と、コンパクション後の保護を制御します。省略すると、履歴に基づく検出は無効、コンパクション後の保護は有効のままになります。両方を有効にするには true、両方を無効にするには false を設定してください。`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`音声理解の添付ファイルポリシー`},help:{"v1-1s3t9s5-3o":`条件に一致する音声添付ファイルのうち、処理するものを選択します。複数の添付ファイルを意図的に文字起こしする場合を除き、最初のファイルのみを処理してください。`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`文字起こし結果のエコー形式`},help:{"v1-glpdzh-3i":`{transcript} プレースホルダーを使って、チャットに送信する文字起こしの形式を設定します。送信内容に文字起こしが含まれるように、プレースホルダーはそのまま保持してください。`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`文字起こしをチャットに送信`},help:{"v1-1dedp8c-3r":`エージェントが処理する前に、音声の文字起こしを元のチャットに送信します。システムが聞き取った内容をユーザーが確認する必要がある場合に有効にしてください。`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`音声理解を有効化`},help:{"v1-1v0x7te-2m":`音声理解を有効にして、音声メモや音声クリップを文字起こしし、エージェントのコンテキストとして利用できるようにします。`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`音声理解の言語`},help:{"v1-1ruqt97-3z":`音声文字起こしプロバイダーに渡すデフォルトの言語ヒントです。主に話される言語がわかっていて、プロバイダーの言語検出が信頼できない場合に設定してください。`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`音声理解の最大バイト数`},help:{"v1-1mcckc8-43":`設定済みモデルと自動検出されたモデルに適用する、デフォルトの音声入力サイズ上限です。プロバイダーとネットワークで受け入れ可能な録音の最大サイズに設定してください。`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`音声理解の最大文字数`},help:{"v1-eo1dp-43":`設定済みモデルと自動検出されたモデルに適用する、デフォルトの文字起こしの最大長です。長い音声メモによってエージェントのコンテキストが増大しないようにするには、値を小さくしてください。`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`優先する音声理解モデル`},help:{"v1-1n5zya1-3c":`音声の文字起こしでは、残りの互換性のあるフォールバックよりも先に、機能タグ付きの tools.media.models エントリを1つ優先して使用します。`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`音声理解のプロンプト`},help:{"v1-1v5jtay-4b":`モデルエントリで上書きされていない場合に使用する、音声文字起こしのデフォルトプロンプトです。後続のワークフローが文字起こしのスタイルに依存している場合は、指示を一定に保ってください。`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`音声理解の適用範囲`},help:{"v1-1pptfg0-3w":`チャンネル、チャットの種類、またはソースキーに基づいて音声理解を制限します。自動文字起こしで機密情報を扱う場合やコストが高くなる場合は、適用範囲を狭くしてください。`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`音声理解のタイムアウト（秒）`},help:{"v1-n8wc6c-3b":`音声理解リクエストのデフォルトのタイムアウトです。長時間の録音や処理の遅いローカル文字起こしモデルを使用する場合は、値を大きくしてください。`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`メディア理解の同時実行数`},help:{"v1-13kr9np-58":`画像、音声、動画のタスク全体で、1ターンあたりに同時実行できるメディア理解処理の最大数です。リソースに制約のある環境では、CPUやネットワークの飽和を防ぐため、この値を小さくしてください。`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`画像理解の添付ファイルポリシー`},help:{"v1-11hofbw-3e":`条件に一致する添付画像のうち、処理するものを選択します。複数画像の分析を意図している場合を除き、最初の画像のみを処理してください。`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`画像理解を有効にする`},help:{"v1-1b2zw34-50":`画像理解を有効にすると、添付または参照された画像を解釈し、テキストのコンテキストに変換できます。テキストのみでの動作が必要な場合や、画像処理のコストを避けたい場合は無効にしてください。`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`画像理解の最大バイト数`},help:{"v1-jwwpd1-3v":`設定済みモデルおよび自動検出されたモデルに適用する、画像入力サイズのデフォルトの上限です。プロバイダーのペイロード制限とデプロイ環境の帯域幅に合わせて設定してください。`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`画像理解の最大文字数`},help:{"v1-ebnxhk-3q":`画像の説明のデフォルトの最大文字数です。コンテキストを簡潔にするには小さい値を、詳細なOCRやシーン分析には大きい値を使用してください。`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`画像理解の優先モデル`},help:{"v1-1o2uwo6-3c":`画像理解に使用する際、機能タグ付きのtools.media.modelsエントリを1つ選び、互換性のある他のフォールバック候補より優先します。`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`画像理解のプロンプト`},help:{"v1-1jdcu8b-3u":`エントリで上書きされていない場合に使用する、画像理解のデフォルトのプロンプトです。利用側が一貫した説明に依存する場合は、結果が安定するような内容にしてください。`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`画像理解の適用範囲`},help:{"v1-tievo1-3s":`チャンネル、チャットの種類、またはソースキーで画像理解を制限します。メッセージの多いチャンネルや信頼できないチャンネルでは、処理を制御するために適用範囲を絞ってください。`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`画像理解のタイムアウト（秒）`},help:{"v1-1wcm84x-31":`画像理解リクエストのデフォルトのタイムアウト。大きな画像や処理速度の遅いローカル視覚モデルを使用する場合は、値を増やしてください。`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`メディア理解の共有モデル`},help:{"v1-f34u65-47":`メディア理解モデルの標準リスト。各パイプラインが互換性のあるフォールバックのみを選択するように、すべてのエントリに image、audio、video のいずれかの機能タグを付けてください。`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`動画理解の添付ファイルポリシー`},help:{"v1-1qm1qrc-3e":`条件に一致する添付動画のうち、どれを処理するかを選択します。複数の動画を意図的に分析する場合を除き、最初の動画のみを処理する設定を使用してください。`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`動画理解を有効にする`},help:{"v1-1ltx5gl-58":`動画理解を有効にすると、動画クリップをテキストに要約し、後続の推論や応答に利用できます。動画処理がポリシーで許可されていない場合や、運用環境でのコストが高すぎる場合は無効にしてください。`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`動画理解の最大バイト数`},help:{"v1-2mp77v-3v":`設定済みモデルと自動検出されたモデルに適用される、デフォルトの動画入力サイズ上限。プロバイダーのペイロード上限と運用環境の帯域幅に合わせて設定してください。`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`動画理解の最大文字数`},help:{"v1-1j0x40b-3j":`動画の説明のデフォルトの最大文字数。コンテキストを簡潔にするには小さい値を、シーンの要約を詳しくするには大きい値を使用してください。`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`優先する動画理解モデル`},help:{"v1-1cygq5k-3c":`動画理解では、機能タグが付いた tools.media.models エントリを1つ優先し、残りの互換性のある候補はフォールバックとして使用します。`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`動画理解プロンプト`},help:{"v1-ul2jx4-3r":`エントリで上書きされていない場合に使用する、動画理解のデフォルトプロンプトです。利用側が安定した要約に依存する場合は、結果の一貫性が保たれるようにしてください。`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`動画理解の適用範囲`},help:{"v1-7gfrx3-3s":`チャンネル、チャットの種類、またはソースキーで動画理解を制限します。トラフィックの多いチャンネルや信頼できないチャンネルでは、範囲を絞って処理を制御してください。`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`動画理解のタイムアウト（秒）`},help:{"v1-e8rzsy-33":`動画理解リクエストのデフォルトのタイムアウトです。長いクリップや低速なローカル分析モデルを使用する場合は、値を増やしてください。`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`メッセージアクションの許可リスト`},help:{"v1-1iceqwa-5c":`メッセージツールのグローバルなメッセージアクション許可リストです。ランタイム全体で公開および受け付けるアクションを限定する必要がある場合にのみ使用してください。公開エージェントやサンドボックス化されたエージェントでは、エージェントごとの許可リストを優先してください。`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`メッセージの一斉送信を有効化`},help:{"v1-1ms74z7-14":`一斉送信アクションを有効にします（デフォルト：true）。`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`コンテキストをまたぐ操作を許可（プロバイダー間）`},help:{"v1-276qxo-2s":`異なるプロバイダー間での送信を許可します（デフォルト: true）。プロバイダー間のメッセージ送信をブロックするには、false に設定してください。`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`コンテキスト間の送信を許可（同一プロバイダー）`},help:{"v1-1sg4x49-1z":`同じプロバイダー内の他のチャンネルへの送信を許可します（デフォルト：true）。`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`コンテキスト間送信マーカー`},help:{"v1-1fg6jrp-1z":`コンテキストをまたいで送信する際に、送信元を示すマーカーを表示します（デフォルト：true）。`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`コンテキスト間送信マーカーの接頭辞`},help:{"v1-eblsru-1p":`コンテキスト間送信マーカーの先頭に付けるテキストです（「{channel}」に対応）。`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`コンテキスト間送信マーカーの接尾辞`},help:{"v1-1nk0jub-1p":`コンテキスト間送信マーカーの末尾に付けるテキストです（「{channel}」に対応）。`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`ツールプロファイル`},help:{"v1-h6k98q-5k":`許可・拒否の上書き設定を適用する前に、定義済みのツールポリシーの基本設定を選択するためのグローバルなツールプロファイル名です。エージェント間で一貫した環境設定を維持するために使用し、プロファイル名は固定してください。`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`サンドボックスのツールポリシー`},help:{"v1-ea7awo-4k":`サンドボックス内でのエージェント実行に適用するツールポリシーのラッパーです。サンドボックスでの実行に独自の機能制限を設定できます。サンドボックス環境でより強固な安全性を確保するために使用してください。`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`サンドボックスのツール許可・拒否ポリシー`},help:{"v1-ub701o-4t":`エージェントがサンドボックス化された実行環境で動作する際に適用される、ツールの許可・拒否ポリシーです。サンドボックス内のタスクが不要な外部操作にまで拡大しないよう、ポリシーで許可する範囲を最小限に抑えてください。`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`セッションツールの可視範囲`},help:{"v1-1vtq2rh-c5":`sessions_list/sessions_history/sessions_search/sessions_send/session_status の対象にできるセッションを制御します（デフォルトの "all" = 他のエージェントやユーザーを含む Gateway 上のすべてのセッション、"agent" = 現在のエージェント ID に属するすべてのセッション、"self" = 現在のセッションのみ、"tree" = 現在のセッションと、生成されたサブエージェントのセッション）。エージェント間のアクセスはデフォルトで有効で、tools.agentToAgent によって範囲が定められます。アクセスを制限するには、可視範囲を狭くしてください。`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`サブエージェントのツールポリシー`},help:{"v1-1xoug01-4z":`生成されたサブエージェントに適用するツールポリシーのラッパーです。親のデフォルト設定と比較して、利用可能なツールを制限または拡張します。委任先エージェントの機能をタスクの目的に沿った範囲に保つために使用します。`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`サブエージェントのツール許可／拒否ポリシー`},help:{"v1-7vxsbf-5d":`生成されたサブエージェントのランタイムに適用される、ツールの許可／拒否ポリシーです。親よりも狭い範囲に設定してください。progress_card などの親が所有するツールは、allow/alsoAllow で指定しても常に拒否されます。`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`スウォーム`},help:{"v1-1q96vvs-45":`コレクターモードのサブエージェントオーケストレーションです。デフォルトで有効です。無効にするには false に設定してください。agents_wait とスウォームの生成オプションには、引き続きツールの権限が適用されます。`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`スウォームのデフォルトエージェント`},help:{"v1-p4alpg-2m":`agentId を省略してスウォームを生成する場合の、デフォルトの対象エージェントです。サブエージェントの許可リストは引き続き適用されます。`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`スウォームを有効にする`},help:{"v1-1nnnrq9-2e":`コレクターモードのサブエージェントと agents_wait を有効にします。デフォルトで有効です。無効にするには false に設定してください。`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`スウォームのグループあたりの稼働中の子数`},help:{"v1-kfx6qp-1c":`スウォームグループごとの稼働中のコレクターの子の最大数。`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`スウォームの同時実行の子数`},help:{"v1-1d46jtm-1s":`スウォームグループごとの同時実行中のコレクターの子の最大数。`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`スウォームのグループあたりの子の総数`},help:{"v1-1gc9vl1-1e":`スウォームグループの存続期間全体で生成できるコレクターの最大数。`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`スウォームの最大待機タイムアウト`},help:{"v1-bog18y-1g":`agents_wait が受け付ける最大タイムアウト（秒）。`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`ツール検索`},help:{"v1-s0kx04-7y":`OpenClaw、MCP、クライアントの大規模なツールカタログをコンパクトにします。未設定の場合、OpenClawランタイムは構造化されたTool Searchを自動的に使用します。Code Modeが有効な場合はそちらが優先され、Codexはネイティブの検索を使用します。無効にするにはfalse、コードブリッジを使用するにはtrueを設定するか、オブジェクト形式でモードを選択してください。`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`ツール検索のコードタイムアウト`},help:{"v1-105r499-34":"`tool_search_code` の1回の実行に許可される最大時間（ミリ秒）。ランタイムは値をサポート範囲の1秒〜60秒に制限します。"}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`ツール検索を有効にする`},help:{"v1-1vm3hfr-4h":"ツール検索を有効にします。有効にすると、OpenClaw は組み込みランタイムでの実行中、大規模なツールカタログを直接公開せず、`tool_search_code` または構造化された検索・説明・呼び出しツールを介してアクセスできるようにします。"}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`ツール検索の最大結果数`},help:{"v1-7du4kh-32":`モデルが要求できるツール検索結果の最大件数。実行時に、サポートされている1..50の範囲に値が制限されます。`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`ツール検索の公開方式`},help:{"v1-jybcbe-7x":'モデルに公開する方式を選択します。"code" は `tool_search_code` を公開します。"tools" は検索・説明取得・呼び出し用の構造化されたフォールバックツールを公開します。"directory" は件数を制限したツールディレクトリを常に表示し、使用する可能性が高いスキーマや必須のスキーマを一定数公開します。それ以外は検索・説明取得・呼び出しを通じて必要に応じて利用できます。'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`ツール検索のデフォルト結果件数`},help:{"v1-1uchq7t-39":"モデルが件数の上限を省略した場合に返されるツール検索結果のデフォルト件数。実行時に `maxSearchLimit` 以下に制限されます。"}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`構造化計画ツールを有効にする`},help:{"v1-1xgegme-4o":"親セッションで永続的な計画と記述形式のメモを扱うための統合ステータスツール `progress_card`。デフォルトで有効です。無効にするには false を設定します。サブエージェントは常に利用できません。"}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Webツール`},help:{"v1-fpsy5-4y":`検索・取得プロバイダー、制限、フォールバック動作を調整するためのWebツールのポリシー設定グループ。有効にする設定は、APIキーの利用可否および外向き通信のポリシーと整合させてください。`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`Web取得キャッシュのTTL（分）`},help:{"v1-1hk89qp-17":`web_fetch の結果のキャッシュTTL（分単位）。`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Web取得ツールを有効にする`},help:{"v1-yrswld-1f":`web_fetch ツール（軽量なHTTP取得）を有効にします。`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`ウェブ取得のリクエストヘッダー`},help:{"v1-16bjkv5-me":"直接の web_fetch リクエストで送信する追加のリクエストヘッダーです。たとえば、ゲートウェイのルーティングヘッダーや認証ヘッダーなどを指定します。設定された値はすべて機密情報として扱われ、公開される設定やデバッグキャプチャではマスクされます。値はプレーンな文字列で、${VAR} による置換と、全体で使用できるリテラルエスケープ $${VAR} をサポートし、モデルが選択した URL に送信されます。各エントリは設定の読み込み時ではなくリクエストの構築時に検証されるため、名前が不正な場合や値を送信できない場合は、機能を無効にするのではなく、そのエントリを除外してログに記録します。Accept、Accept-Language、User-Agent、および Transfer-Encoding などのフレーミングヘッダーも除外されます。ユーザーエージェントを変更するには tools.web.fetch.userAgent を使用してください。クロスオリジンのリダイレクトでは、guarded-fetch の安全なヘッダー許可リストに含まれるヘッダーのみが保持されます。また、実際に送信されるヘッダーを変更すると、取得キャッシュが分割されます。"}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`ウェブ取得の最大文字数`},help:{"v1-12d1fw7-1d":`web_fetch が返す最大文字数です（超過分は切り捨てられます）。`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`ウェブ取得の文字数の絶対上限`},help:{"v1-cl2mf1-1v":`web_fetch の maxChars の絶対上限です（設定とツール呼び出しに適用されます）。`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`ウェブ取得の最大リダイレクト回数`},help:{"v1-t6eak9-1h":`web_fetch で許可されるリダイレクトの最大回数です（デフォルト：3）。`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`ウェブ取得の最大ダウンロードサイズ（バイト）`},help:{"v1-q6ld9c-10":`切り捨てが行われるまでの最大ダウンロードサイズです。`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`ウェブ取得プロバイダー`},help:{"v1-6pb3nv-v":`ウェブ取得のフォールバックプロバイダーID。`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`ウェブ取得のReadability抽出`},help:{"v1-19exqzx-2c":`Readabilityを使用してHTMLからメインコンテンツを抽出します（基本的なHTMLクリーンアップにフォールバックします）。`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`ウェブ取得のSSRFポリシー`},help:{"v1-qtn7zx-3c":`web_fetchに適用する、範囲を限定したSSRFポリシーの上書き設定です。適用範囲を狭く保ち、既知のローカルネットワークのプロキシ環境でのみ有効にしてください。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`ウェブ取得で許可するホスト名`},help:{"v1-1j9ctya-35":`web_fetchで許可する完全一致のホスト名またはIPリテラルです。通常はブロックされる対象も含まれます。リストは必要最小限にしてください。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`ウェブ取得でIPv6ユニークローカル範囲を許可`},help:{"v1-1eyz55i-3b":`sing-box、Clash、Surgeなどの信頼できるfake-IPプロキシとの互換性を確保するため、IPv6ユニークローカルアドレス（fc00::/7）を許可します。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`ウェブ取得でRFC 2544ベンチマーク範囲を許可`},help:{"v1-u5asdb-2y":`ClashやSurgeなどのfake-IPプロキシとの互換性を確保するため、RFC 2544ベンチマーク範囲のIPアドレス（198.18.0.0/15）を許可します。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`ウェブ取得でブロックするホスト名`},help:{"v1-1164vvk-66":`web_fetch の各リダイレクトで、DNS 解決と許可ルールの適用前に拒否するホスト名パターンです。完全一致のホスト名と、サブドメインのみに一致する "*.example.com" をサポートします。頂点ドメインもブロックするには、"example.com" を別途追加してください。空または未設定の場合、拒否は追加されません。`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`ウェブ取得でプライベートネットワークを許可（危険）`},help:{"v1-2s6mv7-3t":`web_fetch によるプライベートネットワークおよび内部ネットワークへのアクセスを許可します。このデプロイ環境でモデルが選択する URL を信頼できる場合を除き、無効のままにしてください。`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`ウェブ取得のタイムアウト（秒）`},help:{"v1-1c3yfr4-16":`web_fetch リクエストのタイムアウト（秒単位）です。`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`ウェブ取得の User-Agent`},help:{"v1-s7pe8j-1e":`web_fetch リクエストの User-Agent ヘッダーを上書きします。`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`ウェブ取得の信頼できる環境変数プロキシ`},help:{"v1-1ypkqj7-54":`環境変数で指定された信頼できる HTTP(S) プロキシを経由して web_fetch を実行し、DNS 解決をプロキシに任せます。そのプロキシが運用者の管理下にあり、DNS 解決後にアウトバウンドポリシーを適用する場合にのみ有効にしてください。`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`ウェブ検索のキャッシュ TTL（分）`},help:{"v1-6trzlf-18":`web_search 結果のキャッシュ TTL（分単位）です。`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`ウェブ検索ツールを有効化`},help:{"v1-n1cm4y-27":`管理対象の web_search と、対応モデルで利用できるオプションの Codex ネイティブ検索を有効にします。`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`ウェブ検索の最大結果数`},help:{"v1-mrw7mi-z":`返す結果の数（1～10）。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Codexの許可ドメイン`},help:{"v1-1cv4y44-43":`ネイティブCodexのweb_search用ドメイン許可リスト。ネイティブホスト型検索を使用するターンでは、マネージドweb_fetchにもこの制限が適用されます。マネージドプロバイダーを使用するターンには影響しません。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Codex検索のコンテキストサイズ`},help:{"v1-antack-1u":`ネイティブCodex検索のコンテキストサイズのヒント："low"、"medium"、"high"。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`ネイティブCodexウェブ検索を有効にする`},help:{"v1-ek2jzd-1k":`Codex対応モデルでネイティブCodexウェブ検索を有効にします。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Codexウェブ検索モード`},help:{"v1-1ahyq9f-32":`ネイティブCodexウェブ検索の優先設定："cached"（デフォルト。制限のないCodexターンでは"live"として扱われます）または"live"。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Codexユーザーの都市`},help:{"v1-1y95orp-1d":`ネイティブCodexウェブ検索に送信するおおよその都市情報。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Codexユーザーの国`},help:{"v1-1xkm5ms-1g":`ネイティブCodexウェブ検索に送信するおおよその国情報。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Codexユーザーの地域`},help:{"v1-lhar02-1l":`CodexのネイティブWeb検索に送信するおおよその地域・州。`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Codexユーザーのタイムゾーン`},help:{"v1-fgv9fh-1h":`CodexのネイティブWeb検索に送信するおおよそのタイムゾーン。`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Web検索プロバイダー`},help:{"v1-10omglr-1x":`検索プロバイダーのID。省略すると、利用可能なAPIキーから自動検出されます。`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Web検索のタイムアウト（秒）`},help:{"v1-i0egvw-17":`web_searchリクエストのタイムアウト（秒単位）。`}},transcripts:{label:{"v1-1iqk6o8-b":`文字起こし`},help:{"v1-1i0sc09-66":`会議メモ、録音対応のエージェントツール、および設定済みのライブ会議自動開始ソースに関する、文字起こしの基本取得設定。会議プラグインはデフォルトでメモを永続的に保存します。全体で無効にするには、enabledをfalseに設定してください。`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`文字起こしの自動開始ソース`},help:{"v1-1mzsl79-5s":`Gatewayの起動時から自動管理されるライブ文字起こしソース。各エントリは存在するだけで有効になります。ソースを無効にするには、そのエントリを削除してください。whenOccupiedが有効でない限り、ソースは継続的に文字起こしを取得します。`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`文字起こしのアカウントID`},help:{"v1-6g2kjj-4b":`アカウントの識別が必要な文字起こしソースに使用する、任意のプロバイダーアカウントまたはワークスペースの識別子。プロバイダーのドキュメントに記載されたアカウントID形式を使用してください。`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`文字起こしのチャンネルID`},help:{"v1-1lk9d5o-4u":`DiscordのボイスチャンネルやSlackのハドルチャンネルなど、ライブ文字起こしソースのプロバイダー側チャンネルIDです。自動開始を有効にする前に、プロバイダー固有のIDの意味を確認してください。`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`DiscordギルドID`},help:{"v1-fyfgnk-4l":`Discord音声文字起こしソース用の任意のDiscordギルドIDです。プロバイダーがギルド内のボイスチャンネルを検索する必要がある場合は、対応するchannelIdとともに設定してください。`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`文字起こし対象の会議URL`},help:{"v1-1xtt9ci-4f":`チャンネルIDではなくURLで参加するプロバイダー用の任意の会議URLです。自動開始によってその会議に参加し、内容を記録する可能性があるため、信頼できる会議リンクのみを使用してください。`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`文字起こしソースのプロバイダーID`},help:{"v1-1uur06p-3s":`Discord音声プロバイダーや今後対応予定のSlackハドルプロバイダーなど、文字起こしソースのプロバイダーIDです。プロバイダープラグインが公開する正確なIDを使用してください。`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`文字起こしセッションID`},help:{"v1-xyo4x5-5o":`この自動開始ソース用の任意の固定文字起こしセッションIDです。whenOccupiedがtrueの場合は無視されます。日単位で固定のセレクターが必要で、同日内の競合を回避できる場合を除き、未設定のままにして自動生成されるIDを使用してください。`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`文字起こしのタイトル`},help:{"v1-ycjnmp-5y":`今後の文字起こし収録に使用する任意のタイトルです。タイトルのみを変更した場合、現在の収録は継続され、開始時に確定したタイトルや保存済みのノートの名前は変更されません。ソースのその他の変更には、通常どおり再起動処理が適用されます。`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`参加者がいる場合に文字起こしを収録`},help:{"v1-34jid4-78":`ソースに人間の参加者が入るたびに新しい文字起こしセッションを開始し、最後の参加者が退出すると停止してノートを生成します。discord-voice など、参加状況を報告するプロバイダーが必要です。デフォルト: false（Gateway の起動時から継続的に収録）。`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`文字起こしを有効化`},help:{"v1-fyqqr0-6d":`永続保存される自動会議ノート、transcripts エージェントツール、および設定済みの自動開始ソースを有効にします。デフォルト: true。false に設定すると、永続保存とツールが無効になります。明示的に指定した会議の文字起こしモードでは、直近のライブデータが一定の範囲内で保持されます。`}},tts:{label:{"v1-bmxkk9-e":`テキスト読み上げ`},help:{"v1-1o27tk2-4n":`対応する音声インターフェースでエージェントの返信を読み上げるためのテキスト読み上げポリシーです。音声再生が運用者またはユーザーのワークフローに含まれていない限り、無効のままにしてください。`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS ペルソナ`},help:{"v1-1r0opcb-29":`デフォルトの TTS ペルソナ ID です。ローカルの TTS ペルソナ設定で、ホストごとに上書きできます。`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS ペルソナ一覧`},help:{"v1-19aybhl-2l":`一貫した話し声の個性と、プロバイダー固有の音声設定の紐付けを定義する、名前付きの TTS ペルソナです。`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS ペルソナ`},help:{"v1-10s52ah-2l":`個別の TTS ペルソナです。特定の音声、モデル、プロンプトテンプレートを指定するには、プロバイダー固有の紐付け設定を使用してください。`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`TTS ペルソナのプロバイダー紐付け`},help:{"v1-993jop-3e":`音声プロバイダー ID をキーとする、プロバイダー固有の TTS ペルソナの紐付けです。有効なペルソナでは、これらが tts.providers に上書きマージされます。`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`TTS プロバイダー設定`},help:{"v1-1k80nl4-4y":`音声プロバイダー ID をキーとする、プロバイダー固有の TTS 設定です。音声プラグインをコア設定スキーマから独立させるため、組み込みのプロバイダー固有のトップレベルキーではなく、この設定を使用してください。`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`TTS プロバイダー構成`},help:{"v1-dwapva-3d":`単一の音声プロバイダー ID に対する、プロバイダー固有の TTS 構成です。フィールドは、そのプロバイダーを所有するプラグインの範囲内に限定してください。`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`TTS プロバイダー API キー`},help:{"v1-1m2fj0i-2o":`プラグインが認証付きの TTS アクセスを必要とする場合に、その音声プロバイダーが使用するプロバイダー API キーです。`}},tui:{label:{"v1-c8hus1-b":`ターミナル UI`},help:{"v1-1fg9vw2-3s":`ターミナル UI の表示設定です。Gateway や他の UI の動作を変更せずに、ターミナル専用の表示を調整するには、このセクションを使用してください。`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`ターミナル UI フッター`},help:{"v1-6e12l3-3k":`ターミナル UI のフッター表示設定です。セッション、モデル、目標、トークンの情報が読みやすいように、任意の補足情報はコンパクトにまとめてください。`}},ui:{label:{"v1-ye4dff-2":`UI`},help:{"v1-dt1924-42":`アクセントやオペレーターの表示設定に関する UI 設定です。実行時の動作を変更せずに、読みやすさをカスタマイズするために使用してください。`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`ユーザーのアクセントカラー`},help:{"v1-16klzws-4z":`Control UI のアクセント色：カスタム色には #RRGGBB、選択したテーマのパレットには 'theme' を指定します。ui.seamColor を上書きします。設定済みの境界色またはテーマのデフォルトを継承するには、この値をクリアしてください。`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`アクセントカラー`},help:{"v1-14q3r4h-4g":`UI の各画面で強調、バッジ、視覚的な識別に使うメインのアクセントカラー。ライトテーマとダークテーマのどちらでも読みやすい、高コントラストの色を使用してください。`}},update:{label:{"v1-k12u1x-7":`更新`},help:{"v1-11c5k8v-5c":`OpenClaw ランタイムを最新のバージョンに保つための更新チャネルと起動時チェックの動作。本番環境では安定性を重視したチャネルを使用し、実験的なチャネルは管理された環境でのみ使用してください。`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`自動更新を有効化`},help:{"v1-49xs2h-3c":`stable および beta のパッケージインストールで、バックグラウンドでの自動更新を有効にします。extended-stable では自動適用されません（既定値：false）。`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`更新チャネル`},help:{"v1-lqtdvf-5b":`git + npm インストールの更新チャネル（"stable"、"extended-stable"、"beta"、"dev"）。extended-stable はパッケージ専用です。インストールはフォアグラウンドでのみ行われ、必要に応じて起動時に読み取り専用のヒントを表示できます。`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`起動時に更新を確認`},help:{"v1-qy3q9g-5v":`Gatewayの起動時に、読み取り専用のextended-stableの更新案内を含め、更新を確認します（デフォルト：true）。Gatewayとヘッドレスノードの自動更新の確認・適用、および匿名の更新通知送信を無効にするには、falseを設定します。`}},voicewake:{label:{"v1-txt1wb-a":`音声起動`}},web:{label:{"v1-1ae9z56-b":`Web チャネル`}},wizard:{label:{"v1-28jonk-h":`セットアップ設定`},help:{"v1-14jh6rm-3b":`ユーザーが管理するセットアップ設定。マシンが管理するウィザードの履歴と確認済み状態は、共有状態データベースに保存されます。`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`セットアップ時の検出アクセス`},help:{"v1-1nqxt0w-38":`ガイド付きセットアップでの検出に関する同意設定です。"full" は確認なしでスキャンし、"guarded" はローカルアプリケーションを調べる前に確認します。`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`セットアップ時のアプリの推奨`},help:{"v1-ub8uoi-30":`ガイド付きセットアップで、インストール済みアプリケーションのラベルを使用して関連するプラグインやスキルを推奨できるかどうかを制御します。`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`ウィザードの最終実行日時`},help:{"v1-1y0fbk-1k":`結果が正常に保存された、直近のウィザード実行のタイムスタンプです。`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`ウィザードの最終実行コマンド`},help:{"v1-x2pfkk-15":`前回のウィザード実行を呼び出したコマンドです。`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`ウィザードの最終実行コミット`},help:{"v1-h0jkmt-1i":`前回の開発版ウィザード実行で使用されたソースコミットです。`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`ウィザードの最終実行モード`},help:{"v1-16508qy-1r":`前回のウィザード実行が "local" と "remote" のどちらのセットアップを対象としていたかを示します。`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`ウィザードの最終実行バージョン`},help:{"v1-1tr4z9d-19":`前回のウィザード実行で使用された OpenClaw のバージョンです。`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`ウィザードのセキュリティ確認日時`},help:{"v1-86i182-2a":`セットアップ時のセキュリティ確認のタイムスタンプです。対象の設定とともに保存されます。`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`ワークツリーの高速化`},help:{"v1-9es3gc-4r":`対応している場合、新しい管理対象ワークツリーにファイルシステムの高速化機能を使用します（デフォルト: true）。通常の Git チェックアウトとファイルコピーを使用するには、false に設定してください。新しいワークツリーにのみ適用されます。`}},worktreeRoot:{label:{"v1-bqutg0-d":`ワークツリーのルート`},help:{"v1-1tgti9j-5d":`新しい管理対象ワークツリー用のグローバルディレクトリです。絶対パスを指定するか、ホームディレクトリを表す ~ を使用してください。デフォルトは <state-dir>/worktrees です。この設定を変更しても、既存のワークツリーには記録済みのパスが引き続き使用されます。`}}}}})))()}export{t as n,n as t};